// Deterministic, authoritative boxing simulation with stamina, guard, counters, knockdowns and judges.
import { clamp } from '../core/rng.js';
import { STYLE_BY_ID } from '../core/data.js';

export const PUNCHES = {
  jab: { id: 'jab', name: 'Jab', short: 'J', damage: 4.2, stamina: 4.5, dur: 0.30, impactAt: 0.42, range: 0.30, accuracy: 0.10, stun: 0.10, guardBreak: 5, score: 1, hand: 'L' },
  cross: { id: 'cross', name: 'Direto', short: 'K', damage: 8.6, stamina: 9, dur: 0.44, impactAt: 0.44, range: 0.22, accuracy: 0.02, stun: 0.2, guardBreak: 12, score: 2, hand: 'R' },
  hook: { id: 'hook', name: 'Gancho', short: 'L', damage: 10.4, stamina: 11.5, dur: 0.48, impactAt: 0.47, range: 0.12, accuracy: -0.02, stun: 0.26, guardBreak: 16, score: 2, hand: 'R' },
  uppercut: { id: 'uppercut', name: 'Uppercut', short: 'I', damage: 13.2, stamina: 14.5, dur: 0.55, impactAt: 0.5, range: 0.10, accuracy: -0.04, stun: 0.34, guardBreak: 22, score: 3, hand: 'R' },
  body: { id: 'body', name: 'Corpo', short: 'B', damage: 7.2, stamina: 9, dur: 0.42, impactAt: 0.45, range: 0.14, accuracy: 0.04, stun: 0.12, guardBreak: 10, score: 2, hand: 'L' },
};

const RING_LIMIT = 2.58;
const START_DISTANCE = 1.62;

function attr(attrs, key, fallback = 55) {
  return attrs?.[key] ?? fallback;
}

export class FightEngine {
  constructor(config = {}) {
    this.config = {
      rounds: 3,
      roundTime: 60,
      mode: 'career',
      difficulty: 'pro',
      seed: Date.now() % 100000,
      ...config,
    };
    this.phase = 'intro';
    this.phaseTime = 0;
    this.clock = this.config.roundTime;
    this.round = 1;
    this.timeScale = 1;
    this.events = [];
    this.finished = false;
    this.result = null;
    this.heat = 0.25;
    this.tick = 0;
    this.slowmoTimer = 0;
    this.started = false;
    this.fighters = [this.makeFighter(config.p1, 'p1'), this.makeFighter(config.p2, 'p2')];
    this.fighters[0].pos = { x: -0.06, z: START_DISTANCE / 2 };
    this.fighters[1].pos = { x: 0.06, z: -START_DISTANCE / 2 };
    this.fighters[0].facing = Math.PI;
    this.fighters[1].facing = 0;
    this.judges = [
      { name: 'Juiz Almeida', bias: 0.0, scores: [0, 0], rounds: [] },
      { name: 'Juiz Tanaka', bias: 0.04, scores: [0, 0], rounds: [] },
      { name: 'Juiz Carter', bias: -0.04, scores: [0, 0], rounds: [] },
    ];
    this.roundDamage = [0, 0];
    this.punchRequests = { p1: null, p2: null };
    this.remoteInput = null;
    this.ai = { p1: config.ai1 ? new BoxingAI(this, 0, config.difficulty) : null, p2: config.ai2 ? new BoxingAI(this, 1, config.difficulty) : null };
    this.emit('intro');
  }

  makeFighter(def = {}, slot) {
    const attrs = def.attributes || {};
    const h = 100 + Math.round((attr(attrs, 'conditioning') - 50) * 0.35);
    return {
      id: slot,
      def,
      isPlayer: !!def.isPlayer,
      name: def.name || (slot === 'p1' ? 'Lutador 1' : 'Lutador 2'),
      nick: def.nick || '',
      style: def.style || 'technical',
      attributes: attrs,
      appearance: def.appearance || null,
      hp: h, maxHp: h,
      stamina: 100, maxStamina: 100,
      guard: 100,
      pos: { x: 0, z: 0 },
      facing: slot === 'p1' ? Math.PI : 0,
      vx: 0, vz: 0,
      moveX: 0, moveZ: 0,
      blocking: false,
      blockingTime: 0,
      action: null,
      cooldown: 0,
      stun: 0,
      dodge: { active: false, time: 0, dir: 1, cooldown: 0 },
      counterWindow: 0,
      lastCounterAt: -10,
      knockdowns: 0,
      down: null,
      combo: 0,
      lastHitAt: -10,
      stats: { thrown: 0, landed: 0, damage: 0, blocks: 0, dodges: 0, counters: 0, maxCombo: 0, jabs: 0, power: 0, distance: 0 },
      roundDamage: 0,
      scorecards: [],
      hurtFlash: 0,
      expression: 'neutral',
      tauntCd: 4,
      victory: false,
      defeated: false,
      aiCooldown: 0.4 + Math.random() * 0.3,
    };
  }

  start() {
    if (this.started) return;
    this.started = true;
    this.phase = 'fight';
    this.phaseTime = 0;
    this.emit('bell');
    this.emit('roundStart', { round: 1 });
  }

  update(dt, inputs = {}) {
    if (!this.started) return;
    this.tick++;
    const scaled = dt * this.timeScale;
    this.phaseTime += scaled;
    for (const f of this.fighters) {
      f.cooldown = Math.max(0, f.cooldown - scaled);
      f.stun = Math.max(0, f.stun - scaled);
      f.dodge.cooldown = Math.max(0, f.dodge.cooldown - scaled);
      f.dodge.time = Math.max(0, f.dodge.time - scaled);
      if (f.dodge.time <= 0) f.dodge.active = false;
      f.counterWindow = Math.max(0, f.counterWindow - scaled);
      f.hurtFlash = Math.max(0, f.hurtFlash - scaled);
      f.tauntCd = Math.max(0, f.tauntCd - scaled);
    }
    if (this.slowmoTimer > 0) {
      this.slowmoTimer -= dt;
      if (this.slowmoTimer <= 0) this.timeScale = 1;
    }

    if (this.phase === 'fight') {
      this.updateFight(scaled, inputs);
    } else if (this.phase === 'knockdown') {
      this.updateKnockdown(scaled, inputs);
    } else if (this.phase === 'roundEnd') {
      if (this.phaseTime > 3.0) this.nextRound();
    } else if (this.phase === 'ko') {
      if (this.phaseTime > 4.2) this.finishKo();
    }
  }

  updateFight(dt, inputs) {
    this.clock -= dt;
    const p1In = this.normalizeInput(inputs.p1, 'p1');
    const p2In = this.normalizeInput(inputs.p2, 'p2');
    // AI overrides its slot.
    const a0 = this.ai.p1 ? this.ai.p1.think(dt) : null;
    const a1 = this.ai.p2 ? this.ai.p2.think(dt) : null;
    const in0 = a0 || p1In;
    const in1 = a1 || p2In;
    this.punchRequests.p1 = in0?.punch || null;
    this.punchRequests.p2 = in1?.punch || null;
    this.stepFighter(this.fighters[0], in0, this.fighters[1], dt);
    this.stepFighter(this.fighters[1], in1, this.fighters[0], dt);
    this.separate();
    this.updateHeat(dt);

    if (this.clock <= 0) {
      this.clock = 0;
      this.endRound();
    }
  }

  normalizeInput(input, slot) {
    const base = { moveX: 0, moveZ: 0, block: false, dodge: false, punch: null };
    if (!input) return base;
    return {
      moveX: clamp(input.moveX || 0, -1, 1),
      moveZ: clamp(input.moveZ || 0, -1, 1),
      block: !!input.block,
      dodge: !!input.dodge,
      punch: input.punch || null,
    };
  }

  setRemoteInput(input) {
    this.remoteInput = input;
    this.remoteInputTime = performance.now();
  }

  stepFighter(f, input, opp, dt) {
    if (!f || !opp) return;
    f.moveX = input.moveX;
    f.moveZ = input.moveZ;
    f.blocking = input.block && !f.action && !f.dodge.active && f.stun <= 0;
    f.expression = f.stun > 0 ? 'hurt' : f.stamina < 25 ? 'tired' : f.action ? 'focused' : 'neutral';

    if (f.stun > 0) {
      f.blocking = false;
      this.applyMovement(f, opp, 0, 0, dt, true);
      return;
    }

    // Dodge
    if (input.dodge && !f.dodge.active && f.dodge.cooldown <= 0 && f.stamina > 8 && !f.action) {
      f.dodge.active = true;
      f.dodge.time = 0.36;
      f.dodge.dir = Math.abs(input.moveX) > 0.1 ? Math.sign(input.moveX) : (Math.random() < 0.5 ? -1 : 1);
      f.dodge.cooldown = 0.9;
      f.stamina = Math.max(0, f.stamina - 9);
      this.emit('dodge', { id: f.id, dir: f.dodge.dir });
    }

    if (f.dodge.active) {
      f.blocking = false;
      this.applyMovement(f, opp, f.dodge.dir * 1.8, 0, dt, true);
      // Grant counter timing in the back half of the dodge.
      if (f.dodge.time > 0.05 && f.dodge.time < 0.3) f.counterWindow = Math.max(f.counterWindow, 0.22);
      return;
    }

    // Start punch
    const req = this.punchRequests[f.id];
    if (req && PUNCHES[req] && !f.action && f.cooldown <= 0 && !f.blocking) {
      this.startPunch(f, opp, req);
    }

    // Advance punch
    if (f.action) {
      const act = f.action;
      act.time += dt;
      if (!act.resolved && act.time >= act.def.impactAt * act.def.dur) {
        act.resolved = true;
        this.resolvePunch(f, opp, act);
      }
      if (act.time >= act.def.dur) {
        f.action = null;
        f.cooldown = 0.08;
      }
      this.applyMovement(f, opp, input.moveX * 0.22, input.moveZ * 0.22, dt, false);
      return;
    }

    // Movement and stamina
    if (!f.blocking) {
      this.applyMovement(f, opp, input.moveX, input.moveZ, dt, false);
    } else {
      this.applyMovement(f, opp, input.moveX * 0.3, input.moveZ * 0.3, dt, false);
      f.blockingTime += dt;
      f.guard = Math.max(0, f.guard - dt * 1.4);
      if (f.guard <= 0) {
        f.stun = Math.max(f.stun, 1.1);
        f.guard = 12;
        f.blocking = false;
        this.emit('guardBreak', { id: f.id });
      }
    }

    // Stamina economy
    const moving = Math.abs(input.moveX) + Math.abs(input.moveZ) > 0.15;
    const cond = attr(f.attributes, 'conditioning', 55);
    const regen = (f.blocking ? 2.2 : moving ? 3.6 : 5.4) * (0.7 + cond / 160);
    if (!f.action) f.stamina = Math.min(f.maxStamina, f.stamina + regen * dt);
    if (!f.blocking) f.guard = Math.min(100, f.guard + dt * 7);
    if (f.stamina <= 0.5) f.expression = 'tired';

    // Reset combo
    if (this.timeSinceHit(f, opp) > 1.6 && f.combo > 0) f.combo = 0;
  }

  applyMovement(f, opp, x, z, dt, locked) {
    const dx = opp.pos.x - f.pos.x;
    const dz = opp.pos.z - f.pos.z;
    const dist = Math.max(0.001, Math.hypot(dx, dz));
    const dirx = dx / dist, dirz = dz / dist;
    const px = -dirz, pz = dirx;
    const mobility = attr(f.attributes, 'mobility', 55);
    const style = STYLE_BY_ID[f.style]?.modifiers || {};
    const fatigue = f.stamina < 25 ? 0.72 : 1;
    let speed = (1.45 + mobility / 100 * 1.0) * (style.speed || 1) * fatigue;
    if (locked) speed *= 1.3;
    if (f.blocking) speed *= 0.4;
    if (f.stun > 0) speed *= 0.2;
    f.vx = (dirx * z + px * x) * speed;
    f.vz = (dirz * z + pz * x) * speed;
    f.pos.x = clamp(f.pos.x + f.vx * dt, -RING_LIMIT, RING_LIMIT);
    f.pos.z = clamp(f.pos.z + f.vz * dt, -RING_LIMIT, RING_LIMIT);
    f.stats.distance += Math.hypot(f.vx * dt, f.vz * dt);
    const ndx = opp.pos.x - f.pos.x;
    const ndz = opp.pos.z - f.pos.z;
    f.facing = Math.atan2(ndx, ndz);
    f.distance = Math.hypot(ndx, ndz);
  }

  separate() {
    const [a, b] = this.fighters;
    const dx = b.pos.x - a.pos.x;
    const dz = b.pos.z - a.pos.z;
    const dist = Math.max(0.0001, Math.hypot(dx, dz));
    const min = 0.78;
    if (dist < min) {
      const push = (min - dist) / 2;
      const nx = dx / dist, nz = dz / dist;
      a.pos.x = clamp(a.pos.x - nx * push, -RING_LIMIT, RING_LIMIT);
      a.pos.z = clamp(a.pos.z - nz * push, -RING_LIMIT, RING_LIMIT);
      b.pos.x = clamp(b.pos.x + nx * push, -RING_LIMIT, RING_LIMIT);
      b.pos.z = clamp(b.pos.z + nz * push, -RING_LIMIT, RING_LIMIT);
    }
    a.facing = Math.atan2(b.pos.x - a.pos.x, b.pos.z - a.pos.z);
    b.facing = Math.atan2(a.pos.x - b.pos.x, a.pos.z - b.pos.z);
  }

  startPunch(f, opp, type) {
    const def = PUNCHES[type];
    if (!def || f.stamina < def.stamina * 0.6) return false;
    f.action = { type, def, time: 0, resolved: false, counter: f.counterWindow > 0 };
    f.stamina = Math.max(0, f.stamina - def.stamina);
    f.stats.thrown++;
    if (def.hand === 'L') f.stats.jabs++;
    else f.stats.power++;
    f.counterWindow = 0;
    this.emit('punch', { id: f.id, type, counter: f.action.counter });
    return true;
  }

  resolvePunch(attacker, defender, act) {
    const def = act.def;
    const dist = attacker.distance || Math.hypot(defender.pos.x - attacker.pos.x, defender.pos.z - attacker.pos.z);
    const reachBonus = (attr(attacker.attributes, 'mobility', 50) - 50) * 0.001;
    const maxRange = 1.48 + def.range + reachBonus + (attacker.attributes && attacker.attributes.reach ? 0 : 0);
    const stats = attacker.stats;
    const style = STYLE_BY_ID[attacker.style]?.modifiers || {};
    if (dist > maxRange) {
      this.emit('whiff', { id: attacker.id, type: act.type });
      return;
    }
    // Defensive states
    if (defender.dodge.active) {
      defender.stats.dodges++;
      defender.counterWindow = Math.max(defender.counterWindow, 0.65);
      attacker.stun = Math.max(attacker.stun, 0.22);
      attacker.combo = 0;
      this.emit('dodgeSuccess', { id: defender.id, attacker: attacker.id, type: act.type });
      return;
    }
    const precision = attr(attacker.attributes, 'precision', 55);
    const reflexes = attr(defender.attributes, 'reflexes', 55);
    const staminaPenalty = attacker.stamina < 20 ? 0.18 : 0;
    let hitChance = 0.70 + def.accuracy + (precision - reflexes) / 240 - staminaPenalty + (act.counter ? 0.16 : 0) + (defender.stun > 0 ? 0.2 : 0);
    if (defender.blocking) hitChance += 0.16;
    if (Math.random() > clamp(hitChance, 0.28, 0.97)) {
      attacker.combo = 0;
      this.emit('whiff', { id: attacker.id, type: act.type });
      return;
    }
    const strength = attr(attacker.attributes, 'strength', 55);
    const staminaFactor = clamp(0.55 + attacker.stamina / 110, 0.55, 1.15);
    let damage = def.damage * (0.72 + strength / 100 * 0.65) * staminaFactor * (0.9 + Math.random() * 0.2);
    damage *= style.power || 1;
    if (act.counter) damage *= 1.28;
    if (attacker.combo > 0) damage *= 1 + Math.min(0.24, attacker.combo * 0.035);
    if (defender.stun > 0) damage *= 1.2;
    const defense = attr(defender.attributes, 'defense', 55);
    damage *= 1 - clamp(defense / 100 * 0.34, 0, 0.38);

    const crit = Math.random() < 0.055 + precision / 1400;
    if (crit) damage *= 1.35;

    const target = Math.random() < 0.68 ? 'head' : 'body';
    defender.hurtFlash = 0.25;
    defender.combo = 0;
    attacker.lastHitAt = this.phaseTime;

    if (defender.blocking) {
      defender.stats.blocks++;
      const guardDmg = def.guardBreak * (0.72 + strength / 160);
      defender.guard = Math.max(0, defender.guard - guardDmg);
      const chip = damage * 0.17;
      defender.hp = Math.max(0, defender.hp - chip);
      defender.hurtFlash = 0.12;
      this.emit('block', { attacker: attacker.id, defender: defender.id, type: act.type, guard: defender.guard, damage: chip });
      if (defender.guard <= 0) {
        defender.stun = Math.max(defender.stun, 1.2);
        defender.blocking = false;
        defender.guard = 15;
        this.emit('guardBreak', { id: defender.id });
      }
      return;
    }

    damage = Math.max(1, Math.round(damage * 10) / 10);
    defender.hp = Math.max(0, defender.hp - damage);
    defender.stun = Math.max(defender.stun, def.stun * (0.8 + strength / 220));
    defender.stats.damage += damage;
    attacker.stats.landed++;
    attacker.stats.damage += damage;
    attacker.combo++;
    attacker.stats.maxCombo = Math.max(attacker.stats.maxCombo, attacker.combo);
    this.roundDamage[attacker.id === 'p1' ? 0 : 1] += damage;
    defender.roundDamage += damage;
    if (act.counter) attacker.stats.counters++;
    this.heat = Math.min(1, this.heat + 0.08 + damage / 80);
    this.emit(crit ? 'critical' : 'hit', {
      attacker: attacker.id, defender: defender.id, type: act.type, damage, crit,
      hp: defender.hp, stamina: defender.stamina, target,
    });
    if (defender.hp <= 0) {
      this.knockdown(defender, attacker);
    }
  }

  timeSinceHit(a, b) {
    return this.phaseTime - (a.lastHitAt || 0);
  }

  knockdown(fighter, opponent) {
    if (this.phase !== 'fight') return;
    fighter.knockdowns++;
    fighter.action = null;
    fighter.blocking = false;
    fighter.dodge.active = false;
    fighter.combo = 0;
    this.phase = 'knockdown';
    this.phaseTime = 0;
    this.down = {
      fighter, opponent, time: 0, count: 0, resolved: false, recovered: false,
      fallProgress: 0, taps: 0, playerCanTap: fighter.isPlayer || this.config.mode === 'multiplayer' && fighter.id === 'p2',
      maxKnockdowns: fighter.knockdowns >= 3,
    };
    opponent.stats.knockdowns = (opponent.stats.knockdowns || 0) + 1;
    this.emit('knockdown', { id: fighter.id, opponent: opponent.id, knockdowns: fighter.knockdowns, tko: this.down.maxKnockdowns });
    this.timeScale = this.down.maxKnockdowns ? 0.5 : 0.62;
    this.slowmoTimer = 1.4;
  }

  updateKnockdown(dt, inputs) {
    const d = this.down;
    if (!d) return;
    d.time += dt;
    d.fallProgress = Math.min(1, d.time / 0.9);
    if (d.playerCanTap && inputs) {
      const inBox = d.fighter.id === 'p1' ? inputs.p1 : inputs.p2;
      if (inBox?.getUp) d.taps++;
      if (this.remoteInput?.getUp && d.fighter.id === 'p2') d.taps++;
    }
    const count = Math.min(10, Math.floor(d.time / 0.55) + 1);
    if (count !== d.count) {
      d.count = count;
      this.emit('count', { count, id: d.fighter.id });
      if (count === 8 && !d.resolved) {
        d.resolved = true;
        const recovery = attr(d.fighter.attributes, 'recovery', 55);
        let chance = 0.36 + recovery / 240 - d.fighter.knockdowns * 0.11;
        chance += Math.min(0.28, d.taps * 0.06);
        if (d.maxKnockdowns) chance = 0;
        d.recovered = Math.random() < clamp(chance, 0, 0.78);
        if (d.recovered) {
          d.fighter.hp = Math.round(d.fighter.maxHp * 0.30);
          d.fighter.stamina = Math.max(30, d.fighter.stamina);
          d.fighter.stun = 0.8;
          d.fighter.guard = 45;
          d.opponent.stamina = Math.max(0, d.opponent.stamina - 6);
          this.emit('getUp', { id: d.fighter.id, taps: d.taps });
        }
      }
    }
    if ((d.resolved && !d.recovered && count >= 9) || count >= 10) {
      const isTko = d.fighter.knockdowns >= 3 || d.opponent.stats.landed - d.opponent.stats.blocks > 0 && d.maxKnockdowns;
      this.endFight({
        winnerId: d.opponent.id,
        loserId: d.fighter.id,
        method: isTko ? 'TKO' : 'KO',
        round: this.round,
        time: Math.max(0, this.clock),
      });
      this.phase = 'ko';
      this.phaseTime = 0;
      this.timeScale = 0.5;
      this.emit('ko', { winner: d.opponent.id, loser: d.fighter.id, method: isTko ? 'TKO' : 'KO' });
      return;
    }
    if (d.recovered && d.time > 6.0) {
      this.phase = 'fight';
      this.phaseTime = 0;
      this.clock = Math.max(6, this.clock);
      this.timeScale = 1;
      this.down = null;
      this.emit('bell');
      this.emit('resume', {});
    }
  }

  endRound() {
    if (this.phase !== 'fight') return;
    this.phase = 'roundEnd';
    this.phaseTime = 0;
    this.emit('bell');
    // Judges score the round
    const [a, b] = this.fighters;
    const dmgA = this.roundDamage[0] + a.knockdowns * 8;
    const dmgB = this.roundDamage[1] + b.knockdowns * 8;
    for (const j of this.judges) {
      let winner = dmgA === dmgB ? 0 : dmgA > dmgB ? 1 : -1;
      if (winner !== 0 && Math.random() < Math.abs(j.bias)) winner *= -1;
      let scoreA = 10, scoreB = 10;
      if (winner === 1) scoreB = 9;
      if (winner === -1) scoreA = 9;
      if (winner !== 0 && Math.random() < 0.04) { scoreA = 10; scoreB = 10; winner = 0; }
      const knocked = winner === 1 ? (b.knockdowns > 0) : (a.knockdowns > 0);
      if (knocked && winner !== 0) scoreB = winner === 1 ? 8 : scoreB;
      if (knocked && winner === -1) scoreA = 8;
      j.scores[0] += scoreA;
      j.scores[1] += scoreB;
      j.rounds.push({ round: this.round, a: scoreA, b: scoreB, winner });
    }
    a.scorecards.push({ round: this.round, dmg: dmgA });
    b.scorecards.push({ round: this.round, dmg: dmgB });
    this.emit('roundEnd', { round: this.round, damage: [...this.roundDamage], scores: this.judges.map((j) => [...j.scores]) });
    // Recovery between rounds
    for (const f of this.fighters) {
      const rec = attr(f.attributes, 'recovery', 55);
      f.hp = Math.min(f.maxHp, f.hp + 5 + rec * 0.075);
      f.stamina = Math.min(f.maxStamina, f.stamina + 18 + rec * 0.24);
      f.guard = Math.min(100, f.guard + 35);
      f.stun = 0;
      f.combo = 0;
      f.knockdowns = Math.max(0, f.knockdowns);
    }
    this.roundDamage = [0, 0];
  }

  nextRound() {
    if (this.round >= this.config.rounds) {
      this.decision();
      return;
    }
    this.round++;
    this.phase = 'fight';
    this.phaseTime = 0;
    this.clock = this.config.roundTime;
    this.timeScale = 1;
    this.emit('roundStart', { round: this.round });
    this.emit('bell');
  }

  decision() {
    const [a, b] = this.fighters;
    const totals = this.judges.map((j) => ({ a: j.scores[0], b: j.scores[1] }));
    let aWins = 0, bWins = 0, draws = 0;
    for (const t of totals) {
      if (t.a > t.b) aWins++;
      else if (t.b > t.a) bWins++;
      else draws++;
    }
    let winnerId = null;
    let method = 'DEC';
    if (aWins > bWins) winnerId = 'p1';
    else if (bWins > aWins) winnerId = 'p2';
    else {
      // Tiebreak by damage + knockdowns
      const scoreA = a.stats.damage + a.knockdowns * 12 + a.stats.landed * 0.5;
      const scoreB = b.stats.damage + b.knockdowns * 12 + b.stats.landed * 0.5;
      if (Math.abs(scoreA - scoreB) < 2) method = 'DRAW';
      else winnerId = scoreA > scoreB ? 'p1' : 'p2';
    }
    const unanimous = method === 'DEC' && (aWins === 3 || bWins === 3);
    this.endFight({
      winnerId,
      loserId: winnerId ? (winnerId === 'p1' ? 'p2' : 'p1') : null,
      method: method === 'DRAW' ? 'DRAW' : 'DEC',
      decisionType: unanimous ? 'UNÂNIME' : 'DIVISÃO',
      round: this.config.rounds,
      time: 0,
      scorecards: totals,
    });
    this.emit('decision', { result: this.result });
  }

  finishKo() {
    if (this.result) {
      this.phase = 'end';
      this.timeScale = 1;
      this.finished = true;
      this.emit('end', this.result);
    }
  }

  endFight(result) {
    if (this.result) return;
    const winner = this.fighters.find((f) => f.id === result.winnerId);
    const loser = this.fighters.find((f) => f.id === result.loserId);
    const totalA = this.judges.reduce((s, j) => s + j.scores[0], 0);
    const totalB = this.judges.reduce((s, j) => s + j.scores[1], 0);
    this.result = {
      ...result,
      rounds: this.config.rounds,
      stats: {
        p1: { ...this.fighters[0].stats, hp: this.fighters[0].hp, maxHp: this.fighters[0].maxHp },
        p2: { ...this.fighters[1].stats, hp: this.fighters[1].hp, maxHp: this.fighters[1].maxHp },
      },
      totals: { p1: totalA, p2: totalB },
      scorecards: this.judges.map((j) => ({ judge: j.name, p1: j.scores[0], p2: j.scores[1], rounds: j.rounds })),
      winnerName: winner?.name || null,
      loserName: loser?.name || null,
      winnerId: result.winnerId,
      loserId: result.loserId,
      method: result.method,
      division: this.config.division,
      date: new Date().toISOString(),
      matchId: this.config.matchId || ('m' + Date.now().toString(36)),
    };
    if (winner) winner.victory = true;
    if (loser) loser.defeated = true;
    this.timeScale = 1;
    this.phase = this.phase === 'ko' ? 'ko' : 'end';
    if (this.phase === 'end') this.finished = true;
    this.emit('result', this.result);
    if (this.phase === 'end') this.emit('end', this.result);
  }

  quit(fighterId = 'p1') {
    if (this.result) return;
    const other = fighterId === 'p1' ? 'p2' : 'p1';
    this.endFight({ winnerId: other, loserId: fighterId, method: 'QUIT', round: this.round, time: Math.max(0, this.clock) });
    this.phase = 'end';
    this.finished = true;
    this.emit('end', this.result);
  }

  joinGetUp() {
    if (this.phase === 'knockdown' && this.down) this.down.taps += 1;
  }

  updateHeat(dt) {
    const [a, b] = this.fighters;
    const activity = (a.combo + b.combo) * 0.05 + (100 - Math.min(a.hp, b.hp)) / 300;
    this.heat = clamp(this.heat + (activity - this.heat) * dt * 0.6, 0.15, 1);
    this.timeScale = this.timeScale < 1 && this.slowmoTimer <= 0 ? 1 : this.timeScale;
  }

  emit(type, data = {}) {
    const ev = { type, time: this.phaseTime, round: this.round, ...data };
    this.events.push(ev);
    if (this.onEvent) this.onEvent(ev);
    if (this.events.length > 300) this.events.shift();
  }

  drainEvents() {
    const e = this.events;
    this.events = [];
    return e;
  }

  getSnapshot() {
    return {
      t: this.tick,
      phase: this.phase,
      started: this.started,
      clock: this.clock,
      round: this.round,
      rounds: this.config.rounds,
      timeScale: this.timeScale,
      heat: this.heat,
      result: this.result,
      fighters: this.fighters.map((f) => ({
        id: f.id, pos: { ...f.pos }, facing: f.facing, hp: f.hp, maxHp: f.maxHp, stamina: f.stamina,
        guard: f.guard, blocking: f.blocking, action: f.action ? { type: f.action.type, time: f.action.time, dur: f.action.def.dur } : null,
        stun: f.stun, dodge: { ...f.dodge }, knockdowns: f.knockdowns, combo: f.combo, expression: f.expression,
        victory: f.victory, defeated: f.defeated, hurtFlash: f.hurtFlash,
        down: this.down && this.down.fighter.id === f.id ? { fallProgress: this.down.fallProgress, count: this.down.count } : null,
      })),
      down: this.down ? { id: this.down.fighter.id, count: this.down.count, fallProgress: this.down.fallProgress, time: this.down.time } : null,
      judges: this.judges.map((j) => ({ scores: [...j.scores] })),
      stats: this.fighters.map((f) => ({ ...f.stats })),
    };
  }

  applySnapshot(s) {
    if (!s) return;
    this.phase = s.phase;
    this.started = s.started;
    this.clock = s.clock;
    this.round = s.round;
    this.timeScale = s.timeScale;
    this.heat = s.heat;
    this.tick = s.t;
    if (s.result && !this.result) {
      this.result = s.result;
      this.fighters.forEach((f, i) => {
        f.victory = !!s.fighters[i]?.victory;
        f.defeated = !!s.fighters[i]?.defeated;
      });
      this.emit('result', this.result);
    }
    if (this.fighters && s.fighters) {
      s.fighters.forEach((sf, i) => {
        const f = this.fighters[i];
        if (!f) return;
        Object.assign(f, {
          hp: sf.hp, maxHp: sf.maxHp, stamina: sf.stamina, guard: sf.guard, blocking: sf.blocking,
          stun: sf.stun, knockdowns: sf.knockdowns, combo: sf.combo, expression: sf.expression,
          victory: sf.victory, defeated: sf.defeated, hurtFlash: sf.hurtFlash, facing: sf.facing,
        });
        f.pos = { ...sf.pos };
        f.dodge = { ...sf.dodge };
        f.action = sf.action ? { type: sf.action.type, time: sf.action.time, def: PUNCHES[sf.action.type], resolved: true } : null;
        f.down = sf.down;
        f.netPos = { ...sf.pos };
      });
    }
    if (s.down) {
      const fighter = this.fighters.find((f) => f.id === s.down.id);
      this.down = { fighter, time: s.down.time, count: s.down.count, fallProgress: s.down.fallProgress, resolved: true, recovered: false };
    } else {
      this.down = null;
    }
    if (s.judges) s.judges.forEach((j, i) => { if (this.judges[i]) this.judges[i].scores = [...j.scores]; });
    if (s.stats) s.stats.forEach((st, i) => { if (this.fighters[i]) this.fighters[i].stats = { ...st }; });
    if (s.phase === 'end') this.finished = true;
  }
}

// ---------------------------------------------------------------------------
// AI
// ---------------------------------------------------------------------------
export class BoxingAI {
  constructor(engine, slot, difficulty = 'pro') {
    this.engine = engine;
    this.slot = slot;
    this.id = slot === 0 ? 'p1' : 'p2';
    this.me = () => engine.fighters[slot];
    this.opp = () => engine.fighters[1 - slot];
    const table = { rookie: 0.55, pro: 0.75, elite: 0.9, legend: 1.0 };
    this.skill = table[difficulty] ?? 0.78;
    this.input = { moveX: 0, moveZ: 0, block: false, dodge: false, punch: null, getUp: false };
    this.timer = 0.5 + Math.random() * 0.5;
    this.punchPlan = [];
    this.blockTimer = 0;
    this.dodgeTimer = 0;
    this.style = this.me().style;
    this.aggression = { aggressive: 0.92, defensive: 0.42, technical: 0.6, counter: 0.5, speed: 0.68, pressure: 0.95 }[this.style] ?? 0.65;
    this.personality = Math.random();
  }

  think(dt) {
    const me = this.me();
    const opp = this.opp();
    const input = this.input;
    input.punch = null;
    input.dodge = false;
    input.getUp = false;
    if (this.engine.phase === 'knockdown' && this.engine.down?.fighter === me) {
      input.getUp = Math.random() < this.skill * 0.7;
      return null;
    }
    if (this.engine.phase !== 'fight') return null;
    this.timer -= dt;
    this.blockTimer = Math.max(0, this.blockTimer - dt);
    this.dodgeTimer = Math.max(0, this.dodgeTimer - dt);
    const dist = me.distance || Math.hypot(opp.pos.x - me.pos.x, opp.pos.z - me.pos.z);
    const oppAttacking = !!opp.action;
    const myStamina = me.stamina;
    const oppHp = opp.hp / opp.maxHp;
    const myHp = me.hp / me.maxHp;

    // Reactive defence (reaction speed increases with difficulty/reflexes).
    const reaction = this.skill * (0.5 + (me.attributes.reflexes || 50) / 180);
    if (oppAttacking && Math.random() < reaction * 0.5 * dt * 18 && this.dodgeTimer <= 0) {
      const styleDodge = this.style === 'counter' || this.style === 'defensive' || this.style === 'speed';
      if (Math.random() < (styleDodge ? 0.55 : 0.3) && me.dodge.cooldown <= 0 && myStamina > 18) {
        input.dodge = true;
        this.dodgeTimer = 0.5;
        input.moveX = Math.random() < 0.5 ? -1 : 1;
        return null;
      }
      if (Math.random() < (styleDodge ? 0.5 : 0.66) && myStamina > 10) {
        this.blockTimer = 0.22 + Math.random() * 0.3;
      }
    }
    input.block = this.blockTimer > 0 && myStamina > 4;
    input.moveX = 0;
    input.moveZ = 0;

    if (myStamina < 16 && !input.block) {
      // Rest: circle away and guard.
      input.moveZ = -0.55;
      input.moveX = Math.sin(this.engine.phaseTime * 0.7) * 0.7;
      if (dist < 1.6) input.block = Math.random() < 0.5;
      if (dist > 2.3) input.moveZ = 0;
      return input;
    }

    // Range management based on style.
    const preferred = this.style === 'technical' ? 1.75 : this.style === 'counter' ? 1.8 : this.style === 'speed' ? 1.5 : this.style === 'defensive' ? 1.95 : 1.45;
    if (dist > preferred + 0.15) {
      input.moveZ = 0.55 + this.aggression * 0.45;
      input.moveX = Math.sin(this.engine.phaseTime * 0.9 + this.personality) * 0.3;
    } else if (dist < preferred - 0.22) {
      input.moveZ = -0.35 - (this.style === 'aggressive' ? -0.1 : 0.2);
      input.moveX = Math.sin(this.engine.phaseTime * 1.1) * 0.4;
    } else {
      input.moveX = Math.sin(this.engine.phaseTime * 0.55 + this.personality * 6) * 0.45;
    }

    // Combo plan
    if (this.punchPlan.length && this.timer <= 0) {
      input.punch = this.punchPlan.shift();
      this.timer = 0.16 + Math.random() * 0.2 + (1 - this.skill) * 0.2;
      return input;
    }

    if (this.timer <= 0) {
      const hurtOpp = oppHp < 0.35;
      const aggression = this.aggression * (0.8 + this.skill * 0.35) * (hurtOpp ? 1.3 : 1) * (myHp < 0.3 ? 0.8 : 1);
      this.timer = 0.3 + Math.random() * (0.6 - aggression * 0.3);
      if (dist < 2.1 && myStamina > 18 && Math.random() < aggression) {
        const roll = Math.random();
        let punch;
        if (dist > 1.85) punch = roll < 0.7 ? 'jab' : 'cross';
        else if (dist > 1.5) punch = roll < 0.4 ? 'jab' : roll < 0.7 ? 'cross' : 'hook';
        else punch = roll < 0.25 ? 'jab' : roll < 0.5 ? 'hook' : roll < 0.8 ? 'uppercut' : 'body';
        if (opp.blocking && Math.random() < 0.45) punch = 'body';
        if (opp.stun > 0) punch = 'uppercut';
        input.punch = punch;
        // Follow-up plan
        const chance = this.skill * (this.style === 'aggressive' || this.style === 'pressure' ? 0.7 : 0.45);
        if (Math.random() < chance) {
          this.punchPlan = [Math.random() < 0.5 ? 'cross' : 'hook'];
          if (this.style === 'pressure' && Math.random() < 0.4) this.punchPlan.push('body');
        }
        this.timer = 0.18 + Math.random() * 0.3;
      } else if (dist < 1.6 && myStamina > 25 && Math.random() < 0.3) {
        input.punch = 'uppercut';
        this.timer = 0.4;
      } else if (Math.random() < 0.25) {
        // reset / feint
        input.dodge = Math.random() < 0.2 && myStamina > 20;
      }
    }
    // Cornered escape
    if (Math.abs(me.pos.x) > 2.15 || Math.abs(me.pos.z) > 2.15) {
      input.moveX = -Math.sign(me.pos.x || 1) * 0.9;
      input.moveZ = -Math.sign(me.pos.z || 1) * 0.5;
    }
    return input;
  }
}

export function simulateQuickFight(p1, p2, { rounds = 3, seed = Date.now() } = {}) {
  // Used by "simular luta" and quick background fights. Deterministic-ish, no rendering.
  let hp1 = 100, hp2 = 100, st1 = 100, st2 = 100;
  let dmg1 = 0, dmg2 = 0;
  let kd1 = 0, kd2 = 0;
  let round = 1;
  let winner = null;
  let method = null;
  const rating1 = (p1.overall || 60) + (p1.style === 'aggressive' ? 1 : 0);
  const rating2 = (p2.overall || 60);
  const rnd = mulberry32Local(seed);
  for (round = 1; round <= rounds; round++) {
    let r = 0;
    while (r < 16) {
      r++;
      const aHits = rnd() < 0.52 + (rating1 - rating2) / 300;
      if (aHits) {
        const dmg = (3 + rnd() * 10) * (rating1 / rating2);
        hp2 -= dmg;
        dmg1 += dmg;
        st1 -= 3;
      } else {
        const dmg = (3 + rnd() * 10) * (rating2 / rating1);
        hp1 -= dmg;
        dmg2 += dmg;
        st2 -= 3;
      }
      if (hp2 <= 0) { hp2 = 0; winner = 'p1'; method = 'KO'; break; }
      if (hp1 <= 0) { hp1 = 0; winner = 'p2'; method = 'KO'; break; }
    }
    if (winner) break;
    // between-rounds recovery
    hp1 = Math.min(100, hp1 + 6 + (p1.attributes?.recovery || 50) * 0.05);
    hp2 = Math.min(100, hp2 + 6 + (p2.attributes?.recovery || 50) * 0.05);
    st1 = Math.min(100, st1 + 20);
    st2 = Math.min(100, st2 + 20);
  }
  if (!winner) {
    const score1 = dmg1 + (100 - hp1) * 0.3 + (rating1 - 60);
    const score2 = dmg2 + (100 - hp2) * 0.3 + (rating2 - 60);
    if (Math.abs(score1 - score2) < 4) { method = 'DRAW'; winner = null; }
    else { winner = score1 > score2 ? 'p1' : 'p2'; method = 'DEC'; round = rounds; }
  }
  return { winner, method, round, hp1, hp2, dmg1, dmg2, score1: dmg1, score2: dmg2 };
}

function mulberry32Local(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Deterministic procedural appearance for any NPC fighter.
import { seeded, clamp } from './rng.js';
import { HAIR, BEARDS, BROWS, FACE_SHAPES, EYES, NOSES, MOUTHS, SCARS, SKIN_TONES, SHORTS, TOPS, SHOES, ROBES, GLOVES, COLORWAYS } from './data.js';

const TATTOOS = ['Nenhuma', 'Dragão', 'Coroa', 'Chama', 'Cobra', 'Asas', 'Estrela', 'Cruz', 'Leão', 'Tribal'];

export function appearanceForFighter(fighter, divisionId = 'middle') {
  if (!fighter) return randomAppearance('default');
  const rnd = seeded('look-' + fighter.id + (fighter.name || ''));
  const heavy = ['cruiser', 'heavy', 'lheavy'].includes(fighter.division || divisionId);
  const light = ['fly', 'bantam', 'feather'].includes(fighter.division || divisionId);
  const muscle = heavy ? rnd.range(0.55, 0.96) : light ? rnd.range(0.28, 0.7) : rnd.range(0.4, 0.88);
  const width = heavy ? rnd.range(0.58, 0.85) : light ? rnd.range(0.3, 0.58) : rnd.range(0.42, 0.7);
  const heightT = fighter.height ? clamp((fighter.height - 162) / 44, 0, 1) : rnd.range(0.2, 0.9);
  const reachT = fighter.reach ? clamp((fighter.reach - 168) / 30, 0, 1) : rnd.range(0.25, 0.85);
  const theme = rnd.int(0, COLORWAYS.length - 1);
  const shorts = SHORTS[rnd.int(0, SHORTS.length - 1)];
  const glove = GLOVES[rnd.int(0, GLOVES.length - 1)];
  return {
    skin: SKIN_TONES[rnd.int(0, SKIN_TONES.length - 1)].id,
    hair: HAIR[rnd.int(0, HAIR.length - 1)].id,
    beard: rnd.chance(0.55) ? BEARDS[rnd.int(0, BEARDS.length - 1)].id : 'none',
    brow: BROWS[rnd.int(0, BROWS.length - 1)].id,
    face: FACE_SHAPES[rnd.int(0, FACE_SHAPES.length - 1)].id,
    eyes: EYES[rnd.int(0, EYES.length - 1)].id,
    nose: NOSES[rnd.int(0, NOSES.length - 1)].id,
    mouth: MOUTHS[rnd.int(0, MOUTHS.length - 1)].id,
    scar: rnd.chance(0.45) ? SCARS[rnd.int(1, SCARS.length - 1)].id : 's0',
    height: heightT,
    reach: reachT,
    muscle,
    width,
    shorts: shorts.id,
    top: rnd.chance(0.14) ? TOPS[rnd.int(0, TOPS.length - 1)].id : 'none',
    shoe: SHOES[rnd.int(0, SHOES.length - 1)].id,
    robe: ROBES[rnd.int(0, ROBES.length - 1)].id,
    glove: glove.id,
    colorway: COLORWAYS[theme].id,
    wrap: rnd.chance(0.45) ? 'bandagem-tradicional' : 'none',
    headgear: 'none',
    medal: 'none',
    tattoo: TATTOOS[rnd.int(0, TATTOOS.length - 1)],
  };
}

export function randomAppearance(seed = 'default', divisionId = 'middle') {
  const rnd = seeded('random-look-' + seed);
  const muscle = rnd.range(0.35, 0.9);
  return {
    skin: SKIN_TONES[rnd.int(0, SKIN_TONES.length - 1)].id,
    hair: HAIR[rnd.int(0, HAIR.length - 1)].id,
    beard: rnd.chance(0.4) ? BEARDS[rnd.int(0, BEARDS.length - 1)].id : 'none',
    brow: BROWS[rnd.int(0, BROWS.length - 1)].id,
    face: FACE_SHAPES[rnd.int(0, FACE_SHAPES.length - 1)].id,
    eyes: EYES[rnd.int(0, EYES.length - 1)].id,
    nose: NOSES[rnd.int(0, NOSES.length - 1)].id,
    mouth: MOUTHS[rnd.int(0, MOUTHS.length - 1)].id,
    scar: SCARS[rnd.int(0, SCARS.length - 1)].id,
    height: rnd.range(0.2, 0.85),
    reach: rnd.range(0.25, 0.85),
    muscle,
    width: rnd.range(0.35, 0.75),
    shorts: SHORTS[rnd.int(0, SHORTS.length - 1)].id,
    top: 'none',
    shoe: SHOES[rnd.int(0, SHOES.length - 1)].id,
    robe: ROBES[rnd.int(0, ROBES.length - 1)].id,
    glove: GLOVES[rnd.int(0, GLOVES.length - 1)].id,
    colorway: COLORWAYS[rnd.int(0, COLORWAYS.length - 1)].id,
    wrap: rnd.chance(0.4) ? 'bandagem-tradicional' : 'none',
    headgear: 'none',
    medal: 'none',
    tattoo: TATTOOS[rnd.int(0, TATTOOS.length - 1)],
  };
}

export function appearanceForPlayer(save) {
  if (!save?.profile?.appearance) return randomAppearance('player');
  return { ...save.profile.appearance };
}

// Cinematic fight rendering: camera direction, animation states, impacts, sweat, replay.
import * as THREE from 'three';
import { buildArena } from '../three/environment.js';
import { Boxer, makeChampionshipBelt } from '../three/boxer.js';
import { appearanceForFighter } from '../core/appearance.js';
import { sparkTexture } from '../three/textures.js';
import { clamp, lerp, damp } from '../core/rng.js';

const VISUAL_SCALE = 0.68;

export class FightView {
  constructor({ renderer, engine, arenaConfig, quality = 'high', appearances = {}, mobile = false }) {
    this.renderer = renderer;
    this.engine = engine;
    this.quality = quality;
    this.mobile = mobile;
    this.arena = buildArena(arenaConfig, { quality, crowd: true, staff: true });
    this.scene = this.arena.scene;
    this.camera = new THREE.PerspectiveCamera(mobile ? 54 : 46, 1, 0.1, 80);
    this.camera.position.set(3.4, 2.2, 5.5);
    this.camera.lookAt(0, 1.2, 0);
    this.cameraTarget = new THREE.Vector3(0, 1.15, 0);
    this.camPos = this.camera.position.clone();
    this.camLook = new THREE.Vector3(0, 1.15, 0);
    this.time = 0;
    this.entrance = null;
    this.replay = null;
    this.frames = [];
    this.recordTimer = 0;
    this.shake = 0;
    this.flash = 0;
    this.heat = 0.25;
    this.beltGroup = null;
    this.confetti = null;
    this.hitstop = 0;
    this.koCamera = false;
    this.lastPhase = 'intro';
    this.resultShownAt = 0;
    this.flashSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: sparkTexture(), color: '#fff7d0', transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.flashSprite.scale.setScalar(3);
    this.flashSprite.position.set(0, 1.2, 0);
    this.scene.add(this.flashSprite);

    // Boxers
    const p1App = appearances.p1 || appearanceForFighter(engine.fighters[0].def, engine.fighters[0].def.division);
    const p2App = appearances.p2 || appearanceForFighter(engine.fighters[1].def, engine.fighters[1].def.division);
    this.boxers = [
      new Boxer(p1App, { robe: true, quality }),
      new Boxer(p2App, { robe: true, quality }),
    ];
    for (const b of this.boxers) {
      b.setRobe(true);
      this.arena.root.add(b.root);
      b.root.position.set(0, 0, 0);
      // Soft contact shadow
      const shadow = new THREE.Mesh(new THREE.CircleGeometry(0.38, 20), new THREE.MeshBasicMaterial({ color: '#000000', transparent: true, opacity: 0.32, depthWrite: false }));
      shadow.rotation.x = -Math.PI / 2;
      shadow.position.y = 0.012;
      b.root.add(shadow);
      b.shadow = shadow;
    }
    this.syncFighters(1);
    this.boxers[0].root.rotation.y = Math.PI;
    this.boxers[1].root.rotation.y = 0;
    // Place boxers in their corners for the entrance.
    this.entrancePos = [
      new THREE.Vector3(2.0, 0, 2.2),
      new THREE.Vector3(-2.0, 0, -2.2),
    ];

    this.setupEffects();
    this.updateCamera(0.016, true);
  }

  setArenaShadow(on) {
    // toggles staff/ref shadows only for performance
    for (const s of this.arena.staff) s.root.traverse((o) => { if (o.isMesh) o.castShadow = on; });
  }

  setupEffects() {
    this.sparks = [];
    for (let i = 0; i < 10; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: sparkTexture(), color: '#ffd27a', transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }));
      s.scale.setScalar(0.5);
      this.scene.add(s);
      this.sparks.push({ sprite: s, life: 0, max: 0, size: 0.5, color: '#ffd27a' });
    }
    // Sweat particle pool
    this.sweatCount = 140;
    const pos = new Float32Array(this.sweatCount * 3);
    const vel = new Float32Array(this.sweatCount * 3);
    const life = new Float32Array(this.sweatCount);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.sweat = { pos, vel, life, cursor: 0, geo };
    const sweatMat = new THREE.PointsMaterial({ color: '#fff5d4', size: 0.028, transparent: true, opacity: 0.8, depthWrite: false, blending: THREE.AdditiveBlending });
    this.sweatPoints = new THREE.Points(geo, sweatMat);
    this.sweatPoints.frustumCulled = false;
    this.scene.add(this.sweatPoints);
    // Contact flash ring
    this.impactRing = new THREE.Mesh(new THREE.RingGeometry(0.12, 0.18, 24), new THREE.MeshBasicMaterial({ color: '#fff0b0', transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.scene.add(this.impactRing);
    this.impactRingLife = 0;
  }

  handleEvent(ev) {
    if (!ev) return;
    switch (ev.type) {
      case 'hit':
      case 'critical': {
        const defender = ev.defender === 'p1' ? this.boxers[0] : this.boxers[1];
        const attacker = ev.attacker === 'p1' ? this.boxers[0] : this.boxers[1];
        const glove = attacker.getGloveWorld(ev.type === 'jab' ? 'L' : 'R');
        const head = defender.getHeadWorld();
        const pos = new THREE.Vector3().lerpVectors(glove, head, 0.48);
        pos.y = ev.target === 'body' ? Math.min(pos.y, 1.15) : pos.y;
        this.spawnImpact(pos, ev.damage, ev.crit, ev.defender);
        defender.flash(ev.crit ? '#ffd36e' : '#ff7a5c');
        this.shake = Math.min(0.8, this.shake + 0.08 + (ev.damage || 0) / 130);
        if (ev.crit) this.flash = Math.max(this.flash, 0.45);
        if ((ev.damage || 0) > 10) this.hitstop = 0.055;
        this.spawnSweat(head, ev.crit ? 16 : 8, ev.attacker === 'p1' ? 1 : -1);
        break;
      }
      case 'block': {
        const defender = ev.defender === 'p1' ? this.boxers[0] : this.boxers[1];
        const glove = defender.getGloveWorld('R');
        this.spawnImpact(glove, 2, false, ev.defender, '#bfe6ff');
        this.shake = Math.min(0.5, this.shake + 0.035);
        break;
      }
      case 'knockdown':
      case 'ko':
        this.shake = 0.9;
        this.flash = 1;
        this.koCamera = true;
        break;
      case 'guardBreak':
        this.flash = Math.max(this.flash, 0.25);
        break;
      case 'getUp':
        this.flashSprite.material.color.set('#a8ffcf');
        break;
      default:
        break;
    }
  }

  spawnImpact(pos, damage = 4, crit = false, defenderId = 'p2', color = null) {
    const spark = this.sparks.find((s) => s.life <= 0) || this.sparks[0];
    spark.life = 0.28;
    spark.max = 0.28;
    spark.size = clamp(0.35 + damage / 26, 0.35, 1.25) * (crit ? 1.4 : 1);
    spark.sprite.position.copy(pos);
    spark.sprite.material.color.set(color || (crit ? '#ffe9a3' : '#ffc27a'));
    spark.sprite.material.opacity = 1;
    spark.sprite.scale.setScalar(spark.size * 0.6);
    spark.crit = crit;
    this.impactRing.position.copy(pos);
    this.impactRing.position.z += 0.01;
    this.impactRing.material.color.set(color || '#fff0b0');
    this.impactRing.material.opacity = 0.9;
    this.impactRingLife = 0.2;
    this.impactRing.scale.setScalar(1);
    // opponent flinch offset
    const b = defenderId === 'p1' ? this.boxers[0] : this.boxers[1];
    b.flinch = (Math.random() < 0.5 ? -1 : 1) * 0.12;
  }

  spawnSweat(origin, count = 8, dir = 1) {
    if (!this.sweat) return;
    for (let i = 0; i < count; i++) {
      const idx = this.sweat.cursor;
      this.sweat.cursor = (this.sweat.cursor + 1) % this.sweatCount;
      this.sweat.pos[idx * 3] = origin.x + (Math.random() - 0.5) * 0.2;
      this.sweat.pos[idx * 3 + 1] = origin.y + (Math.random() - 0.5) * 0.2;
      this.sweat.pos[idx * 3 + 2] = origin.z + (Math.random() - 0.5) * 0.2;
      this.sweat.vel[idx * 3] = (Math.random() - 0.5) * 1.8 + dir * 0.4;
      this.sweat.vel[idx * 3 + 1] = 0.8 + Math.random() * 1.8;
      this.sweat.vel[idx * 3 + 2] = (Math.random() - 0.5) * 1.8;
      this.sweat.life[idx] = 0.45 + Math.random() * 0.4;
    }
    this.sweatPoints.visible = true;
  }

  startEntrance() {
    this.entrance = { t: 0, dur: 3.1 };
    for (const b of this.boxers) b.setRobe(true);
    this.boxers[0].root.position.copy(this.entrancePos[0]);
    this.boxers[1].root.position.copy(this.entrancePos[1]);
    this.boxers[0].root.rotation.y = Math.PI * 0.8;
    this.boxers[1].root.rotation.y = -Math.PI * 0.2;
    this.boxers[0].update(0.016, { entrance: true, robe: true });
    this.boxers[1].update(0.016, { entrance: true, robe: true });
  }

  endEntrance() {
    this.entrance = null;
    for (const b of this.boxers) b.setRobe(false);
    this.syncFighters(1);
  }

  update(dt, { paused = false } = {}) {
    if (this.hitstop > 0) {
      this.hitstop = Math.max(0, this.hitstop - dt);
      dt *= 0.15;
    }
    this.time += dt;
    this.heat = damp(this.heat, this.engine.heat || 0.25, 1.2, dt);
    this.shake = Math.max(0, this.shake - dt * 2.4);
    this.flash = Math.max(0, this.flash - dt * 3.2);

    if (this.replay) {
      this.updateReplay(dt);
      this.updateParticles(dt);
      this.arena.update(dt, this.heat);
      this.renderCamera(dt, true);
      return;
    }

    if (this.entrance) {
      this.entrance.t += dt;
      const p = clamp(this.entrance.t / this.entrance.dur, 0, 1);
      const ease = p * p * (3 - 2 * p);
      const start0 = new THREE.Vector3(-0.06 * VISUAL_SCALE, 0, (1.62 / 2) * VISUAL_SCALE);
      const start1 = new THREE.Vector3(0.06 * VISUAL_SCALE, 0, -(1.62 / 2) * VISUAL_SCALE);
      this.boxers[0].root.position.lerpVectors(this.entrancePos[0], start0, ease);
      this.boxers[1].root.position.lerpVectors(this.entrancePos[1], start1, ease);
      this.boxers[0].root.rotation.y = lerp(Math.PI * 0.8, Math.PI, ease);
      this.boxers[1].root.rotation.y = lerp(-Math.PI * 0.2, 0, ease);
      for (const [i, b] of this.boxers.entries()) {
        b.update(dt, { entrance: p < 0.9, robe: true, moveZ: 1, moveX: 0, stamina: 100 });
      }
      this.updateStaff(dt);
      this.updateCamera(dt, false, true);
      this.arena.update(dt, 0.6);
      this.updateParticles(dt);
      if (p >= 1 && !this._entranceDone) {
        this._entranceDone = true;
        this.onEntranceDone?.();
      }
      return;
    }

    this.syncFighters(dt);
    this.updateStaff(dt);
    this.updateCamera(dt);
    this.arena.update(dt, Math.min(1, this.heat + (this.engine.phase === 'knockdown' ? 0.35 : 0)));
    this.updateParticles(dt);
    this.recordFrame(dt);
    if (this.engine.result && this.engine.phase === 'end' && !this.resultAt) this.resultAt = this.time;
    if (this.engine.result && !this.beltGroup) this.maybeCelebrate();
  }

  syncFighters(dt) {
    const [f1, f2] = this.engine.fighters;
    const fighting = this.engine.phase !== 'intro';
    for (const [i, f] of [f1, f2].entries()) {
      const b = this.boxers[i];
      if (!f || !b) continue;
      const x = f.pos.x * VISUAL_SCALE;
      const z = f.pos.z * VISUAL_SCALE;
      b.root.position.x = damp(b.root.position.x, x, 20, dt);
      b.root.position.z = damp(b.root.position.z, z, 20, dt);
      b.root.position.y = 0.012;
      b.root.rotation.y = f.facing;
      const down = this.engine.phase === 'knockdown' && this.engine.down?.fighter?.id === f.id;
      const downKo = this.engine.phase === 'ko' && this.engine.result?.loserId === f.id && ['KO', 'TKO'].includes(this.engine.result.method);
      const state = {
        moveX: f.moveX || 0,
        moveZ: f.moveZ || 0,
        blocking: f.blocking,
        dodging: f.dodge.active,
        dodgeDir: f.dodge.dir,
        action: f.action?.type || null,
        actionTime: f.action?.time || 0,
        actionDur: f.action?.def?.dur || 0,
        stun: f.stun,
        stamina: f.stamina,
        hp: f.hp,
        knockedDown: down || downKo,
        fallProgress: down ? this.engine.down?.fallProgress || 1 : downKo ? 1 : 0,
        victory: !!(this.engine.result && this.engine.result.winnerId === f.id && this.engine.phase === 'end'),
        defeated: downKo || !!(this.engine.result && this.engine.result.loserId === f.id && this.engine.phase === 'end' && !['KO', 'TKO'].includes(this.engine.result.method)),
        robe: false,
      };
      const wasBlocking = b._blocking;
      b.update(dt, state);
      b._blocking = f.blocking;
      if (b.shadow) {
        b.shadow.material.opacity = down || downKo ? 0.2 : 0.32;
      }
      if (this.engine.result && this.engine.phase === 'end' && this.engine.result.winnerId === f.id) {
        b.setExpression('happy');
      } else if (f.stun > 0.1) b.setExpression('hurt');
      else if (f.stamina < 24) b.setExpression('tired');
      else if (f.action) b.setExpression('focused');
      else b.setExpression('neutral');
    }
  }

  updateStaff(dt) {
    const ref = this.arena.referee;
    if (!ref) return;
    const e = this.engine;
    let targetX = 0.0, targetZ = -2.3;
    let rotation = 0;
    if (e.phase === 'knockdown' && e.down) {
      const f = e.fighters.find((x) => x.id === e.down.fighter.id);
      if (f) {
        targetX = f.pos.x * VISUAL_SCALE + 0.65;
        targetZ = f.pos.z * VISUAL_SCALE + 0.55;
        rotation = Math.atan2(-(f.pos.x * VISUAL_SCALE - targetX), -(f.pos.z * VISUAL_SCALE - targetZ));
        // wave down
        ref.setExpression('focused');
      }
    } else if (e.phase === 'end' && e.result?.winnerId) {
      const w = e.fighters.find((f) => f.id === e.result.winnerId);
      if (w) {
        targetX = w.pos.x * VISUAL_SCALE + 0.65;
        targetZ = w.pos.z * VISUAL_SCALE + 0.35;
        rotation = Math.atan2(-(w.pos.x * VISUAL_SCALE - targetX), -(w.pos.z * VISUAL_SCALE - targetZ));
        ref.setExpression('happy');
      }
    } else {
      targetX = Math.sin(this.time * 0.2) * 0.6;
      targetZ = -2.35;
      rotation = 0;
    }
    ref.root.position.x = damp(ref.root.position.x, targetX, 2.2, dt);
    ref.root.position.z = damp(ref.root.position.z, targetZ, 2.2, dt);
    ref.root.rotation.y = damp(ref.root.rotation.y, rotation, 3, dt);
    const knee = e.phase === 'knockdown' ? 0.9 : 0.15;
    ref.update(dt, { stamina: 90, stance: knee, blocking: false });
    for (const s of this.arena.staff) {
      if (s === ref) continue;
      s.update(dt, { stamina: 95, idle: true });
    }
  }

  updateCamera(dt, forced = false, entrance = false) {
    const e = this.engine;
    const aspect = this.camera.aspect;
    const mobileFactor = aspect < 1 ? 1.26 : 1;
    const [f1, f2] = e.fighters;
    const mid = new THREE.Vector3(
      ((f1.pos.x + f2.pos.x) / 2) * VISUAL_SCALE,
      1.08,
      ((f1.pos.z + f2.pos.z) / 2) * VISUAL_SCALE,
    );
    let desiredPos;
    let desiredLook;
    if (entrance) {
      const p = clamp((this.entrance?.t || 0) / (this.entrance?.dur || 3), 0, 1);
      const ease = p * p * (3 - 2 * p);
      desiredPos = new THREE.Vector3(lerp(-3.6, 3.1, ease), lerp(0.65, 2.0, ease), lerp(6.0, 5.0, ease));
      desiredLook = new THREE.Vector3(lerp(1.6, 0, ease), lerp(0.75, 1.1, ease), 0.2);
    } else if (e.phase === 'knockdown' && e.down) {
      const f = e.fighters.find((x) => x.id === e.down.fighter.id) || f1;
      const x = f.pos.x * VISUAL_SCALE;
      const z = f.pos.z * VISUAL_SCALE;
      desiredPos = new THREE.Vector3(x + 1.55 * mobileFactor, 0.82, z + 1.85 * mobileFactor);
      desiredLook = new THREE.Vector3(x, 0.5, z);
    } else if (e.phase === 'ko' && e.result) {
      const loser = e.fighters.find((f) => f.id === e.result.loserId) || f2;
      const winner = e.fighters.find((f) => f.id === e.result.winnerId) || f1;
      const x = loser.pos.x * VISUAL_SCALE;
      const z = loser.pos.z * VISUAL_SCALE;
      const t = clamp((e.phaseTime || 0) / 4, 0, 1);
      desiredPos = new THREE.Vector3(x + 2.0 * mobileFactor, 0.8 + t * 0.4, z + 1.9 * mobileFactor);
      desiredLook = new THREE.Vector3(x, 0.42, z);
      desiredPos.y += Math.sin(this.time * 0.8) * 0.03;
    } else if (e.phase === 'end' && e.result?.winnerId) {
      const w = e.fighters.find((f) => f.id === e.result.winnerId) || f1;
      const x = w.pos.x * VISUAL_SCALE;
      const z = w.pos.z * VISUAL_SCALE;
      desiredPos = new THREE.Vector3(x + 1.55 * mobileFactor, 1.5, z + 2.15 * mobileFactor);
      desiredLook = new THREE.Vector3(x, 1.15, z);
      if (this.beltGroup) {
        desiredLook.set(0, 1.2, 0);
        desiredPos.set(1.1, 1.8, 3.4);
      }
    } else {
      const dist = Math.abs(f1.pos.z - f2.pos.z) + Math.abs(f1.pos.x - f2.pos.x);
      const zoom = clamp(dist * 0.16, 0, 0.45);
      desiredPos = new THREE.Vector3(
        mid.x + (2.85 + zoom) * mobileFactor,
        1.95 + (mobileFactor - 1) * 0.8,
        mid.z + (4.6 + zoom * 2.2) * mobileFactor,
      );
      desiredLook = new THREE.Vector3(mid.x, 1.05, mid.z);
      // subtle orbit with the action
      desiredPos.x += Math.sin(this.time * 0.22) * 0.12;
      desiredPos.y += Math.sin(this.time * 0.35) * 0.04;
    }
    const lambda = entrance ? 2.4 : forced ? 100 : (e.phase === 'knockdown' || e.phase === 'ko' ? 2.0 : 3.4);
    this.camera.position.x = damp(this.camera.position.x, desiredPos.x, lambda, dt);
    this.camera.position.y = damp(this.camera.position.y, desiredPos.y, lambda, dt);
    this.camera.position.z = damp(this.camera.position.z, desiredPos.z, lambda, dt);
    this.cameraTarget.x = damp(this.cameraTarget.x, desiredLook.x, lambda, dt);
    this.cameraTarget.y = damp(this.cameraTarget.y, desiredLook.y, lambda, dt);
    this.cameraTarget.z = damp(this.cameraTarget.z, desiredLook.z, lambda, dt);
    if (this.shake > 0.01) {
      const s = this.shake * 0.12;
      this.camera.position.x += (Math.random() - 0.5) * s;
      this.camera.position.y += (Math.random() - 0.5) * s;
      this.camera.position.z += (Math.random() - 0.5) * s * 0.5;
    }
    this.camera.lookAt(this.cameraTarget);
  }

  renderCamera(dt) {
    if (this.replay) {
      // camera handled by replay frames
      return;
    }
    if (this.shake > 0.01) { /* handled in updateCamera */ }
    this.camera.lookAt(this.cameraTarget);
  }

  updateParticles(dt) {
    for (const spark of this.sparks) {
      if (spark.life <= 0) { spark.sprite.material.opacity = 0; continue; }
      spark.life -= dt;
      const p = 1 - spark.life / spark.max;
      spark.sprite.material.opacity = Math.max(0, 1 - p) * 0.95;
      const s = spark.size * (0.55 + p * 1.3);
      spark.sprite.scale.setScalar(s);
    }
    if (this.impactRingLife > 0) {
      this.impactRingLife -= dt;
      const p = 1 - this.impactRingLife / 0.2;
      this.impactRing.material.opacity = Math.max(0, 1 - p);
      this.impactRing.scale.setScalar(1 + p * 3.5);
    } else {
      this.impactRing.material.opacity = 0;
    }
    // Sweat
    const { pos, vel, life } = this.sweat;
    for (let i = 0; i < this.sweatCount; i++) {
      if (life[i] <= 0) {
        if (pos[i * 3 + 1] > -5) pos[i * 3 + 1] = -10;
        continue;
      }
      life[i] -= dt;
      vel[i * 3 + 1] -= 5.5 * dt;
      pos[i * 3] += vel[i * 3] * dt;
      pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
      pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
      if (pos[i * 3 + 1] < 0.03) { pos[i * 3 + 1] = 0.03; vel[i * 3 + 1] *= -0.2; vel[i * 3] *= 0.5; }
    }
    this.sweat.geo.attributes.position.needsUpdate = true;
    this.flashSprite.material.opacity = this.flash * 0.65;
    this.flashSprite.scale.setScalar(2 + this.flash * 2);
    this.flashSprite.material.color.set(this.flash > 0.5 ? '#ffd27a' : '#ff7a4a');
    if (this.flinchTimer > 0) this.flinchTimer -= dt;
  }

  recordFrame(dt) {
    if (this.engine.phase === 'intro' || this.engine.phase === 'roundEnd') return;
    this.recordTimer += dt;
    if (this.recordTimer < 0.045) return;
    this.recordTimer = 0;
    const frame = {
      t: this.time,
      cam: { pos: this.camera.position.toArray(), look: this.cameraTarget.toArray() },
      boxers: this.boxers.map((b) => ({
        pos: b.root.position.toArray(),
        ry: b.root.rotation.y,
        state: b.getRenderState(),
      })),
      heat: this.heat,
      phase: this.engine.phase,
    };
    this.frames.push(frame);
    if (this.frames.length > 170) this.frames.shift();
  }

  startReplay(seconds = 4, speed = 0.42, onDone = null) {
    if (this.frames.length < 4) { onDone?.(); return false; }
    const cutoff = this.time - seconds;
    const frames = this.frames.filter((f) => f.t >= cutoff);
    if (frames.length < 4) { onDone?.(); return false; }
    this.replay = { frames, index: 0, elapsed: 0, speed, onDone, duration: seconds };
    this._entranceDone = false;
    return true;
  }

  updateReplay(dt) {
    const r = this.replay;
    if (!r) return;
    r.elapsed += dt;
    const frames = r.frames;
    const tStart = frames[0].t;
    const targetT = tStart + r.elapsed * r.speed;
    let i = r.index;
    while (i < frames.length - 1 && frames[i + 1].t <= targetT) i++;
    r.index = i;
    const f = frames[i];
    const next = frames[Math.min(frames.length - 1, i + 1)];
    const p = next.t > f.t ? clamp((targetT - f.t) / (next.t - f.t), 0, 1) : 0;
    for (const [bi, b] of this.boxers.entries()) {
      const a = f.boxers[bi], c = next.boxers[bi];
      if (!a) continue;
      b.root.position.set(lerp(a.pos[0], c.pos[0], p), lerp(a.pos[1], c.pos[1], p), lerp(a.pos[2], c.pos[2], p));
      b.root.rotation.y = lerp(a.ry, c.ry, p);
      const pose = {};
      for (const k of Object.keys(a.state.pose)) pose[k] = lerp(a.state.pose[k], c.state?.pose?.[k] ?? a.state.pose[k], p);
      b.applyRenderState({ ...a.state, pose });
    }
    this.camera.position.set(
      lerp(f.cam.pos[0], next.cam.pos[0], p),
      lerp(f.cam.pos[1], next.cam.pos[1], p),
      lerp(f.cam.pos[2], next.cam.pos[2], p),
    );
    const look = new THREE.Vector3(
      lerp(f.cam.look[0], next.cam.look[0], p),
      lerp(f.cam.look[1], next.cam.look[1], p),
      lerp(f.cam.look[2], next.cam.look[2], p),
    );
    this.camera.lookAt(look);
    this.cameraTarget.copy(look);
    this.heat = f.heat;
    if (r.elapsed * r.speed >= (frames[frames.length - 1].t - tStart) || r.elapsed > 18) {
      const cb = r.onDone;
      this.replay = null;
      this.syncFighters(1);
      cb?.();
    }
  }

  maybeCelebrate() {
    const result = this.engine.result;
    if (!result || this.engine.phase !== 'end') return;
    if (!['KO', 'TKO', 'DEC', 'QUIT'].includes(result.method)) return;
    // Confetti burst
    if (!this.confetti) this.spawnConfetti();
    // Belt appears if a career belt was attached
    if (this.pendingBelt && !this.beltGroup) {
      const belt = makeChampionshipBelt(this.pendingBelt);
      belt.position.set(0, 1.65, 0.1);
      belt.rotation.set(0.15, 0, 0);
      this.scene.add(belt);
      this.beltGroup = belt;
      this.beltSpin = 0;
    }
  }

  showBelt(belt) {
    this.pendingBelt = belt;
    this.maybeCelebrate();
  }

  spawnConfetti() {
    const count = 240;
    const pos = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const palette = [[0.95, 0.76, 0.3], [0.76, 0.1, 0.16], [0.96, 0.96, 0.94], [0.2, 0.7, 0.9]];
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 8;
      pos[i * 3 + 1] = 3 + Math.random() * 4;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 6;
      const c = palette[i % palette.length];
      colors[i * 3] = c[0]; colors[i * 3 + 1] = c[1]; colors[i * 3 + 2] = c[2];
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.PointsMaterial({ size: 0.06, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false });
    const points = new THREE.Points(geo, mat);
    this.scene.add(points);
    this.confetti = { points, pos, vel: Array.from({ length: count }, () => [Math.random() * 0.4, 1 + Math.random() * 1.2, Math.random() * 0.4]), count };
  }

  updateConfetti(dt) {
    if (!this.confetti) return;
    const { pos, vel, count } = this.confetti;
    for (let i = 0; i < count; i++) {
      pos[i * 3] += Math.sin(this.time + i) * dt * 0.35 + vel[i][0] * dt;
      pos[i * 3 + 1] -= vel[i][1] * dt;
      pos[i * 3 + 2] += Math.cos(this.time * 0.7 + i) * dt * 0.2;
      if (pos[i * 3 + 1] < 0.02) pos[i * 3 + 1] = 3 + Math.random() * 3;
    }
    this.confetti.points.geometry.attributes.position.needsUpdate = true;
    if (this.beltGroup) {
      this.beltSpin += dt * 0.7;
      this.beltGroup.rotation.y = Math.sin(this.time * 0.5) * 0.5;
      this.beltGroup.rotation.z = Math.sin(this.time * 0.8) * 0.04;
      this.beltGroup.position.y = 1.65 + Math.sin(this.time * 1.6) * 0.04;
      this.beltGroup.visible = true;
    }
  }

  resize(width, height) {
    this.camera.aspect = width / height;
    this.camera.fov = width / height < 1 ? 56 : 46;
    this.camera.updateProjectionMatrix();
  }

  render() {
    this.updateConfetti(1 / 60);
    this.renderer.render(this.scene, this.camera);
  }

  dispose() {
    this.frames = [];
    this.replay = null;
    for (const b of this.boxers) b.dispose();
    this.arena.dispose();
    this.scene.clear();
  }
}

