// Application shell: renderer, scene backgrounds, single animation loop and navigation.
import * as THREE from 'three';
import { SoundEngine } from './game/audio.js';
import { buildShowcase, buildStudio, buildGym } from './three/environment.js';
import { Boxer } from './three/boxer.js';
import { DEFAULT_APPEARANCE, persist, bus } from './core/store.js';
import { appearanceForFighter } from './core/appearance.js';
import { DIVISIONS } from './core/data.js';

export class App {
  constructor(canvas) {
    this.canvas = canvas;
    const coarse = typeof matchMedia !== 'undefined' && matchMedia('(pointer:coarse)').matches;
    this.mobile = coarse || (typeof innerWidth !== 'undefined' && innerWidth < 860);
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: !this.mobile, alpha: false, powerPreference: 'high-performance', stencil: false });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.quality = this.mobile ? 'medium' : 'high';
    this.applyQuality();
    this.audio = new SoundEngine();
    this.clock = new THREE.Clock();
    this.background = null;
    this.frameHook = null;
    this.navigator = () => {};
    this.save = null;
    this.universe = null;
    this.transition = 0;
    this.menuNews = [];
    this.resize = this.resize.bind(this);
    window.addEventListener('resize', this.resize);
    this.resize();
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
    this.lastFps = 60;
    this.fpsAccum = 0;
    this.fpsFrames = 0;
  }

  applyQuality() {
    const dpr = window.devicePixelRatio || 1;
    const cap = this.quality === 'low' ? 1 : this.quality === 'medium' ? 1.35 : 1.8;
    this.renderer.setPixelRatio(Math.min(dpr, cap));
    this.renderer.shadowMap.enabled = this.quality !== 'low';
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
  }

  setQuality(q) {
    this.quality = q;
    this.applyQuality();
    this.resize();
  }

  boot({ save, universe }) {
    this.save = save;
    this.universe = universe;
    if (save) this.audio.setSettings(save.settings || {});
  }

  navigate(screen, data = {}) {
    this.navigator(screen, data);
  }

  setFrame(fn) {
    this.frameHook = fn;
  }

  clearBackground() {
    if (this.background?.dispose) this.background.dispose();
    if (this.background?.scene) {
      this.background.scene.traverse?.((o) => {
        if (o.isMesh) {
          o.geometry?.dispose?.();
          if (o.material?.map) o.material.map = null;
          o.material?.dispose?.();
        }
      });
    }
    this.background = null;
    this.setFrame(null);
  }

  defaultAppearance() {
    if (this.save?.profile?.appearance) return this.save.profile.appearance;
    return appearanceForFighter({ id: 'hero-default', name: 'Kaito', division: 'middle' });
  }

  showMenu() {
    this.clearBackground();
    const env = buildShowcase();
    const app = this.save?.profile?.appearance || this.defaultAppearance();
    const hero = new Boxer(app, { robe: false, quality: this.quality });
    const mobile = this.mobile;
    hero.root.position.set(mobile ? 0 : 0.7, 0.26, 0.15);
    hero.root.rotation.y = -0.12;
    env.scene.add(hero.root);
    hero.setExpression('focused');
    const camera = new THREE.PerspectiveCamera(mobile ? 48 : 38, window.innerWidth / window.innerHeight, 0.1, 60);
    const setCam = () => {
      if (window.innerWidth / window.innerHeight < 1) {
        camera.position.set(1.3, 1.55, 4.9);
        camera.lookAt(0.0, 1.2, 0);
      } else {
        camera.position.set(2.2, 1.55, 4.35);
        camera.lookAt(0.45, 1.15, 0);
      }
    };
    setCam();
    let t = 0;
    this.background = {
      kind: 'showcase', scene: env.scene, camera, boxer: hero,
      update: (dt) => {
        t += dt;
        hero.update(dt, { stamina: 100, idle: true });
        hero.root.rotation.y = -0.12 + Math.sin(t * 0.22) * 0.18;
        env.update(dt);
        camera.position.x += Math.sin(t * 0.18) * 0.0006;
        camera.lookAt(mobile ? 0 : 0.45, 1.15, 0);
      },
      resize: () => { camera.aspect = window.innerWidth / window.innerHeight; camera.fov = window.innerWidth / window.innerHeight < 1 ? 48 : 38; camera.updateProjectionMatrix(); setCam(); },
      render: () => this.renderer.render(env.scene, camera),
      dispose: () => { hero.dispose(); env.dispose(); },
    };
  }

  showEditor(appearance) {
    this.clearBackground();
    const env = buildStudio();
    const boxer = new Boxer(appearance, { robe: false, quality: this.quality });
    boxer.root.position.set(0, 0.14, 0);
    boxer.setExpression('focused');
    env.scene.add(boxer.root);
    const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 60);
    const place = () => {
      const portrait = window.innerWidth / window.innerHeight < 0.9;
      camera.position.set(0, portrait ? 1.65 : 1.5, portrait ? 5.2 : 4.5);
      camera.lookAt(0, portrait ? 1.1 : 1.05, 0);
    };
    place();
    let t = 0;
    let rot = 0;
    this.background = {
      kind: 'studio', scene: env.scene, camera, boxer,
      update: (dt) => {
        t += dt;
        if (!this.editorDragging) boxer.root.rotation.y = Math.sin(t * 0.3) * 0.22;
        else boxer.root.rotation.y = rot;
        boxer.update(dt, { stamina: 100, idle: true });
        env.update(dt);
      },
      setRotation: (r) => { rot = r; this.editorDragging = true; setTimeout(() => { this.editorDragging = false; }, 1600); },
      resize: () => { camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); place(); },
      render: () => this.renderer.render(env.scene, camera),
      dispose: () => { boxer.dispose(); env.dispose(); },
    };
    return boxer;
  }

  showGym() {
    this.clearBackground();
    const env = buildGym();
    const appearance = this.save?.profile?.appearance || this.defaultAppearance();
    const player = new Boxer(appearance, { robe: false, quality: this.quality });
    player.root.position.set(2.2, 0.02, -5.2);
    player.root.rotation.y = Math.PI * 0.92;
    env.scene.add(player.root);
    const camera = new THREE.PerspectiveCamera(44, window.innerWidth / window.innerHeight, 0.1, 60);
    const place = () => {
      const portrait = window.innerWidth / window.innerHeight < 0.9;
      camera.position.set(portrait ? 3.2 : 4.5, 1.8, portrait ? 4.6 : 5.4);
      camera.lookAt(0, 1.05, -1.4);
    };
    place();
    let t = 0;
    this.background = {
      kind: 'gym', scene: env.scene, camera, coach: env.coach, player,
      update: (dt) => {
        t += dt;
        env.update(dt);
        const cycle = t % 2.1;
        const punch = cycle < 0.2 ? 'jab' : null;
        player.update(dt, {
          stamina: 82, action: punch, actionTime: cycle % 0.3, actionDur: 0.3,
          moveZ: 0, expression: 'focused',
        });
        env.coach.update(dt, { stamina: 95, idle: true });
      },
      resize: () => { camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); place(); },
      render: () => this.renderer.render(env.scene, camera),
      dispose: () => { player.dispose(); env.dispose(); },
    };
  }

  showFight(view) {
    this.clearBackground();
    this.background = {
      kind: 'fight', scene: view.scene, camera: view.camera, view,
      update: (dt) => view.update(dt),
      render: () => view.render(),
      resize: () => view.resize(window.innerWidth, window.innerHeight),
      dispose: () => view.dispose(),
    };
    view.resize(window.innerWidth, window.innerHeight);
  }

  recreateMenu() {
    if (this.background?.kind === 'showcase') this.showMenu();
  }

  saveNow() {
    persist(this.save, true);
  }

  resize() {
    const w = window.innerWidth, h = window.innerHeight;
    this.renderer.setSize(w, h, false);
    this.applyQuality();
    if (this.background?.resize) this.background.resize();
  }

  loop() {
    requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, this.clock.getDelta());
    this.fpsAccum += dt;
    this.fpsFrames++;
    if (this.fpsAccum > 1) {
      this.lastFps = Math.round(this.fpsFrames / this.fpsAccum);
      this.fpsAccum = 0;
      this.fpsFrames = 0;
    }
    this.audio.update(dt);
    try {
      if (this.background?.update) this.background.update(dt);
      if (this.frameHook) this.frameHook(dt);
      if (this.background?.render) this.background.render();
    } catch (err) {
      console.error('Frame error', err);
    }
    bus.emit('frame', dt);
  }
}

@import '/fonts/fonts.css';

:root {
  --bg: #060608;
  --bg2: #0b0b10;
  --panel: rgba(18, 18, 25, 0.86);
  --panel-solid: #111117;
  --panel2: rgba(28, 28, 38, 0.72);
  --line: rgba(255, 255, 255, 0.09);
  --line2: rgba(255, 255, 255, 0.16);
  --text: #f4f1ea;
  --muted: #9a99a8;
  --muted2: #6d6c7c;
  --gold: #f2c14e;
  --gold2: #c9922b;
  --red: #e11d48;
  --red2: #a30f30;
  --green: #34d399;
  --blue: #38bdf8;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --r: 14px;
  --r-sm: 9px;
  --font-display: 'Bebas Neue', Impact, sans-serif;
  --font-cond: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --font-body: 'Barlow', system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; min-height: 100%; background: var(--bg); color: var(--text); font-family: var(--font-body); }
body { overflow: hidden; overscroll-behavior: none; -webkit-font-smoothing: antialiased; }
#game-canvas { position: fixed; inset: 0; width: 100vw; height: 100vh; display: block; z-index: 0; outline: none; }
#ui-root { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#ui-root > * { pointer-events: auto; }
button, input, select, textarea { font: inherit; color: inherit; }
button { -webkit-tap-highlight-color: transparent; }
a { color: var(--gold); text-decoration: none; }
::selection { background: rgba(242, 193, 78, 0.3); color: #fff; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: rgba(255, 255, 255, 0.03); }
::-webkit-scrollbar-thumb { background: rgba(242, 193, 78, 0.25); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: rgba(242, 193, 78, 0.45); }

.ic { flex: none; display: inline-block; vertical-align: middle; }

/* -------------------------------- Boot -------------------------------- */
.boot-screen {
  position: fixed; inset: 0; z-index: 100; background: #050507; display: grid; place-items: center;
  transition: opacity 0.7s ease, visibility 0.7s; pointer-events: auto;
}
.boot-screen.hide { opacity: 0; visibility: hidden; }
.boot-inner { text-align: center; width: min(440px, 82vw); }
.boot-mark { display: flex; justify-content: center; margin-bottom: 18px; }
.boot-logo { font-family: var(--font-display); font-size: clamp(54px, 9vw, 86px); line-height: 0.82; letter-spacing: 0.02em; }
.boot-logo span { color: var(--gold); }
.boot-tag { font-family: var(--font-cond); letter-spacing: 0.34em; font-size: 12px; color: var(--muted); margin-top: 14px; text-transform: uppercase; }
.boot-bar { margin-top: 42px; height: 2px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--red), var(--gold)); transition: width 0.35s ease; }
.boot-phase { margin-top: 14px; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.18em; color: var(--muted2); text-transform: uppercase; min-height: 16px; }
.boot-ring { width: 74px; height: 74px; margin: 0 auto; border: 1px solid rgba(242, 193, 78, 0.22); border-radius: 50%; position: relative; display: grid; place-items: center; }
.boot-ring::before { content: ''; position: absolute; inset: -1px; border-radius: 50%; border: 2px solid transparent; border-top-color: var(--gold); animation: spin 1.3s linear infinite; }
.boot-ring::after { content: 'TG'; font-family: var(--font-display); font-size: 26px; color: var(--gold); }
@keyframes spin { to { transform: rotate(360deg); } }

/* -------------------------------- Typography / common -------------------------------- */
.display { font-family: var(--font-display); font-weight: 400; text-transform: uppercase; letter-spacing: 0.015em; line-height: 0.92; }
.kicker { font-family: var(--font-cond); text-transform: uppercase; letter-spacing: 0.28em; font-size: 11px; font-weight: 600; color: var(--gold); }
.muted { color: var(--muted); }
.tiny { font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.06em; color: var(--muted); }
.gold { color: var(--gold); }
.red { color: #ff5a72; }
.green { color: var(--green); }
.cond { font-family: var(--font-cond); }

.screen {
  position: absolute; inset: 0; overflow-y: auto; overflow-x: hidden; padding: 26px clamp(18px, 4vw, 64px) 64px;
  background:
    radial-gradient(120% 80% at 85% 0%, rgba(225, 29, 72, 0.09), transparent 55%),
    linear-gradient(180deg, rgba(6, 6, 8, 0.62) 0%, rgba(6, 6, 8, 0.28) 32%, rgba(6, 6, 8, 0.82) 100%);
  animation: screenIn 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.screen.plain { background: linear-gradient(180deg, rgba(6, 6, 8, 0.9), rgba(6, 6, 8, 0.75)); backdrop-filter: blur(8px); }
.screen.compact { padding-top: 14px; }
@keyframes screenIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
.screen-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin-bottom: 26px; flex-wrap: wrap; }
.screen-title { font-family: var(--font-display); font-size: clamp(34px, 5vw, 62px); line-height: 0.9; margin: 6px 0 0; letter-spacing: 0.015em; }
.screen-sub { color: var(--muted); font-size: 14px; max-width: 560px; margin: 8px 0 0; line-height: 1.55; }
.head-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.section-title { display: flex; align-items: baseline; justify-content: space-between; gap: 14px; margin: 0 0 14px; }
.section-title h2 { font-family: var(--font-display); font-size: 26px; margin: 0; letter-spacing: 0.02em; }
.section-title h3 { font-family: var(--font-cond); font-size: 15px; letter-spacing: 0.12em; text-transform: uppercase; margin: 0; color: var(--muted); }
.divider { height: 1px; background: var(--line); margin: 22px 0; }

/* -------------------------------- Buttons -------------------------------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 9px; border: 1px solid var(--line2);
  background: rgba(255, 255, 255, 0.045); color: var(--text); padding: 12px 18px; border-radius: 8px;
  font-family: var(--font-cond); font-weight: 600; font-size: 14px; letter-spacing: 0.12em; text-transform: uppercase;
  cursor: pointer; transition: 0.18s ease; position: relative; overflow: hidden; white-space: nowrap; text-decoration: none;
}
.btn:hover { background: rgba(255, 255, 255, 0.09); border-color: rgba(255, 255, 255, 0.3); transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn:disabled { opacity: 0.38; cursor: not-allowed; transform: none; }
.btn-primary { background: linear-gradient(135deg, #f7d072, #dca52f); border-color: #f2c14e; color: #1a1305; box-shadow: 0 10px 30px rgba(242, 193, 78, 0.18); }
.btn-primary:hover { background: linear-gradient(135deg, #ffe197, #eab340); border-color: #ffe3a1; color: #120d03; }
.btn-red { background: linear-gradient(135deg, #f43f5e, #b31237); border-color: #f43f5e; color: #fff; box-shadow: 0 10px 30px rgba(225, 29, 72, 0.2); }
.btn-red:hover { background: linear-gradient(135deg, #fb7185, #d61a45); }
.btn-gold-outline { background: transparent; border-color: rgba(242, 193, 78, 0.55); color: var(--gold); }
.btn-gold-outline:hover { background: rgba(242, 193, 78, 0.1); border-color: var(--gold); }
.btn-ghost { background: transparent; border-color: transparent; color: var(--muted); }
.btn-ghost:hover { color: var(--text); background: rgba(255, 255, 255, 0.06); }
.btn-sm { padding: 8px 12px; font-size: 12px; letter-spacing: 0.1em; border-radius: 6px; }
.btn-lg { padding: 16px 26px; font-size: 17px; }
.btn-block { width: 100%; }
.btn-icon { width: 42px; height: 42px; padding: 0; border-radius: 8px; }
.btn-icon.sm { width: 32px; height: 32px; }
.btn .ic { opacity: 0.9; }

.chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border-radius: 999px; background: rgba(255, 255, 255, 0.06); font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.06em; color: var(--muted); border: 1px solid var(--line); }
.chip.gold { color: var(--gold); background: rgba(242, 193, 78, 0.09); border-color: rgba(242, 193, 78, 0.22); }
.chip.red { color: #ff8197; background: rgba(225, 29, 72, 0.09); border-color: rgba(225, 29, 72, 0.25); }
.chip.green { color: #6ee7b7; background: rgba(52, 211, 153, 0.08); border-color: rgba(52, 211, 153, 0.22); }
.tag { display: inline-block; font-family: var(--font-cond); font-size: 10px; font-weight: 600; letter-spacing: 0.18em; text-transform: uppercase; padding: 4px 7px; border-radius: 3px; background: var(--panel2); color: var(--muted); }
.tag.gold { color: #1a1305; background: var(--gold); }
.tag.red { color: #fff; background: var(--red); }
.tag.green { background: rgba(52, 211, 153, 0.16); color: #6ee7b7; }
.tag.blue { background: rgba(56, 189, 248, 0.14); color: #7dd3fc; }

.panel { position: relative; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); backdrop-filter: blur(14px); overflow: hidden; }
.panel-inner { padding: 22px; }
.panel.flush { overflow: visible; }
.panel-gold { border-color: rgba(242, 193, 78, 0.28); }
.panel-red { border-color: rgba(225, 29, 72, 0.26); }
.panel::after { content: ''; position: absolute; inset: 0; pointer-events: none; border-radius: inherit; box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07); }
.panel-head { padding: 18px 20px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.panel-head h3 { margin: 0; font-family: var(--font-cond); text-transform: uppercase; letter-spacing: 0.14em; font-size: 14px; }
.panel-body { padding: 20px; }

/* -------------------------------- Topbar -------------------------------- */
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 30px;
  padding: 8px 0 14px; border-bottom: 1px solid rgba(255, 255, 255, 0.07); position: relative; z-index: 5;
}
.brand-mini { display: flex; align-items: center; gap: 12px; cursor: pointer; background: none; border: none; padding: 0; }
.brand-mark { width: 34px; height: 34px; display: grid; place-items: center; background: linear-gradient(145deg, var(--gold), #a2711a); color: #120d03; font-family: var(--font-display); font-size: 17px; border-radius: 6px; box-shadow: 0 6px 18px rgba(242, 193, 78, 0.2); }
.brand-text { text-align: left; }
.brand-text b { display: block; font-family: var(--font-display); font-size: 20px; letter-spacing: 0.06em; line-height: 0.9; }
.brand-text span { font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.3em; color: var(--gold); text-transform: uppercase; }
.topnav { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.topnav button { background: none; border: none; color: var(--muted); padding: 8px 11px; border-radius: 6px; cursor: pointer; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; display: inline-flex; align-items: center; gap: 7px; }
.topnav button:hover { color: var(--text); background: rgba(255, 255, 255, 0.05); }
.topnav button.active { color: var(--gold); background: rgba(242, 193, 78, 0.08); }
.userbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.wallet { display: flex; gap: 6px; }
.wallet .chip { background: rgba(9, 9, 12, 0.7); }
.profile-pill { display: flex; align-items: center; gap: 9px; background: rgba(9, 9, 12, 0.65); border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px 4px 4px; cursor: pointer; }
.profile-pill .avatar { width: 30px; height: 30px; border-radius: 50%; background: linear-gradient(140deg, #5a1e2a, #1c1c25); display: grid; place-items: center; font-family: var(--font-display); font-size: 14px; color: var(--gold); border: 1px solid rgba(242, 193, 78, 0.3); overflow: hidden; }
.profile-pill b { font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.07em; font-weight: 600; }
.profile-pill small { display: block; font-family: var(--font-cond); font-size: 9px; color: var(--muted); letter-spacing: 0.14em; }
.sound-toggle { width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--line); background: rgba(9, 9, 12, 0.65); color: var(--muted); display: grid; place-items: center; cursor: pointer; }
.sound-toggle:hover { color: var(--gold); border-color: rgba(242, 193, 78, 0.35); }

/* -------------------------------- Main menu -------------------------------- */
.main-menu { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: center; padding: 4vh clamp(22px, 6vw, 96px) 90px; pointer-events: none; }
.main-menu > * { pointer-events: auto; }
.menu-left { width: min(430px, 92vw); }
.logo-block { margin-bottom: 26px; }
.logo-eyebrow { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.logo-eyebrow .line { width: 34px; height: 1px; background: var(--gold); }
.logo-eyebrow span { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.4em; color: var(--gold); text-transform: uppercase; }
.main-logo { font-family: var(--font-display); font-size: clamp(68px, 9.2vw, 128px); line-height: 0.76; letter-spacing: 0.01em; text-shadow: 0 12px 50px rgba(0, 0, 0, 0.8); }
.main-logo .tg { color: var(--text); display: block; }
.main-logo .box { color: var(--gold); display: block; margin-left: 0.09em; }
.main-logo .box::after { content: ''; }
.logo-sub { display: flex; align-items: center; gap: 9px; margin-top: 16px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.34em; color: #cfcbbe; text-transform: uppercase; }
.logo-sub::before { content: ''; width: 8px; height: 8px; background: var(--red); transform: rotate(45deg); display: inline-block; }
.menu-list { display: flex; flex-direction: column; gap: 2px; margin-top: 24px; }
.menu-btn {
  position: relative; display: flex; align-items: center; gap: 14px; width: 100%; text-align: left;
  background: linear-gradient(90deg, rgba(16, 16, 22, 0.8), rgba(16, 16, 22, 0.32)); border: 1px solid rgba(255, 255, 255, 0.07);
  border-left: 2px solid rgba(255, 255, 255, 0.1); color: var(--text); padding: 13px 16px; cursor: pointer;
  transition: 0.2s ease; border-radius: 2px 8px 8px 2px; backdrop-filter: blur(8px);
}
.menu-btn .idx { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); width: 16px; letter-spacing: 0.1em; }
.menu-btn .ic { color: var(--muted); transition: 0.2s; }
.menu-btn b { font-family: var(--font-display); font-size: 22px; letter-spacing: 0.06em; font-weight: 400; line-height: 1; flex: 1; }
.menu-btn small { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.08em; color: var(--muted); text-transform: uppercase; opacity: 0; transform: translateX(-4px); transition: 0.2s; }
.menu-btn .go { color: var(--muted2); font-size: 15px; }
.menu-btn:hover { background: linear-gradient(90deg, rgba(242, 193, 78, 0.13), rgba(242, 193, 78, 0.02)); border-color: rgba(242, 193, 78, 0.25); border-left-color: var(--gold); transform: translateX(3px); }
.menu-btn:hover .ic, .menu-btn:hover .go { color: var(--gold); }
.menu-btn:hover small { opacity: 1; transform: none; }
.menu-btn.primary { border-left-color: var(--red); background: linear-gradient(90deg, rgba(225, 29, 72, 0.18), rgba(16, 16, 22, 0.4)); }
.menu-btn.primary .ic { color: #ff6f86; }
.menu-btn.primary:hover { border-color: rgba(225, 29, 72, 0.4); background: linear-gradient(90deg, rgba(225, 29, 72, 0.3), rgba(16, 16, 22, 0.4)); }
.menu-btn.locked { opacity: 0.45; }
.menu-bottom { margin-top: 20px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.menu-ticker {
  position: absolute; left: 0; right: 0; bottom: 0; border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, rgba(6, 6, 8, 0.2), rgba(6, 6, 8, 0.9)); padding: 11px clamp(22px, 6vw, 96px);
  display: flex; align-items: center; gap: 16px; overflow: hidden; pointer-events: auto;
}
.ticker-label { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.2em; color: #1a1305; background: var(--gold); padding: 4px 8px; border-radius: 3px; flex: none; }
.ticker-track { white-space: nowrap; overflow: hidden; font-family: var(--font-cond); font-size: 12px; color: #cfcbbe; letter-spacing: 0.05em; }
.ticker-track span { display: inline-block; animation: ticker 40s linear infinite; padding-left: 100%; }
@keyframes ticker { from { transform: translateX(0); } to { transform: translateX(-100%); } }
.hero-badge { position: absolute; right: clamp(22px, 6vw, 96px); bottom: 110px; text-align: right; pointer-events: none; }
.hero-badge .name { font-family: var(--font-display); font-size: 30px; color: var(--text); }
.hero-badge .meta { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.22em; color: var(--gold); text-transform: uppercase; }
.version-stamp { position: fixed; right: 16px; top: 16px; font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.16em; color: rgba(255, 255, 255, 0.25); pointer-events: none; z-index: 20; }
.menu-corner { position: absolute; top: 22px; right: clamp(18px, 4vw, 52px); display: flex; gap: 8px; align-items: center; }
.menu-corner .chip { background: rgba(9, 9, 12, 0.7); backdrop-filter: blur(8px); }

/* -------------------------------- Grids / cards -------------------------------- */
.grid { display: grid; gap: 16px; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.grid-auto { grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); }
.stack { display: flex; flex-direction: column; gap: 14px; }
.row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.row.between { justify-content: space-between; }
.spacer { flex: 1; }

.stat-tile { background: rgba(255, 255, 255, 0.035); border: 1px solid var(--line); border-radius: 10px; padding: 14px; position: relative; overflow: hidden; }
.stat-tile .label { font-family: var(--font-cond); text-transform: uppercase; letter-spacing: 0.13em; font-size: 10px; color: var(--muted); }
.stat-tile .value { font-family: var(--font-display); font-size: 30px; line-height: 1.05; margin-top: 4px; }
.stat-tile .sub { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); letter-spacing: 0.06em; }
.stat-tile.accent { border-color: rgba(242, 193, 78, 0.2); background: linear-gradient(135deg, rgba(242, 193, 78, 0.08), rgba(255, 255, 255, 0.02)); }

.avatar-lg { width: 74px; height: 74px; border-radius: 50%; border: 1px solid rgba(242, 193, 78, 0.35); background: radial-gradient(circle at 35% 25%, #6b2733, #13131a 70%); display: grid; place-items: center; font-family: var(--font-display); font-size: 30px; color: var(--gold); overflow: hidden; flex: none; }
.fighter-card { display: flex; gap: 16px; align-items: center; }
.fighter-card .name { font-family: var(--font-display); font-size: 30px; line-height: 1; }
.fighter-card .nick { color: var(--gold); font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; margin-top: 4px; }

.bars { display: flex; flex-direction: column; gap: 7px; }
.bar-row { display: grid; grid-template-columns: 86px 1fr 34px; gap: 8px; align-items: center; font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
.bar-track { height: 5px; background: rgba(255, 255, 255, 0.08); border-radius: 6px; overflow: hidden; }
.bar-fill { height: 100%; background: linear-gradient(90deg, #b98727, var(--gold)); border-radius: 6px; transition: width 0.5s ease; }
.bar-fill.red { background: linear-gradient(90deg, #8e0f2c, var(--red)); }
.bar-fill.green { background: linear-gradient(90deg, #0f766e, var(--green)); }
.attr-value { text-align: right; color: var(--text); }

/* -------------------------------- Career -------------------------------- */
.career-top { display: grid; grid-template-columns: 1.35fr 0.9fr; gap: 18px; margin-bottom: 18px; }
.career-hero { padding: 24px; display: flex; gap: 22px; align-items: center; position: relative; overflow: hidden; background: linear-gradient(120deg, rgba(25, 17, 18, 0.95), rgba(14, 14, 20, 0.9)); border: 1px solid var(--line); border-radius: var(--r); }
.career-hero::before { content: ''; position: absolute; right: -60px; top: -80px; width: 280px; height: 280px; background: radial-gradient(circle, rgba(225, 29, 72, 0.22), transparent 65%); pointer-events: none; }
.career-hero .fighter-card .name { font-size: clamp(34px, 4vw, 48px); }
.career-hero .profile-stats { display: flex; gap: 22px; margin-top: 14px; flex-wrap: wrap; }
.career-hero .profile-stats b { display: block; font-family: var(--font-display); font-size: 22px; line-height: 1; }
.career-hero .profile-stats span { font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.16em; color: var(--muted); text-transform: uppercase; }
.career-side { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.next-fight-card { grid-column: 1 / -1; padding: 18px 20px; background: linear-gradient(115deg, rgba(225, 29, 72, 0.14), rgba(17, 17, 23, 0.9) 55%); border: 1px solid rgba(225, 29, 72, 0.25); border-radius: var(--r); position: relative; overflow: hidden; }
.next-fight-card::after { content: 'VS'; position: absolute; right: 18px; bottom: -6px; font-family: var(--font-display); font-size: 78px; color: rgba(255, 255, 255, 0.045); pointer-events: none; }
.next-fight-card .kicker { color: #ff7c91; }
.next-fight-card h3 { font-family: var(--font-display); font-size: 28px; margin: 4px 0 2px; }
.next-fight-card .meta { font-family: var(--font-cond); font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
.offer-list { display: flex; flex-direction: column; gap: 10px; }
.offer-card { display: flex; align-items: center; gap: 14px; padding: 14px 16px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255, 255, 255, 0.025); transition: 0.18s; }
.offer-card:hover { border-color: rgba(242, 193, 78, 0.25); background: rgba(242, 193, 78, 0.045); }
.offer-card.selected { border-color: var(--gold); background: rgba(242, 193, 78, 0.07); }
.offer-card .opp { flex: 1; min-width: 0; }
.offer-card .opp b { font-family: var(--font-cond); font-size: 15px; letter-spacing: 0.03em; display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.offer-card .opp span { font-family: var(--font-cond); font-size: 10px; color: var(--muted); letter-spacing: 0.06em; }
.offer-card .purse { text-align: right; }
.offer-card .purse b { display: block; font-family: var(--font-display); font-size: 22px; color: var(--gold); }
.offer-card .purse span { font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.1em; color: var(--muted); }
.dashboard-grid { display: grid; grid-template-columns: 1.25fr 1fr; gap: 18px; }
.news-mini { display: flex; flex-direction: column; }
.news-mini .item { padding: 12px 0; border-bottom: 1px solid var(--line); display: flex; gap: 12px; align-items: flex-start; cursor: pointer; }
.news-mini .item:last-child { border-bottom: none; }
.news-mini .item:hover .t { color: var(--gold); }
.news-mini .item .t { font-family: var(--font-cond); font-size: 14px; font-weight: 600; line-height: 1.25; transition: 0.18s; }
.news-mini .item .d { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); margin-top: 3px; letter-spacing: 0.06em; }
.news-mini .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--gold); margin-top: 6px; flex: none; }
.training-row { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--line); }
.training-row:last-child { border-bottom: none; }
.training-row .ico { width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center; background: rgba(242, 193, 78, 0.08); color: var(--gold); flex: none; }
.training-row b { font-family: var(--font-cond); font-size: 14px; }
.training-row span { display: block; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.progress { height: 4px; border-radius: 4px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.progress i { display: block; height: 100%; background: linear-gradient(90deg, var(--red), var(--gold)); }
.day-badge { display: flex; align-items: center; gap: 8px; font-family: var(--font-cond); font-size: 12px; color: var(--muted); }

/* -------------------------------- Rankings -------------------------------- */
.rank-layout { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(260px, 0.65fr); gap: 18px; align-items: start; }
.rank-list { display: flex; flex-direction: column; }
.rank-row { display: grid; grid-template-columns: 42px 1fr auto auto; gap: 14px; align-items: center; padding: 11px 14px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); transition: 0.15s; cursor: pointer; }
.rank-row:hover { background: rgba(255, 255, 255, 0.035); }
.rank-row.me { background: linear-gradient(90deg, rgba(242, 193, 78, 0.12), transparent); border-left: 2px solid var(--gold); }
.rank-row .num { font-family: var(--font-display); font-size: 20px; color: var(--muted2); text-align: center; }
.rank-row .num.top { color: var(--gold); }
.rank-row .who b { font-family: var(--font-cond); font-size: 15px; font-weight: 600; }
.rank-row .who span { display: block; font-family: var(--font-cond); font-size: 10px; color: var(--muted); letter-spacing: 0.06em; }
.rank-row .rec { font-family: var(--font-cond); font-size: 13px; color: var(--muted); text-align: right; }
.rank-row .pts { font-family: var(--font-display); font-size: 18px; color: var(--gold); text-align: right; min-width: 56px; }
.champ-card { background: linear-gradient(135deg, rgba(242, 193, 78, 0.14), rgba(18, 18, 25, 0.95)); border: 1px solid rgba(242, 193, 78, 0.3); border-radius: var(--r); padding: 20px; position: relative; overflow: hidden; }
.champ-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 80% 20%, rgba(242, 193, 78, 0.14), transparent 60%); }
.champ-card .belt-ico { color: var(--gold); margin-bottom: 8px; }
.champ-card .name { font-family: var(--font-display); font-size: 28px; line-height: 1; }
.champ-card .nick { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.12em; color: var(--gold); text-transform: uppercase; }
.division-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 16px; }
.division-tabs button { border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03); color: var(--muted); padding: 7px 11px; border-radius: 6px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.07em; cursor: pointer; }
.division-tabs button:hover { color: var(--text); border-color: var(--line2); }
.division-tabs button.active { background: rgba(242, 193, 78, 0.12); border-color: rgba(242, 193, 78, 0.4); color: var(--gold); }
.org-tabs { display: flex; gap: 8px; }
.org-tabs button { background: none; border: 1px solid var(--line); color: var(--muted); border-radius: 6px; padding: 6px 10px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.1em; cursor: pointer; }
.org-tabs button.active { color: #111; background: var(--gold); border-color: var(--gold); }

/* -------------------------------- News -------------------------------- */
.news-layout { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(300px, 0.8fr); gap: 18px; align-items: start; }
.news-feature { position: relative; min-height: 380px; border-radius: var(--r); overflow: hidden; border: 1px solid var(--line); background: #121218; cursor: pointer; }
.news-art { position: absolute; inset: 0; background-size: cover; }
.news-art::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 20%, rgba(6, 6, 8, 0.92) 90%); }
.news-feature .content { position: absolute; left: 0; right: 0; bottom: 0; padding: 28px; z-index: 2; }
.news-feature h2 { font-family: var(--font-display); font-size: clamp(28px, 3.2vw, 46px); line-height: 0.95; margin: 10px 0; max-width: 620px; }
.news-feature p { font-family: var(--font-cond); color: #bbb8ae; font-size: 14px; line-height: 1.45; max-width: 580px; margin: 0; }
.news-item-card { display: flex; gap: 14px; padding: 14px 0; border-bottom: 1px solid var(--line); cursor: pointer; }
.news-item-card .thumb { width: 84px; height: 62px; border-radius: 7px; flex: none; background: #191922; border: 1px solid var(--line); position: relative; overflow: hidden; }
.news-item-card .thumb::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 60% 30%, rgba(242, 193, 78, 0.35), transparent 55%); }
.news-item-card .thumb span { position: absolute; bottom: 4px; right: 6px; font-family: var(--font-display); font-size: 20px; color: rgba(255, 255, 255, 0.16); }
.news-item-card .t { font-family: var(--font-cond); font-weight: 600; font-size: 14px; line-height: 1.25; transition: 0.18s; }
.news-item-card:hover .t { color: var(--gold); }
.news-item-card .meta { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); margin-top: 5px; letter-spacing: 0.06em; }
.article-body { font-size: 15px; line-height: 1.75; color: #c9c6bd; white-space: pre-line; }
.article-body p { margin: 0 0 18px; }
.news-filter { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 18px; }
.news-filter button { background: transparent; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.08em; padding: 6px 11px; cursor: pointer; }
.news-filter button.active { color: #161006; background: var(--gold); border-color: var(--gold); }

/* -------------------------------- Shop -------------------------------- */
.shop-layout { display: grid; grid-template-columns: 1fr; gap: 18px; }
.shop-card { padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: rgba(255, 255, 255, 0.025); display: flex; flex-direction: column; gap: 12px; transition: 0.18s; position: relative; overflow: hidden; }
.shop-card:hover { border-color: rgba(242, 193, 78, 0.25); transform: translateY(-2px); }
.shop-card.owned { border-color: rgba(52, 211, 153, 0.25); }
.shop-card .ico-big { height: 74px; border-radius: 9px; display: grid; place-items: center; background: radial-gradient(circle at 50% 30%, rgba(242, 193, 78, 0.12), rgba(255, 255, 255, 0.02)); color: var(--gold); border: 1px solid var(--line); }
.shop-card h4 { margin: 0; font-family: var(--font-cond); font-size: 15px; letter-spacing: 0.03em; }
.shop-card p { margin: 0; font-size: 12px; line-height: 1.45; color: var(--muted); flex: 1; }
.price-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.price { font-family: var(--font-display); font-size: 20px; color: var(--gold); }
.price small { font-family: var(--font-cond); font-size: 9px; color: var(--muted); margin-left: 3px; letter-spacing: 0.1em; }

/* -------------------------------- Editor -------------------------------- */
.editor { position: absolute; inset: 0; display: grid; grid-template-columns: 210px minmax(260px, 1fr) 350px; gap: 0; pointer-events: none; }
.editor > * { pointer-events: auto; }
.editor-left { padding: 18px 0 18px 18px; display: flex; flex-direction: column; gap: 4px; justify-content: center; }
.editor-left .cat-btn { display: flex; align-items: center; gap: 11px; background: rgba(8, 8, 11, 0.55); border: 1px solid transparent; border-left: 2px solid transparent; color: var(--muted); padding: 10px 13px; cursor: pointer; text-align: left; border-radius: 2px 7px 7px 2px; backdrop-filter: blur(8px); font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.09em; text-transform: uppercase; }
.editor-left .cat-btn:hover { color: var(--text); background: rgba(255, 255, 255, 0.05); }
.editor-left .cat-btn.active { color: var(--gold); border-left-color: var(--gold); background: rgba(242, 193, 78, 0.09); }
.editor-left .cat-btn .ic { color: inherit; }
.editor-left .done { margin-top: 14px; }
.editor-center { position: relative; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; padding-bottom: 20px; pointer-events: none; }
.editor-center > * { pointer-events: auto; }
.editor-center .hint { font-family: var(--font-cond); font-size: 10px; color: rgba(255, 255, 255, 0.3); letter-spacing: 0.16em; text-transform: uppercase; margin-bottom: 10px; }
.editor-stats { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; }
.editor-stat { background: rgba(6, 6, 8, 0.55); border: 1px solid var(--line); border-radius: 7px; padding: 6px 11px; text-align: center; backdrop-filter: blur(8px); min-width: 62px; }
.editor-stat b { display: block; font-family: var(--font-display); font-size: 18px; line-height: 1; }
.editor-stat span { font-family: var(--font-cond); font-size: 8px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
.editor-right { display: flex; flex-direction: column; background: rgba(8, 8, 11, 0.78); border-left: 1px solid var(--line); backdrop-filter: blur(16px); max-height: 100vh; }
.editor-head { padding: 18px 18px 14px; border-bottom: 1px solid var(--line); }
.editor-head h2 { font-family: var(--font-display); font-size: 28px; margin: 0; }
.editor-head .sub { font-family: var(--font-cond); font-size: 10px; color: var(--muted); letter-spacing: 0.12em; text-transform: uppercase; margin-top: 2px; }
.editor-scroll { overflow-y: auto; flex: 1; padding: 14px 18px 18px; }
.editor-group { margin-bottom: 18px; }
.editor-group h3 { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: var(--gold); margin: 0 0 9px; display: flex; justify-content: space-between; }
.editor-group h3 span { color: var(--muted2); font-weight: 400; }
.option-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(46px, 1fr)); gap: 6px; }
.option { height: 46px; border: 1px solid var(--line); border-radius: 6px; background: rgba(255, 255, 255, 0.025); cursor: pointer; position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; color: var(--muted); font-family: var(--font-cond); font-size: 10px; padding: 3px; text-align: center; transition: 0.15s; }
.option:hover { border-color: var(--line2); transform: translateY(-1px); }
.option.active { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold), 0 4px 14px rgba(242, 193, 78, 0.15); }
.option .swatch { position: absolute; inset: 0; }
.option .lbl { position: relative; z-index: 2; background: rgba(0, 0, 0, 0.5); padding: 1px 4px; border-radius: 3px; font-size: 8px; letter-spacing: 0.02em; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.option.color-only .lbl { display: none; }
.option.color-only { height: 36px; }
.option-grid.names { grid-template-columns: repeat(2, 1fr); }
.option-grid.names .option { height: 40px; justify-content: flex-start; padding: 0 9px; font-size: 11px; letter-spacing: 0.03em; }
.option-grid.names .option.active { color: var(--gold); }
.field { margin-bottom: 12px; }
.field label { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); margin-bottom: 6px; }
.field label b { color: var(--text); font-weight: 600; letter-spacing: 0.03em; }
.field input[type="text"], .field select, .input {
  width: 100%; background: rgba(255, 255, 255, 0.05); border: 1px solid var(--line); border-radius: 7px; padding: 9px 11px;
  font-family: var(--font-body); font-size: 13px; color: var(--text); outline: none;
}
.field input[type="text"]:focus, .field select:focus, .input:focus { border-color: rgba(242, 193, 78, 0.5); background: rgba(255, 255, 255, 0.07); }
.field select option { background: #14141a; }
input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; height: 4px; border-radius: 3px; background: rgba(255, 255, 255, 0.1); outline: none; }
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 50%; background: var(--gold); border: 2px solid #1a1305; box-shadow: 0 0 0 1px var(--gold); cursor: pointer; }
input[type="range"]::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: var(--gold); border: 2px solid #1a1305; cursor: pointer; }
.slider-row { display: grid; grid-template-columns: 80px 1fr 40px; gap: 9px; align-items: center; margin-bottom: 10px; font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
.slider-row b { text-align: right; color: var(--text); font-size: 12px; }
.attr-alloc { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; }
.attr-pill { display: flex; align-items: center; gap: 6px; padding: 5px 6px; border: 1px solid var(--line); border-radius: 6px; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.attr-pill b { color: var(--text); font-size: 13px; margin-left: auto; }
.attr-pill button { width: 19px; height: 19px; border-radius: 3px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.05); color: var(--text); cursor: pointer; display: grid; place-items: center; font-size: 12px; line-height: 1; }
.attr-pill button:hover { border-color: var(--gold); color: var(--gold); }
.editor-footer { padding: 14px 18px; border-top: 1px solid var(--line); display: flex; gap: 8px; }
.points-left { font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
.points-left b { color: var(--gold); font-size: 14px; }

/* -------------------------------- Gym -------------------------------- */
.gym-layout { display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; align-items: start; }
.gym-hero { min-height: 300px; display: flex; align-items: flex-end; padding: 26px; border-radius: var(--r); border: 1px solid var(--line); background: linear-gradient(180deg, transparent, rgba(6, 6, 8, 0.9)); pointer-events: none; }
.gym-hero h2 { font-family: var(--font-display); font-size: 42px; margin: 0; }
.gym-hero p { font-family: var(--font-cond); color: var(--muted); max-width: 430px; font-size: 13px; line-height: 1.5; }
.drill-card { padding: 18px; border: 1px solid var(--line); border-radius: 12px; background: rgba(12, 12, 16, 0.85); margin-bottom: 10px; cursor: pointer; transition: 0.18s; }
.drill-card:hover { border-color: rgba(242, 193, 78, 0.3); background: rgba(242, 193, 78, 0.04); }
.drill-card.active { border-color: var(--gold); }
.timing-game { height: 34px; border-radius: 8px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); position: relative; overflow: hidden; margin: 14px 0; }
.timing-zone { position: absolute; top: 0; bottom: 0; background: rgba(52, 211, 153, 0.28); border-left: 1px solid var(--green); border-right: 1px solid var(--green); }
.timing-marker { position: absolute; top: 0; bottom: 0; width: 3px; background: var(--gold); box-shadow: 0 0 12px rgba(242, 193, 78, 0.7); }
.timing-hit { position: absolute; top: 50%; font-family: var(--font-display); font-size: 20px; color: var(--green); transform: translateY(-50%); pointer-events: none; }

/* -------------------------------- Stats / awards -------------------------------- */
.records-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.record-list { display: flex; flex-direction: column; }
.record-row { display: flex; align-items: center; gap: 10px; padding: 9px 0; border-bottom: 1px solid var(--line); font-family: var(--font-cond); font-size: 13px; }
.record-row:last-child { border-bottom: none; }
.record-row .pos { width: 18px; color: var(--muted2); font-size: 11px; }
.record-row .val { margin-left: auto; font-family: var(--font-display); font-size: 18px; color: var(--gold); }
.award-card { text-align: center; padding: 20px 14px; border: 1px solid var(--line); border-radius: 12px; background: linear-gradient(180deg, rgba(242, 193, 78, 0.06), rgba(255, 255, 255, 0.015)); }
.award-card .ic { color: var(--gold); margin-bottom: 8px; }
.award-card b { display: block; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; }
.award-card span { display: block; font-family: var(--font-cond); font-size: 13px; color: var(--gold); margin-top: 5px; }
.award-card small { display: block; color: var(--muted); font-size: 10px; margin-top: 2px; }
.trophy-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }
.trophy { border: 1px solid var(--line); border-radius: 10px; padding: 16px; background: radial-gradient(circle at 50% 0%, rgba(242, 193, 78, 0.12), rgba(255, 255, 255, 0.02)); text-align: center; }
.trophy .gold-ic { color: var(--gold); margin-bottom: 6px; }
.trophy b { font-family: var(--font-cond); font-size: 13px; display: block; }
.trophy small { font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.belt-card { border: 1px solid rgba(242, 193, 78, 0.3); border-radius: 12px; padding: 16px; background: linear-gradient(135deg, rgba(242, 193, 78, 0.13), rgba(20, 15, 10, 0.9)); display: flex; gap: 14px; align-items: center; }
.belt-art { width: 72px; height: 72px; border-radius: 50%; background: radial-gradient(circle at 40% 35%, #fff3c4, #d4a017 50%, #6b4708); display: grid; place-items: center; color: #241604; font-family: var(--font-display); font-size: 20px; flex: none; border: 4px solid #3a2405; box-shadow: 0 8px 24px rgba(242, 193, 78, 0.25); }
.belt-card b { font-family: var(--font-cond); font-size: 15px; display: block; }
.belt-card span { font-family: var(--font-cond); font-size: 10px; color: var(--gold); letter-spacing: 0.08em; }

/* -------------------------------- Settings -------------------------------- */
.settings-layout { display: grid; grid-template-columns: 230px minmax(0, 680px); gap: 24px; align-items: start; }
.settings-nav { display: flex; flex-direction: column; gap: 4px; }
.settings-nav button { text-align: left; border: none; border-left: 2px solid transparent; background: none; color: var(--muted); padding: 11px 14px; font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; cursor: pointer; }
.settings-nav button:hover { color: var(--text); background: rgba(255, 255, 255, 0.04); }
.settings-nav button.active { color: var(--gold); border-left-color: var(--gold); background: rgba(242, 193, 78, 0.06); }
.settings-section { border-bottom: 1px solid var(--line); padding: 4px 0 18px; margin-bottom: 18px; }
.settings-section h3 { font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; margin: 0 0 12px; color: var(--gold); }
.toggle { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 10px 0; font-family: var(--font-cond); font-size: 13px; }
.toggle input { appearance: none; width: 38px; height: 21px; border-radius: 999px; background: rgba(255, 255, 255, 0.12); position: relative; cursor: pointer; transition: 0.2s; border: 1px solid var(--line); }
.toggle input::after { content: ''; position: absolute; width: 15px; height: 15px; border-radius: 50%; background: #888; top: 2px; left: 2px; transition: 0.2s; }
.toggle input:checked { background: rgba(242, 193, 78, 0.25); border-color: rgba(242, 193, 78, 0.5); }
.toggle input:checked::after { background: var(--gold); transform: translateX(17px); }
.control-customizer { position: relative; height: 230px; border-radius: 12px; border: 1px solid var(--line); background: radial-gradient(circle at 50% 40%, rgba(60, 60, 80, 0.15), rgba(0, 0, 0, 0.3)); overflow: hidden; }
.cc-stick { position: absolute; border: 2px dashed rgba(255, 255, 255, 0.25); border-radius: 50%; display: grid; place-items: center; color: rgba(255, 255, 255, 0.35); font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.1em; }
.cc-btn { position: absolute; border: 2px dashed rgba(242, 193, 78, 0.4); border-radius: 50%; display: grid; place-items: center; color: rgba(242, 193, 78, 0.6); font-family: var(--font-display); font-size: 14px; }

/* -------------------------------- Fight HUD -------------------------------- */
.fight-ui { position: absolute; inset: 0; pointer-events: none; z-index: 20; }
.fight-ui > * { pointer-events: auto; }
.hud-top { position: absolute; top: 0; left: 0; right: 0; padding: 18px clamp(14px, 3vw, 38px); display: grid; grid-template-columns: 1fr auto 1fr; gap: 20px; align-items: start; background: linear-gradient(180deg, rgba(0, 0, 0, 0.72), transparent); }
.hud-fighter { display: flex; gap: 10px; align-items: flex-start; min-width: 0; }
.hud-fighter.right { flex-direction: row-reverse; text-align: right; }
.hud-avatar { width: 46px; height: 46px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.18); background: radial-gradient(circle at 40% 30%, #60202c, #111118); display: grid; place-items: center; font-family: var(--font-display); font-size: 18px; color: var(--gold); flex: none; overflow: hidden; }
.hud-fighter.right .hud-avatar { border-color: rgba(225, 29, 72, 0.45); }
.hud-info { flex: 1; min-width: 0; max-width: 330px; }
.hud-name { font-family: var(--font-cond); font-weight: 600; font-size: 14px; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-record { font-family: var(--font-cond); font-size: 9px; color: var(--muted); letter-spacing: 0.1em; margin-bottom: 6px; }
.hp-track { height: 9px; background: rgba(255, 255, 255, 0.09); border-radius: 2px; overflow: hidden; position: relative; transform: skewX(-12deg); border: 1px solid rgba(255, 255, 255, 0.08); }
.hp-fill { height: 100%; background: linear-gradient(90deg, #ff2d55, #ff6b3d); transition: width 0.2s linear; box-shadow: 0 0 12px rgba(255, 45, 85, 0.35); }
.hp-fill.p2 { background: linear-gradient(90deg, #f2c14e, #e08a2e); box-shadow: 0 0 12px rgba(242, 193, 78, 0.3); }
.hud-fighter.right .hp-fill { margin-left: auto; }
.hp-ghost { position: absolute; inset: 0; background: rgba(255, 255, 255, 0.25); transition: width 0.8s ease 0.2s; }
.stamina-track { height: 4px; margin-top: 4px; background: rgba(255, 255, 255, 0.08); border-radius: 2px; overflow: hidden; transform: skewX(-12deg); }
.stamina-fill { height: 100%; background: linear-gradient(90deg, #38bdf8, #22d3ee); transition: width 0.15s linear; }
.stamina-fill.p2 { background: linear-gradient(90deg, #34d399, #a3e635); margin-left: auto; }
.round-center { text-align: center; min-width: 120px; }
.round-label { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.28em; color: var(--muted); text-transform: uppercase; }
.round-timer { font-family: var(--font-display); font-size: 46px; line-height: 0.85; color: var(--text); text-shadow: 0 4px 24px rgba(0, 0, 0, 0.6); }
.round-timer.low { color: #ff5a72; animation: pulse 1s infinite; }
.round-dots { display: flex; gap: 4px; justify-content: center; margin-top: 5px; }
.round-dots i { width: 16px; height: 3px; background: rgba(255, 255, 255, 0.15); }
.round-dots i.done { background: var(--gold); }
@keyframes pulse { 50% { opacity: 0.55; } }
.hud-bottom { position: absolute; bottom: 18px; left: 0; right: 0; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 clamp(14px, 3vw, 38px); gap: 14px; }
.hud-stats { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.1em; color: rgba(255, 255, 255, 0.5); display: flex; gap: 14px; text-transform: uppercase; }
.hud-stats b { color: var(--text); font-weight: 600; }
.hud-actions { display: flex; gap: 8px; }
.hud-btn { width: 40px; height: 40px; border-radius: 50%; background: rgba(8, 8, 12, 0.7); border: 1px solid rgba(255, 255, 255, 0.15); color: var(--text); display: grid; place-items: center; cursor: pointer; backdrop-filter: blur(6px); }
.hud-btn:hover { border-color: var(--gold); color: var(--gold); }
.combo-meter { position: absolute; left: clamp(14px, 3vw, 38px); top: 130px; font-family: var(--font-display); font-size: 32px; color: var(--gold); opacity: 0; transform: translateX(-10px); transition: 0.2s; text-shadow: 0 4px 18px rgba(0, 0, 0, 0.8); }
.combo-meter.show { opacity: 1; transform: none; }
.combo-meter small { display: block; font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.2em; color: var(--text); }
.announcer { position: absolute; left: 50%; top: 30%; transform: translate(-50%, -50%); text-align: center; opacity: 0; transition: 0.3s; pointer-events: none; }
.announcer.show { opacity: 1; }
.announcer .big { font-family: var(--font-display); font-size: clamp(56px, 9vw, 118px); line-height: 0.8; color: var(--text); text-shadow: 0 12px 60px rgba(0, 0, 0, 0.9), 0 0 40px rgba(242, 193, 78, 0.18); }
.announcer .small { font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.3em; color: var(--gold); text-transform: uppercase; margin-top: 8px; }
.count-overlay { position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none; }
.count-num { font-family: var(--font-display); font-size: clamp(120px, 22vw, 250px); color: var(--gold); line-height: 0.8; text-shadow: 0 0 60px rgba(242, 193, 78, 0.35); animation: countPop 0.5s ease-out; }
@keyframes countPop { from { transform: scale(1.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }

/* Touch controls */
.touch-controls { position: absolute; inset: 0; pointer-events: none; display: none; }
.touch-controls.enabled { display: block; }
.joystick { position: absolute; left: 22px; bottom: 26px; width: 130px; height: 130px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.18); background: radial-gradient(circle, rgba(255, 255, 255, 0.05), rgba(0, 0, 0, 0.2)); pointer-events: auto; touch-action: none; backdrop-filter: blur(3px); }
.joystick::before { content: ''; position: absolute; inset: 25%; border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 50%; }
.joystick-knob { position: absolute; width: 54px; height: 54px; border-radius: 50%; left: 50%; top: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.32), rgba(242, 193, 78, 0.25)); border: 1px solid rgba(242, 193, 78, 0.5); box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4); }
.joy-label { position: absolute; left: 0; right: 0; bottom: 8px; text-align: center; font-family: var(--font-cond); font-size: 8px; letter-spacing: 0.18em; color: rgba(255, 255, 255, 0.3); }
.action-pad { position: absolute; right: 18px; bottom: 24px; width: 190px; height: 190px; pointer-events: none; }
.act-btn { position: absolute; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.2); background: rgba(8, 8, 12, 0.62); color: var(--text); display: grid; place-items: center; font-family: var(--font-display); font-size: 15px; pointer-events: auto; touch-action: none; backdrop-filter: blur(4px); transition: transform 0.08s, background 0.08s; user-select: none; }
.act-btn:active, .act-btn.pressed { transform: scale(0.92); background: rgba(242, 193, 78, 0.35); border-color: var(--gold); }
.act-btn.jab { width: 54px; height: 54px; right: 68px; top: 96px; }
.act-btn.cross { width: 54px; height: 54px; right: 6px; top: 62px; }
.act-btn.hook { width: 54px; height: 54px; right: 16px; top: 0px; }
.act-btn.upper { width: 54px; height: 54px; right: 84px; top: 10px; }
.act-btn.block { width: 58px; height: 58px; right: 132px; top: 122px; font-size: 11px; letter-spacing: 0.05em; background: rgba(15, 23, 42, 0.7); }
.act-btn.dodge { width: 48px; height: 48px; right: 116px; top: 56px; font-size: 10px; background: rgba(15, 23, 42, 0.7); }
.act-btn.getup { width: 120px; height: 54px; left: 50%; transform: translateX(-50%); bottom: 30px; border-radius: 10px; background: rgba(242, 193, 78, 0.25); font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.1em; }
.act-btn.getup:active { transform: translateX(-50%) scale(0.96); }
.act-btn.punch { border-color: rgba(242, 193, 78, 0.4); color: #ffe6a3; }
.desktop-hint { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.4); text-transform: uppercase; display: flex; gap: 12px; flex-wrap: wrap; }
.key { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border: 1px solid rgba(255, 255, 255, 0.22); border-radius: 4px; font-size: 9px; color: var(--text); background: rgba(255, 255, 255, 0.06); }
.touch-controls.enabled ~ .hud-bottom .desktop-hint { display: none; }

/* Intro / result / pause overlays */
.fight-overlay { position: absolute; inset: 0; background: radial-gradient(circle at 50% 40%, rgba(12, 8, 12, 0.4), rgba(4, 4, 6, 0.94)); backdrop-filter: blur(4px); z-index: 30; display: flex; align-items: center; justify-content: center; padding: 24px; overflow-y: auto; }
.vs-card { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: clamp(10px, 4vw, 50px); width: min(1000px, 94vw); }
.vs-fighter { text-align: center; }
.vs-fighter .portrait { width: clamp(110px, 18vw, 190px); aspect-ratio: 1; margin: 0 auto 14px; border-radius: 50%; background: radial-gradient(circle at 40% 25%, #6b202c, #131319 72%); border: 2px solid rgba(242, 193, 78, 0.35); display: grid; place-items: center; font-family: var(--font-display); font-size: 60px; color: var(--gold); box-shadow: 0 20px 80px rgba(0, 0, 0, 0.5); position: relative; overflow: hidden; }
.vs-fighter .portrait::after { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 50% 120%, rgba(242, 193, 78, 0.2), transparent 55%); }
.vs-fighter h2 { font-family: var(--font-display); font-size: clamp(28px, 4vw, 50px); line-height: 0.9; margin: 0; }
.vs-fighter .nickname { font-family: var(--font-cond); font-size: 12px; color: var(--gold); letter-spacing: 0.18em; text-transform: uppercase; margin: 5px 0 10px; }
.vs-fighter .rec { font-family: var(--font-cond); font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
.vs-mid { text-align: center; }
.vs-mid .vs { font-family: var(--font-display); font-size: clamp(54px, 9vw, 110px); color: transparent; -webkit-text-stroke: 1px rgba(242, 193, 78, 0.6); line-height: 0.8; }
.vs-mid .at { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.25em; color: var(--muted); margin-bottom: 6px; }
.intro-details { text-align: center; margin-top: 30px; }
.intro-details .event { font-family: var(--font-display); font-size: 25px; color: var(--text); letter-spacing: 0.06em; }
.intro-details .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 4px; }
.intro-details .title-line { font-family: var(--font-cond); color: var(--gold); font-size: 12px; letter-spacing: 0.18em; margin-top: 8px; display: flex; gap: 8px; justify-content: center; align-items: center; }
.intro-buttons { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
.result-card { width: min(900px, 94vw); }
.result-head { text-align: center; margin-bottom: 20px; }
.result-head .method { font-family: var(--font-display); font-size: clamp(56px, 10vw, 110px); line-height: 0.8; color: var(--gold); }
.result-head .winner { font-family: var(--font-display); font-size: clamp(26px, 4vw, 46px); margin-top: 6px; }
.result-head .winner span { color: var(--gold); }
.result-head .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.15em; color: var(--muted); margin-top: 3px; }
.result-stats { display: grid; grid-template-columns: 1fr auto 1fr; gap: 20px; align-items: center; }
.result-side { display: flex; flex-direction: column; gap: 6px; }
.result-side.right { text-align: right; }
.result-stat { display: flex; justify-content: space-between; gap: 12px; font-family: var(--font-cond); font-size: 11px; color: var(--muted); padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.result-side.right .result-stat { flex-direction: row-reverse; }
.result-stat b { color: var(--text); font-weight: 600; }
.result-purse { text-align: center; margin: 18px 0; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.1em; color: var(--muted); }
.result-purse b { color: var(--gold); font-size: 20px; font-family: var(--font-display); }
.scorecards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
.scorecard { border: 1px solid var(--line); border-radius: 7px; padding: 7px; text-align: center; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.scorecard b { display: block; font-family: var(--font-display); font-size: 18px; color: var(--text); }
.result-actions { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
.result-news { margin-top: 18px; padding: 12px 16px; border-left: 2px solid var(--gold); background: rgba(242, 193, 78, 0.05); font-family: var(--font-cond); font-size: 13px; line-height: 1.5; }
.result-news span { color: var(--gold); font-size: 9px; letter-spacing: 0.18em; display: block; margin-bottom: 3px; }
.replay-overlay { position: absolute; top: 26px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.25em; color: var(--gold); text-transform: uppercase; background: rgba(6, 6, 8, 0.6); border: 1px solid rgba(242, 193, 78, 0.25); padding: 7px 13px; border-radius: 4px; pointer-events: none; animation: blink 1.2s infinite; }
@keyframes blink { 50% { opacity: 0.55; } }
.pause-menu { width: min(440px, 92vw); }
.pause-menu .panel-body { display: flex; flex-direction: column; gap: 8px; }
.pause-menu h2 { font-family: var(--font-display); font-size: 44px; margin: 0 0 4px; text-align: center; }

/* -------------------------------- Multiplayer -------------------------------- */
.mp-layout { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.75fr); gap: 18px; align-items: start; }
.lobby-card { padding: 26px; }
.room-code { font-family: var(--font-display); font-size: clamp(42px, 7vw, 72px); letter-spacing: 0.16em; color: var(--gold); text-align: center; line-height: 1; padding: 16px 0 8px; }
.invite-box { display: flex; gap: 8px; margin-top: 12px; }
.invite-box input { flex: 1; background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); color: var(--muted); border-radius: 7px; padding: 9px 11px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.03em; min-width: 0; }
.player-slots { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px; margin: 20px 0; }
.player-slot { border: 1px solid var(--line); border-radius: 12px; padding: 16px; text-align: center; background: rgba(255, 255, 255, 0.025); min-height: 150px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; }
.player-slot.ready { border-color: rgba(52, 211, 153, 0.45); box-shadow: inset 0 0 30px rgba(52, 211, 153, 0.06); }
.player-slot .avatar { width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 40% 30%, #5c1d28, #111118); border: 1px solid rgba(242, 193, 78, 0.3); display: grid; place-items: center; font-family: var(--font-display); font-size: 24px; color: var(--gold); }
.player-slot b { font-family: var(--font-cond); font-size: 15px; }
.player-slot span { font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.vs-small { font-family: var(--font-display); font-size: 26px; color: var(--muted2); }
.connection-pill { display: inline-flex; align-items: center; gap: 7px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.08em; padding: 6px 10px; border-radius: 999px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); }
.connection-pill .dot { width: 7px; height: 7px; border-radius: 50%; background: #eab308; }
.connection-pill.online .dot { background: var(--green); box-shadow: 0 0 8px rgba(52, 211, 153, 0.8); }
.connection-pill.offline .dot { background: var(--red); }
.mp-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.quick-list { display: flex; flex-direction: column; gap: 8px; }
.quick-row { display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; cursor: pointer; }
.quick-row:hover { border-color: rgba(242, 193, 78, 0.3); background: rgba(242, 193, 78, 0.04); }
.quick-row .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); }
.quick-row b { font-family: var(--font-cond); font-size: 13px; }
.quick-row span { margin-left: auto; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.wager-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.wager-row button { border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03); border-radius: 6px; color: var(--muted); padding: 7px 11px; font-family: var(--font-cond); font-size: 11px; cursor: pointer; }
.wager-row button.active { border-color: var(--gold); color: var(--gold); background: rgba(242, 193, 78, 0.08); }
.chat-feed { max-height: 150px; overflow-y: auto; display: flex; flex-direction: column; gap: 5px; font-family: var(--font-cond); font-size: 12px; }
.chat-feed .msg { color: var(--muted); }
.chat-feed .msg b { color: var(--text); }
.match-history { display: flex; flex-direction: column; }
.match-history .row-item { display: flex; gap: 10px; align-items: center; padding: 9px 0; border-bottom: 1px solid var(--line); font-family: var(--font-cond); font-size: 12px; }
.match-history .win { color: var(--green); }
.match-history .loss { color: #ff7c91; }
.mp-status { text-align: center; padding: 22px; }
.mp-status .big { font-family: var(--font-display); font-size: 32px; }
.spinner { width: 34px; height: 34px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.12); border-top-color: var(--gold); animation: spin 1s linear infinite; margin: 0 auto 12px; }

/* -------------------------------- Modal / toast -------------------------------- */
.modal-backdrop { position: fixed; inset: 0; z-index: 80; background: rgba(3, 3, 5, 0.78); backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; padding: 20px; animation: fadeIn 0.2s; }
.modal { width: min(560px, 94vw); max-height: 88vh; overflow-y: auto; background: #111117; border: 1px solid var(--line2); border-radius: 16px; box-shadow: var(--shadow); padding: 26px; }
.modal.wide { width: min(850px, 95vw); }
.modal h2 { font-family: var(--font-display); font-size: 34px; margin: 0 0 6px; }
.modal p { color: var(--muted); font-size: 13px; line-height: 1.6; }
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 22px; flex-wrap: wrap; }
@keyframes fadeIn { from { opacity: 0; } }
.toast-stack { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); z-index: 120; display: flex; flex-direction: column; gap: 8px; pointer-events: none; width: min(420px, 92vw); }
.toast { background: rgba(16, 16, 22, 0.96); border: 1px solid var(--line2); border-left: 2px solid var(--gold); border-radius: 8px; padding: 11px 14px; font-family: var(--font-cond); font-size: 13px; display: flex; align-items: center; gap: 9px; box-shadow: var(--shadow); animation: toastIn 0.28s cubic-bezier(0.22, 1, 0.36, 1); pointer-events: auto; }
.toast.error { border-left-color: var(--red); }
.toast.success { border-left-color: var(--green); }
.toast.achievement { border-left-color: var(--gold); background: linear-gradient(90deg, rgba(242, 193, 78, 0.15), #111117); }
.toast .ic { color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px); } }
.toast.out { animation: toastOut 0.3s forwards; }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

/* -------------------------------- Misc -------------------------------- */
.empty-state { text-align: center; padding: 50px 20px; color: var(--muted); }
.empty-state .ic { color: var(--muted2); margin-bottom: 10px; }
.empty-state b { display: block; font-family: var(--font-display); font-size: 26px; color: var(--text); margin-bottom: 4px; }
.loading-block { display: grid; place-items: center; padding: 60px; }
.kbd-hint { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); letter-spacing: 0.1em; }
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin-bottom: 18px; overflow-x: auto; }
.tabs button { background: none; border: none; border-bottom: 2px solid transparent; color: var(--muted); padding: 10px 14px; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; cursor: pointer; white-space: nowrap; }
.tabs button:hover { color: var(--text); }
.tabs button.active { color: var(--gold); border-bottom-color: var(--gold); }
.division-badge { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.division-badge i { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); }
.list-plain { margin: 0; padding: 0; list-style: none; }
.notice { border-left: 2px solid var(--gold); background: rgba(242, 193, 78, 0.06); padding: 11px 14px; font-family: var(--font-cond); font-size: 12px; line-height: 1.5; color: #cfc9b8; }
.notice.red { border-color: var(--red); background: rgba(225, 29, 72, 0.07); }
.notice.green { border-color: var(--green); background: rgba(52, 211, 153, 0.06); }

/* -------------------------------- Responsive -------------------------------- */
@media (max-width: 1100px) {
  .editor { grid-template-columns: 180px minmax(200px, 1fr) 320px; }
  .career-top { grid-template-columns: 1fr; }
  .career-side { grid-template-columns: 1fr 1fr 1fr; }
  .next-fight-card { grid-column: auto; }
  .dashboard-grid { grid-template-columns: 1fr; }
  .rank-layout { grid-template-columns: 1fr; }
  .news-layout { grid-template-columns: 1fr; }
  .mp-layout { grid-template-columns: 1fr; }
  .gym-layout { grid-template-columns: 1fr; }
  .settings-layout { grid-template-columns: 1fr; }
  .settings-nav { flex-direction: row; overflow-x: auto; }
  .records-grid { grid-template-columns: 1fr; }
  .menu-left { width: min(380px, 92vw); }
  .main-logo { font-size: clamp(60px, 10vw, 96px); }
}
@media (max-width: 820px) {
  body { overflow: hidden; }
  .screen { padding: 16px 14px 80px; }
  .topbar { flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
  .topnav { order: 3; width: 100%; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 4px; }
  .topnav button { white-space: nowrap; font-size: 11px; }
  .userbar { margin-left: auto; }
  .profile-pill small { display: none; }
  .menu-left { width: 100%; margin-top: 4vh; }
  .main-menu { justify-content: flex-start; padding-top: 8vh; padding-bottom: 100px; overflow-y: auto; display: block; }
  .main-logo { font-size: clamp(66px, 19vw, 100px); }
  .menu-btn { padding: 10px 13px; }
  .menu-btn b { font-size: 19px; }
  .menu-btn small { display: none; }
  .menu-ticker { padding: 9px 14px; }
  .hero-badge { display: none; }
  .career-side { grid-template-columns: 1fr 1fr; }
  .next-fight-card { grid-column: 1 / -1; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: 1fr; }
  .editor { grid-template-columns: 1fr; grid-template-rows: minmax(280px, 45vh) 1fr; }
  .editor-left { position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; flex-direction: row; overflow-x: auto; padding: 8px; gap: 4px; justify-content: flex-start; background: linear-gradient(0deg, rgba(6, 6, 8, 0.95), transparent); }
  .editor-left .cat-btn { flex-direction: column; gap: 3px; font-size: 9px; padding: 8px 10px; white-space: nowrap; border-left: none; border-bottom: 2px solid transparent; }
  .editor-left .cat-btn.active { border-bottom-color: var(--gold); }
  .editor-left .done { margin-top: 0; margin-left: auto; }
  .editor-center { grid-row: 1; justify-content: center; padding-bottom: 70px; }
  .editor-right { grid-row: 2; border-left: none; border-top: 1px solid var(--line); max-height: none; height: auto; }
  .editor-scroll { max-height: 44vh; }
  .editor-head { padding: 12px 14px; }
  .editor-head h2 { font-size: 23px; }
  .editor-footer { position: sticky; bottom: 0; background: #0c0c11; }
  .hud-top { padding: 10px 12px; gap: 8px; }
  .hud-avatar { width: 36px; height: 36px; font-size: 14px; border-width: 1px; }
  .hud-name { font-size: 11px; }
  .hud-record { font-size: 8px; margin-bottom: 3px; }
  .round-timer { font-size: 34px; }
  .round-center { min-width: 74px; }
  .hud-info { max-width: 42vw; }
  .hud-bottom { bottom: 8px; }
  .hud-stats { display: none; }
  .desktop-hint { display: none; }
  .combo-meter { top: 100px; font-size: 24px; }
  .vs-card { grid-template-columns: 1fr; gap: 12px; }
  .vs-mid { order: -1; display: flex; align-items: center; justify-content: center; gap: 12px; }
  .vs-mid .vs { font-size: 46px; }
  .vs-mid .at { margin: 0; }
  .vs-fighter .portrait { width: 92px; height: 92px; font-size: 34px; margin-bottom: 8px; }
  .vs-fighter h2 { font-size: 34px; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .result-stats .vs-small { display: none; }
  .scorecards { grid-template-columns: 1fr; }
  .fight-overlay { padding: 14px; align-items: flex-start; padding-top: 30px; }
  .modal { padding: 20px; }
  .division-tabs button { font-size: 10px; padding: 6px 9px; }
  .rank-row { grid-template-columns: 34px 1fr auto; gap: 10px; }
  .rank-row .pts { display: none; }
  .rank-row .rec { font-size: 11px; }
  .screen-title { font-size: 38px; }
  .career-hero { flex-direction: column; text-align: center; }
  .career-hero .fighter-card { flex-direction: column; }
  .career-hero .profile-stats { justify-content: center; }
  .gym-hero h2 { font-size: 31px; }
  .news-feature { min-height: 300px; }
  .news-feature .content { padding: 18px; }
  .toast-stack { top: 10px; }
}
@media (max-width: 520px) {
  .main-logo { font-size: 20vw; }
  .logo-sub { font-size: 9px; letter-spacing: 0.24em; }
  .menu-btn b { font-size: 17px; }
  .menu-btn .idx { display: none; }
  .menu-corner .chip { display: none; }
  .career-side { grid-template-columns: 1fr; }
  .next-fight-card { grid-column: auto; }
  .grid-4 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
