287: export function simulateFight(a, b, rnd = Math.random) {
288:   const ratingA = a.overall + (a.isPlayer ? 0 : 0);
289:   const ratingB = b.overall;
290:   const chanceA = 1 / (1 + Math.pow(10, (ratingB - ratingA) / 32));
291:   const winnerA = rnd() < chanceA;
292:   const winner = winnerA ? a : b;
293:   const loser = winnerA ? b : a;
294:   const koChance = clamp(0.18 + Math.abs(ratingA - ratingB) / 140 + (winner.koRate || 0.3) * 0.35, 0.12, 0.72);
295:   const method = rnd() < koChance ? 'KO' : rnd() < 0.08 ? 'TKO' : rnd() < 0.07 ? 'DRAW' : 'DEC';
296:   if (method === 'DRAW') return { winner: null, loser: null, method: 'DRAW', round: null };
297:   const round = method === 'DEC' ? null : 1 + Math.floor(rnd() * 8);
298:   return { winner, loser, method, round, winnerA };
299: }
