336:   winner.streak = Math.max(1, winner.streak + 1);
337:   loser.streak = Math.min(-1, loser.streak - 1);
338:   if (winner.streak > winner.bestStreak) winner.bestStreak = winner.streak;
339:   winner.form = [method === 'DEC' ? 'V' : 'V', ...winner.form].slice(0, 5);
340:   loser.form = ['D', ...loser.form].slice(0, 5);
341:   const weight = clamp(1 + (100 - (loser.rankSeed || 50)) / 90, 0.4, 2.2);
