343:   winner.points += gain;
344:   loser.points = Math.max(10, loser.points - Math.round(gain * 0.6));
345:   winner.reputation = clamp(winner.reputation + 2, 0, 100);
346:   loser.reputation = clamp(loser.reputation - 1, 0, 100);
