515: export function computeAwards(save, universe) {
516:   const list = universe ? universe.fighters.filter((f) => !f.retired) : [];
517:   const player = createPlayerFighter(save);
518:   const playerScore = player ? player.record.w * 4 + player.record.ko * 3 + save.career.reputation * 2 + save.career.belts.length * 40 : 0;
519:   const best = list.slice().sort((a, b) => (b.record.w * 4 + b.record.ko * 3 + (b.belts?.length || 0) * 40) - (a.record.w * 4 + a.record.ko * 3 + (a.belts?.length || 0) * 40))[0];
520:   const bestFighter = playerScore > (best ? best.record.w * 4 + best.record.ko * 3 + (best.belts?.length || 0) * 40 : 0) ? player : best;
521:   const awards = AWARD_TYPES.map((type) => {
522:     let winner = bestFighter;
523:     if (type.id === 'ko') winner = (player && player.record.ko >= (best?.record.ko || 0)) ? player : best;
524:     if (type.id === 'prospect') winner = (player && save.career.record.w <= 12) ? player : list.filter((f) => f.age <= 24).sort((a, b) => b.record.w - a.record.w)[0];
525:     if (type.id === 'rivalry') winner = player && save.career.rivalries.length ? player : list[0];
526:     if (type.id === 'coach') winner = { name: save.profile.name + '\'s corner', nick: 'Treinador do ano', isCoach: true };
527:     return {
528:       ...type,
529:       year: save.career.season.year,
530:       winner: winner ? { name: winner.name, nick: winner.nick, id: winner.id, isPlayer: winner.isPlayer } : { name: 'TG Boxing', nick: '' },
531:     };
532:   });
533:   return awards;
534: }
