495:     const tStart = frames[0].t;
496:     const targetT = tStart + r.elapsed * r.speed;
497:     let i = r.index;
498:     while (i < frames.length - 1 && frames[i + 1].t <= targetT) i++;
499:     r.index = i;
500:     const f = frames[i];
501:     const next = frames[Math.min(frames.length - 1, i + 1)];
502:     const p = next.t > f.t ? clamp((targetT - f.t) / (next.t - f.t), 0, 1) : 0;
503:     for (const [bi, b] of this.boxers.entries()) {
504:       const a = f.boxers[bi], c = next.boxers[bi];
505:       if (!a) continue;
506:       b.root.position.set(lerp(a.pos[0], c.pos[0], p), lerp(a.pos[1], c.pos[1], p), lerp(a.pos[2], c.pos[2], p));
507:       b.root.rotation.y = lerp(a.ry, c.ry, p);
508:       const pose = {};
509:       for (const k of Object.keys(a.state.pose)) pose[k] = lerp(a.state.pose[k], c.state?.pose?.[k] ?? a.state.pose[k], p);
510:       b.applyRenderState({ ...a.state, pose });
511:     }
512:     this.camera.position.set(
513:       lerp(f.cam.pos[0], next.cam.pos[0], p),
514:       lerp(f.cam.pos[1], next.cam.pos[1], p),
515:       lerp(f.cam.pos[2], next.cam.pos[2], p),
516:     );
517:     const look = new THREE.Vector3(
518:       lerp(f.cam.look[0], next.cam.look[0], p),
519:       lerp(f.cam.look[1], next.cam.look[1], p),
520:       lerp(f.cam.look[2], next.cam.look[2], p),
521:     );
522:     this.camera.lookAt(look);
523:     this.cameraTarget.copy(look);
524:     this.heat = f.heat;
525:     if (r.elapsed * r.speed >= (frames[frames.length - 1].t - tStart) || r.elapsed > 18) {
526:       const cb = r.onDone;
527:       this.replay = null;
528:       this.syncFighters(1);
529:       cb?.();
530:     }
531:   }
532: 
533:   maybeCelebrate() {
534:     const result = this.engine.result;
535:     if (!result || this.engine.phase !== 'end') return;
536:     if (!['KO', 'TKO', 'DEC', 'QUIT'].includes(result.method)) return;
537:     // Confetti burst
538:     if (!this.confetti) this.spawnConfetti();
539:     // Belt appears if a career belt was attached
540:     if (this.pendingBelt && !this.beltGroup) {
541:       const belt = makeChampionshipBelt(this.pendingBelt);
542:       belt.position.set(0, 1.65, 0.1);
543:       belt.rotation.set(0.15, 0, 0);
544:       this.scene.add(belt);
545:       this.beltGroup = belt;
546:       this.beltSpin = 0;
547:     }
548:   }
549: 
550:   showBelt(belt) {
551:     this.pendingBelt = belt;
552:     this.maybeCelebrate();
553:   }
554: 
555:   spawnConfetti() {
556:     const count = 240;
557:     const pos = new Float32Array(count * 3);
558:     const colors = new Float32Array(count * 3);
559:     const palette = [[0.95, 0.76, 0.3], [0.76, 0.1, 0.16], [0.96, 0.96, 0.94], [0.2, 0.7, 0.9]];
560:     for (let i = 0; i < count; i++) {
561:       pos[i * 3] = (Math.random() - 0.5) * 8;
562:       pos[i * 3 + 1] = 3 + Math.random() * 4;
563:       pos[i * 3 + 2] = (Math.random() - 0.5) * 6;
564:       const c = palette[i % palette.length];
565:       colors[i * 3] = c[0]; colors[i * 3 + 1] = c[1]; colors[i * 3 + 2] = c[2];
566:     }
567:     const geo = new THREE.BufferGeometry();
568:     geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
569:     geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
570:     const mat = new THREE.PointsMaterial({ size: 0.06, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false });
571:     const points = new THREE.Points(geo, mat);
572:     this.scene.add(points);
573:     this.confetti = { points, pos, vel: Array.from({ length: count }, () => [Math.random() * 0.4, 1 + Math.random() * 1.2, Math.random() * 0.4]), count };
574:   }
575: 
576:   updateConfetti(dt) {
577:     if (!this.confetti) return;
578:     const { pos, vel, count } = this.confetti;
579:     for (let i = 0; i < count; i++) {
580:       pos[i * 3] += Math.sin(this.time + i) * dt * 0.35 + vel[i][0] * dt;
581:       pos[i * 3 + 1] -= vel[i][1] * dt;
582:       pos[i * 3 + 2] += Math.cos(this.time * 0.7 + i) * dt * 0.2;
583:       if (pos[i * 3 + 1] < 0.02) pos[i * 3 + 1] = 3 + Math.random() * 3;
584:     }
585:     this.confetti.points.geometry.attributes.position.needsUpdate = true;
586:     if (this.beltGroup) {
587:       this.beltSpin += dt * 0.7;
588:       this.beltGroup.rotation.y = Math.sin(this.time * 0.5) * 0.5;
589:       this.beltGroup.rotation.z = Math.sin(this.time * 0.8) * 0.04;
590:       this.beltGroup.position.y = 1.65 + Math.sin(this.time * 1.6) * 0.04;
591:       this.beltGroup.visible = true;
592:     }
593:   }
594: 
595:   resize(width, height) {
596:     this.camera.aspect = width / height;
597:     this.camera.fov = width / height < 1 ? 56 : 46;
598:     this.camera.updateProjectionMatrix();
599:   }
600: 
601:   render() {
602:     this.renderer.render(this.scene, this.camera);
603:   }
604: 
605:   dispose() {
606:     this.frames = [];
607:     this.replay = null;
608:     for (const b of this.boxers) b.dispose();
609:     this.arena.dispose();
610:     this.scene.clear();
611:   }
612: }

