341:/* -------------------------------- Editor -------------------------------- */
342:.editor { position: absolute; inset: 0; display: grid; grid-template-columns: 210px minmax(260px, 1fr) 350px; gap: 0; pointer-events: none; }
343:.editor > * { pointer-events: auto; }
