345:.editor-left .cat-btn { display: flex; align-items: center; gap: 11px; background: rgba(8, 8, 11, 0.55); border: 1px solid transparent; border-left: 2px solid transparent; color: var(--muted); padding: 10px 13px; cursor: pointer; text-align: left; border-radius: 2px 7px 7px 2px; backdrop-filter: blur(8px); font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.09em; text-transform: uppercase; }
