353:.editor-stats { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; }
354:.editor-stat { background: rgba(6, 6, 8, 0.55); border: 1px solid var(--line); border-radius: 7px; padding: 6px 11px; text-align: center; backdrop-filter: blur(8px); min-width: 62px; }
355:.editor-stat b { display: block; font-family: var(--font-display); font-size: 18px; line-height: 1; }
356:.editor-stat span { font-family: var(--font-cond); font-size: 8px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
357:.editor-right { display: flex; flex-direction: column; background: rgba(8, 8, 11, 0.78); border-left: 1px solid var(--line); backdrop-filter: blur(16px); max-height: 100vh; }
358:.editor-head { padding: 18px 18px 14px; border-bottom: 1px solid var(--line); }
