361:.editor-scroll { overflow-y: auto; flex: 1; padding: 14px 18px 18px; }
362:.editor-group { margin-bottom: 18px; }
363:.editor-group h3 { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: var(--gold); margin: 0 0 9px; display: flex; justify-content: space-between; }
