366:.option { height: 46px; border: 1px solid var(--line); border-radius: 6px; background: rgba(255, 255, 255, 0.025); cursor: pointer; position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; color: var(--muted); font-family: var(--font-cond); font-size: 10px; padding: 3px; text-align: center; transition: 0.15s; }
367:.option:hover { border-color: var(--line2); transform: translateY(-1px); }
