379:.field input[type="text"], .field select, .input {
383:.field input[type="text"]:focus, .field select:focus, .input:focus { border-color: rgba(242, 193, 78, 0.5); background: rgba(255, 255, 255, 0.07); }
384:.field select option { background: #14141a; }
388:.slider-row { display: grid; grid-template-columns: 80px 1fr 40px; gap: 9px; align-items: center; margin-bottom: 10px; font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
389:.slider-row b { text-align: right; color: var(--text); font-size: 12px; }
