394:.attr-pill button:hover { border-color: var(--gold); color: var(--gold); }

394:.attr-pill button:hover { border-color: var(--gold); color: var(--gold); }
395:.editor-footer { padding: 14px 18px; border-top: 1px solid var(--line); display: flex; gap: 8px; }
396:.points-left { font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
397:.points-left b { color: var(--gold); font-size: 14px; }
399:/* -------------------------------- Gym -------------------------------- */
400:.gym-layout { display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; align-items: start; }
401:.gym-hero { min-height: 300px; display: flex; align-items: flex-end; padding: 26px; border-radius: var(--r); border: 1px solid var(--line); background: linear-gradient(180deg, transparent, rgba(6, 6, 8, 0.9)); pointer-events: none; }
