441:.settings-section h3 { font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; margin: 0 0 12px; color: var(--gold); }
442:.toggle { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 10px 0; font-family: var(--font-cond); font-size: 13px; }
443:.toggle input { appearance: none; width: 38px; height: 21px; border-radius: 999px; background: rgba(255, 255, 255, 0.12); position: relative; cursor: pointer; transition: 0.2s; border: 1px solid var(--line); }
