447:.control-customizer { position: relative; height: 230px; border-radius: 12px; border: 1px solid var(--line); background: radial-gradient(circle at 50% 40%, rgba(60, 60, 80, 0.15), rgba(0, 0, 0, 0.3)); overflow: hidden; }
448:.cc-stick { position: absolute; border: 2px dashed rgba(255, 255, 255, 0.25); border-radius: 50%; display: grid; place-items: center; color: rgba(255, 255, 255, 0.35); font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.1em; }
449:.cc-btn { position: absolute; border: 2px dashed rgba(242, 193, 78, 0.4); border-radius: 50%; display: grid; place-items: center; color: rgba(242, 193, 78, 0.6); font-family: var(--font-display); font-size: 14px; }
451:/* -------------------------------- Fight HUD -------------------------------- */
452:.fight-ui { position: absolute; inset: 0; pointer-events: none; z-index: 20; }
453:.fight-ui > * { pointer-events: auto; }
454:.hud-top { position: absolute; top: 0; left: 0; right: 0; padding: 18px clamp(14px, 3vw, 38px); display: grid; grid-template-columns: 1fr auto 1fr; gap: 20px; align-items: start; background: linear-gradient(180deg, rgba(0, 0, 0, 0.72), transparent); }
455:.hud-fighter { display: flex; gap: 10px; align-items: flex-start; min-width: 0; }
456:.hud-fighter.right { flex-direction: row-reverse; text-align: right; }
457:.hud-avatar { width: 46px; height: 46px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.18); background: radial-gradient(circle at 40% 30%, #60202c, #111118); display: grid; place-items: center; font-family: var(--font-display); font-size: 18px; color: var(--gold); flex: none; overflow: hidden; }
458:.hud-fighter.right .hud-avatar { border-color: rgba(225, 29, 72, 0.45); }
459:.hud-info { flex: 1; min-width: 0; max-width: 330px; }
460:.hud-name { font-family: var(--font-cond); font-weight: 600; font-size: 14px; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
461:.hud-record { font-family: var(--font-cond); font-size: 9px; color: var(--muted); letter-spacing: 0.1em; margin-bottom: 6px; }
462:.hp-track { height: 9px; background: rgba(255, 255, 255, 0.09); border-radius: 2px; overflow: hidden; position: relative; transform: skewX(-12deg); border: 1px solid rgba(255, 255, 255, 0.08); }
463:.hp-fill { height: 100%; background: linear-gradient(90deg, #ff2d55, #ff6b3d); transition: width 0.2s linear; box-shadow: 0 0 12px rgba(255, 45, 85, 0.35); }
464:.hp-fill.p2 { background: linear-gradient(90deg, #f2c14e, #e08a2e); box-shadow: 0 0 12px rgba(242, 193, 78, 0.3); }
465:.hud-fighter.right .hp-fill { margin-left: auto; }
466:.hp-ghost { position: absolute; inset: 0; background: rgba(255, 255, 255, 0.25); transition: width 0.8s ease 0.2s; }
467:.stamina-track { height: 4px; margin-top: 4px; background: rgba(255, 255, 255, 0.08); border-radius: 2px; overflow: hidden; transform: skewX(-12deg); }
468:.stamina-fill { height: 100%; background: linear-gradient(90deg, #38bdf8, #22d3ee); transition: width 0.15s linear; }
469:.stamina-fill.p2 { background: linear-gradient(90deg, #34d399, #a3e635); margin-left: auto; }
470:.round-center { text-align: center; min-width: 120px; }
471:.round-label { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.28em; color: var(--muted); text-transform: uppercase; }
472:.round-timer { font-family: var(--font-display); font-size: 46px; line-height: 0.85; color: var(--text); text-shadow: 0 4px 24px rgba(0, 0, 0, 0.6); }
473:.round-timer.low { color: #ff5a72; animation: pulse 1s infinite; }
474:.round-dots { display: flex; gap: 4px; justify-content: center; margin-top: 5px; }
475:.round-dots i { width: 16px; height: 3px; background: rgba(255, 255, 255, 0.15); }
476:.round-dots i.done { background: var(--gold); }
478:.hud-bottom { position: absolute; bottom: 18px; left: 0; right: 0; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 clamp(14px, 3vw, 38px); gap: 14px; }
479:.hud-stats { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.1em; color: rgba(255, 255, 255, 0.5); display: flex; gap: 14px; text-transform: uppercase; }
480:.hud-stats b { color: var(--text); font-weight: 600; }
481:.hud-actions { display: flex; gap: 8px; }
482:.hud-btn { width: 40px; height: 40px; border-radius: 50%; background: rgba(8, 8, 12, 0.7); border: 1px solid rgba(255, 255, 255, 0.15); color: var(--text); display: grid; place-items: center; cursor: pointer; backdrop-filter: blur(6px); }
483:.hud-btn:hover { border-color: var(--gold); color: var(--gold); }
484:.combo-meter { position: absolute; left: clamp(14px, 3vw, 38px); top: 130px; font-family: var(--font-display); font-size: 32px; color: var(--gold); opacity: 0; transform: translateX(-10px); transition: 0.2s; text-shadow: 0 4px 18px rgba(0, 0, 0, 0.8); }
485:.combo-meter.show { opacity: 1; transform: none; }
486:.combo-meter small { display: block; font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.2em; color: var(--text); }
487:.announcer { position: absolute; left: 50%; top: 30%; transform: translate(-50%, -50%); text-align: center; opacity: 0; transition: 0.3s; pointer-events: none; }
488:.announcer.show { opacity: 1; }
489:.announcer .big { font-family: var(--font-display); font-size: clamp(56px, 9vw, 118px); line-height: 0.8; color: var(--text); text-shadow: 0 12px 60px rgba(0, 0, 0, 0.9), 0 0 40px rgba(242, 193, 78, 0.18); }
490:.announcer .small { font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.3em; color: var(--gold); text-transform: uppercase; margin-top: 8px; }
491:.count-overlay { position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none; }
492:.count-num { font-family: var(--font-display); font-size: clamp(120px, 22vw, 250px); color: var(--gold); line-height: 0.8; text-shadow: 0 0 60px rgba(242, 193, 78, 0.35); animation: countPop 0.5s ease-out; }
495:/* Touch controls */
496:.touch-controls { position: absolute; inset: 0; pointer-events: none; display: none; }
497:.touch-controls.enabled { display: block; }
498:.joystick { position: absolute; left: 22px; bottom: 26px; width: 130px; height: 130px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.18); background: radial-gradient(circle, rgba(255, 255, 255, 0.05), rgba(0, 0, 0, 0.2)); pointer-events: auto; touch-action: none; backdrop-filter: blur(3px); }
499:.joystick::before { content: ''; position: absolute; inset: 25%; border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 50%; }
500:.joystick-knob { position: absolute; width: 54px; height: 54px; border-radius: 50%; left: 50%; top: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.32), rgba(242, 193, 78, 0.25)); border: 1px solid rgba(242, 193, 78, 0.5); box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4); }
501:.joy-label { position: absolute; left: 0; right: 0; bottom: 8px; text-align: center; font-family: var(--font-cond); font-size: 8px; letter-spacing: 0.18em; color: rgba(255, 255, 255, 0.3); }
502:.action-pad { position: absolute; right: 18px; bottom: 24px; width: 190px; height: 190px; pointer-events: none; }
503:.act-btn { position: absolute; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.2); background: rgba(8, 8, 12, 0.62); color: var(--text); display: grid; place-items: center; font-family: var(--font-display); font-size: 15px; pointer-events: auto; touch-action: none; backdrop-filter: blur(4px); transition: transform 0.08s, background 0.08s; user-select: none; }
504:.act-btn:active, .act-btn.pressed { transform: scale(0.92); background: rgba(242, 193, 78, 0.35); border-color: var(--gold); }
505:.act-btn.jab { width: 54px; height: 54px; right: 68px; top: 96px; }
506:.act-btn.cross { width: 54px; height: 54px; right: 6px; top: 62px; }
507:.act-btn.hook { width: 54px; height: 54px; right: 16px; top: 0px; }
508:.act-btn.upper { width: 54px; height: 54px; right: 84px; top: 10px; }
509:.act-btn.block { width: 58px; height: 58px; right: 132px; top: 122px; font-size: 11px; letter-spacing: 0.05em; background: rgba(15, 23, 42, 0.7); }
510:.act-btn.dodge { width: 48px; height: 48px; right: 116px; top: 56px; font-size: 10px; background: rgba(15, 23, 42, 0.7); }
511:.act-btn.getup { width: 120px; height: 54px; left: 50%; transform: translateX(-50%); bottom: 30px; border-radius: 10px; background: rgba(242, 193, 78, 0.25); font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.1em; }
512:.act-btn.getup:active { transform: translateX(-50%) scale(0.96); }
513:.act-btn.punch { border-color: rgba(242, 193, 78, 0.4); color: #ffe6a3; }
514:.desktop-hint { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.4); text-transform: uppercase; display: flex; gap: 12px; flex-wrap: wrap; }
515:.key { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border: 1px solid rgba(255, 255, 255, 0.22); border-radius: 4px; font-size: 9px; color: var(--text); background: rgba(255, 255, 255, 0.06); }
516:.touch-controls.enabled ~ .hud-bottom .desktop-hint { display: none; }
518:/* Intro / result / pause overlays */
519:.fight-overlay { position: absolute; inset: 0; background: radial-gradient(circle at 50% 40%, rgba(12, 8, 12, 0.4), rgba(4, 4, 6, 0.94)); backdrop-filter: blur(4px); z-index: 30; display: flex; align-items: center; justify-content: center; padding: 24px; overflow-y: auto; }
520:.vs-card { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: clamp(10px, 4vw, 50px); width: min(1000px, 94vw); }
521:.vs-fighter { text-align: center; }
522:.vs-fighter .portrait { width: clamp(110px, 18vw, 190px); aspect-ratio: 1; margin: 0 auto 14px; border-radius: 50%; background: radial-gradient(circle at 40% 25%, #6b202c, #131319 72%); border: 2px solid rgba(242, 193, 78, 0.35); display: grid; place-items: center; font-family: var(--font-display); font-size: 60px; color: var(--gold); box-shadow: 0 20px 80px rgba(0, 0, 0, 0.5); position: relative; overflow: hidden; }
523:.vs-fighter .portrait::after { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 50% 120%, rgba(242, 193, 78, 0.2), transparent 55%); }
524:.vs-fighter h2 { font-family: var(--font-display); font-size: clamp(28px, 4vw, 50px); line-height: 0.9; margin: 0; }
525:.vs-fighter .nickname { font-family: var(--font-cond); font-size: 12px; color: var(--gold); letter-spacing: 0.18em; text-transform: uppercase; margin: 5px 0 10px; }
526:.vs-fighter .rec { font-family: var(--font-cond); font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
527:.vs-mid { text-align: center; }
528:.vs-mid .vs { font-family: var(--font-display); font-size: clamp(54px, 9vw, 110px); color: transparent; -webkit-text-stroke: 1px rgba(242, 193, 78, 0.6); line-height: 0.8; }
529:.vs-mid .at { font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.25em; color: var(--muted); margin-bottom: 6px; }
530:.intro-details { text-align: center; margin-top: 30px; }
531:.intro-details .event { font-family: var(--font-display); font-size: 25px; color: var(--text); letter-spacing: 0.06em; }
532:.intro-details .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 4px; }
533:.intro-details .title-line { font-family: var(--font-cond); color: var(--gold); font-size: 12px; letter-spacing: 0.18em; margin-top: 8px; display: flex; gap: 8px; justify-content: center; align-items: center; }
534:.intro-buttons { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
535:.result-card { width: min(900px, 94vw); }
536:.result-head { text-align: center; margin-bottom: 20px; }
537:.result-head .method { font-family: var(--font-display); font-size: clamp(56px, 10vw, 110px); line-height: 0.8; color: var(--gold); }
538:.result-head .winner { font-family: var(--font-display); font-size: clamp(26px, 4vw, 46px); margin-top: 6px; }
539:.result-head .winner span { color: var(--gold); }
540:.result-head .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.15em; color: var(--muted); margin-top: 3px; }
541:.result-stats { display: grid; grid-template-columns: 1fr auto 1fr; gap: 20px; align-items: center; }
542:.result-side { display: flex; flex-direction: column; gap: 6px; }
543:.result-side.right { text-align: right; }
544:.result-stat { display: flex; justify-content: space-between; gap: 12px; font-family: var(--font-cond); font-size: 11px; color: var(--muted); padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
545:.result-side.right .result-stat { flex-direction: row-reverse; }
546:.result-stat b { color: var(--text); font-weight: 600; }
547:.result-purse { text-align: center; margin: 18px 0; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.1em; color: var(--muted); }
548:.result-purse b { color: var(--gold); font-size: 20px; font-family: var(--font-display); }
549:.scorecards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
550:.scorecard { border: 1px solid var(--line); border-radius: 7px; padding: 7px; text-align: center; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
551:.scorecard b { display: block; font-family: var(--font-display); font-size: 18px; color: var(--text); }
552:.result-actions { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
553:.result-news { margin-top: 18px; padding: 12px 16px; border-left: 2px solid var(--gold); background: rgba(242, 193, 78, 0.05); font-family: var(--font-cond); font-size: 13px; line-height: 1.5; }
554:.result-news span { color: var(--gold); font-size: 9px; letter-spacing: 0.18em; display: block; margin-bottom: 3px; }
555:.replay-overlay { position: absolute; top: 26px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.25em; color: var(--gold); text-transform: uppercase; background: rgba(6, 6, 8, 0.6); border: 1px solid rgba(242, 193, 78, 0.25); padding: 7px 13px; border-radius: 4px; pointer-events: none; animation: blink 1.2s infinite; }
557:.pause-menu { width: min(440px, 92vw); }
558:.pause-menu .panel-body { display: flex; flex-direction: column; gap: 8px; }
559:.pause-menu h2 { font-family: var(--font-display); font-size: 44px; margin: 0 0 4px; text-align: center; }
561:/* -------------------------------- Multiplayer -------------------------------- */
562:.mp-layout { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.75fr); gap: 18px; align-items: start; }
563:.lobby-card { padding: 26px; }
564:.room-code { font-family: var(--font-display); font-size: clamp(42px, 7vw, 72px); letter-spacing: 0.16em; color: var(--gold); text-align: center; line-height: 1; padding: 16px 0 8px; }
565:.invite-box { display: flex; gap: 8px; margin-top: 12px; }
566:.invite-box input { flex: 1; background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); color: var(--muted); border-radius: 7px; padding: 9px 11px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.03em; min-width: 0; }
567:.player-slots { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px; margin: 20px 0; }
568:.player-slot { border: 1px solid var(--line); border-radius: 12px; padding: 16px; text-align: center; background: rgba(255, 255, 255, 0.025); min-height: 150px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; }
569:.player-slot.ready { border-color: rgba(52, 211, 153, 0.45); box-shadow: inset 0 0 30px rgba(52, 211, 153, 0.06); }
570:.player-slot .avatar { width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 40% 30%, #5c1d28, #111118); border: 1px solid rgba(242, 193, 78, 0.3); display: grid; place-items: center; font-family: var(--font-display); font-size: 24px; color: var(--gold); }
571:.player-slot b { font-family: var(--font-cond); font-size: 15px; }
572:.player-slot span { font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
573:.vs-small { font-family: var(--font-display); font-size: 26px; color: var(--muted2); }
574:.connection-pill { display: inline-flex; align-items: center; gap: 7px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.08em; padding: 6px 10px; border-radius: 999px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); }
575:.connection-pill .dot { width: 7px; height: 7px; border-radius: 50%; background: #eab308; }
576:.connection-pill.online .dot { background: var(--green); box-shadow: 0 0 8px rgba(52, 211, 153, 0.8); }
577:.connection-pill.offline .dot { background: var(--red); }
578:.mp-actions { display: flex; gap: 8px; flex-wrap: wrap; }
579:.quick-list { display: flex; flex-direction: column; gap: 8px; }
580:.quick-row { display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; cursor: pointer; }
581:.quick-row:hover { border-color: rgba(242, 193, 78, 0.3); background: rgba(242, 193, 78, 0.04); }
582:.quick-row .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); }
583:.quick-row b { font-family: var(--font-cond); font-size: 13px; }
584:.quick-row span { margin-left: auto; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
585:.wager-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
586:.wager-row button { border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03); border-radius: 6px; color: var(--muted); padding: 7px 11px; font-family: var(--font-cond); font-size: 11px; cursor: pointer; }
587:.wager-row button.active { border-color: var(--gold); color: var(--gold); background: rgba(242, 193, 78, 0.08); }
588:.chat-feed { max-height: 150px; overflow-y: auto; display: flex; flex-direction: column; gap: 5px; font-family: var(--font-cond); font-size: 12px; }
589:.chat-feed .msg { color: var(--muted); }
590:.chat-feed .msg b { color: var(--text); }
591:.match-history { display: flex; flex-direction: column; }
592:.match-history .row-item { display: flex; gap: 10px; align-items: center; padding: 9px 0; border-bottom: 1px solid var(--line); font-family: var(--font-cond); font-size: 12px; }
593:.match-history .win { color: var(--green); }
594:.match-history .loss { color: #ff7c91; }
595:.mp-status { text-align: center; padding: 22px; }
596:.mp-status .big { font-family: var(--font-display); font-size: 32px; }
597:.spinner { width: 34px; height: 34px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.12); border-top-color: var(--gold); animation: spin 1s linear infinite; margin: 0 auto 12px; }
599:/* -------------------------------- Modal / toast -------------------------------- */
600:.modal-backdrop { position: fixed; inset: 0; z-index: 80; background: rgba(3, 3, 5, 0.78); backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; padding: 20px; animation: fadeIn 0.2s; }
601:.modal { width: min(560px, 94vw); max-height: 88vh; overflow-y: auto; background: #111117; border: 1px solid var(--line2); border-radius: 16px; box-shadow: var(--shadow); padding: 26px; }
602:.modal.wide { width: min(850px, 95vw); }
603:.modal h2 { font-family: var(--font-display); font-size: 34px; margin: 0 0 6px; }
604:.modal p { color: var(--muted); font-size: 13px; line-height: 1.6; }
605:.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 22px; flex-wrap: wrap; }
607:.toast-stack { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); z-index: 120; display: flex; flex-direction: column; gap: 8px; pointer-events: none; width: min(420px, 92vw); }
608:.toast { background: rgba(16, 16, 22, 0.96); border: 1px solid var(--line2); border-left: 2px solid var(--gold); border-radius: 8px; padding: 11px 14px; font-family: var(--font-cond); font-size: 13px; display: flex; align-items: center; gap: 9px; box-shadow: var(--shadow); animation: toastIn 0.28s cubic-bezier(0.22, 1, 0.36, 1); pointer-events: auto; }
609:.toast.error { border-left-color: var(--red); }
610:.toast.success { border-left-color: var(--green); }
611:.toast.achievement { border-left-color: var(--gold); background: linear-gradient(90deg, rgba(242, 193, 78, 0.15), #111117); }
612:.toast .ic { color: var(--gold); }
614:.toast.out { animation: toastOut 0.3s forwards; }
617:/* -------------------------------- Misc -------------------------------- */
618:.empty-state { text-align: center; padding: 50px 20px; color: var(--muted); }
619:.empty-state .ic { color: var(--muted2); margin-bottom: 10px; }
620:.empty-state b { display: block; font-family: var(--font-display); font-size: 26px; color: var(--text); margin-bottom: 4px; }
621:.loading-block { display: grid; place-items: center; padding: 60px; }
622:.kbd-hint { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); letter-spacing: 0.1em; }
623:.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin-bottom: 18px; overflow-x: auto; }
624:.tabs button { background: none; border: none; border-bottom: 2px solid transparent; color: var(--muted); padding: 10px 14px; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; cursor: pointer; white-space: nowrap; }
