        <button class="btn btn-sm" data-nav="rankings">${icon('chart', 15)} Rankings</button>
        <button class="btn btn-sm btn-gold-outline" data-action="edit">${icon('person', 15)} Editar Lutador</button>`,
    })}

    <div class="career-top">
