              <div class="nick">${esc(p.nickname || 'Sem apelido')} · ${countryName(p.nationality)}</div>
              <div class="row" style="margin-top:8px;gap:6px">
                <span class="chip gold">${icon('crown', 12)} RANKING #${rank}</span>
                <span class="chip">${icon('star', 12)} OVERALL ${overallValue}</span>
                <span class="chip">${STYLE_BY_ID[p.style]?.name || 'Técnico'}</span>
              </div>
            </div>
          </div>
          <div class="profile-stats">
            <div><b>${recordText(c.record)}</b><span>Cartel</span></div>
            <div><b>${c.record.ko}</b><span>Nocautes</span></div>
            <div><b>${c.reputation}</b><span>Reputação</span></div>
            <div><b>${winRate}%</b><span>Vitórias</span></div>
            <div><b>${c.belts.length}</b><span>Cinturões</span></div>
          </div>
        </div>
      </div>
      <div class="career-side">
        ${active ? `
          <div class="next-fight-card">
            <div class="kicker">Contrato assinado · ${esc(active.eventName)}</div>
            <h3>${esc(p.name)} <span class="muted" style="font-family:var(--font-cond);font-size:14px">VS</span> ${esc(active.opponent.name)}</h3>
            <div class="meta">${icon('calendar', 11)} ${fmtDate(active.date)} · ${esc(active.arenaName)}, ${esc(active.city)} · ${active.rounds} rounds</div>
            <div class="row between" style="margin-top:12px">
              <div class="row" style="gap:6px">
                <span class="chip gold">${icon('coin', 12)} C$ ${fmtNum(active.purse)}</span>
                <span class="chip">${icon('coin', 12)} ${active.coinReward} TG</span>
                ${active.title ? `<span class="chip red">${icon('belt', 12)} TÍTULO</span>` : ''}
              </div>
              <button class="btn btn-primary btn-sm" data-action="fight">${icon('play', 14)} Iniciar Luta</button>
            </div>
          </div>
        ` : `
          <div class="next-fight-card">
            <div class="kicker">Próximo passo</div>
            <h3>Assine um contrato</h3>
            <div class="meta">Escolha uma das ofertas abaixo e prepare o campo de treino.</div>
            <div class="row" style="margin-top:12px;gap:6px">
              <span class="chip">${icon('calendar', 11)} ${c.offers.length} ofertas</span>
              <span class="chip gold">${icon('coin', 11)} C$ ${fmtNum(c.money)}</span>
            </div>
          </div>
        `}
        <div class="stat-tile accent"><div class="label">TG COIN</div><div class="value">${fmtNum(c.coins)}</div><div class="sub">Moeda virtual</div></div>
        <div class="stat-tile"><div class="label">Sessões de treino</div><div class="value">${c.training.sessionsLeft}<span style="font-size:14px;color:var(--muted)">/4</span></div><div class="sub">Fadiga ${c.training.fatigue}%</div></div>
      </div>
    </div>

    <div class="dashboard-grid">
      <div class="stack">
        <div class="panel">
          <div class="panel-head"><h3>${active ? 'Contrato ativo' : 'Ofertas de luta'}</h3><span class="tiny">${active ? '1 contrato' : `${c.offers.length} disponíveis`}</span></div>
          <div class="panel-body">
            ${active ? activeContract(active) : offerList(c.offers, p.division)}
            ${!active ? `<div class="notice" style="margin-top:12px">${icon('shield', 13)} Negocie a bolsa uma vez por oferta. Contratos de título exigem ranking e histórico.</div>` : ''}
          </div>
        </div>

        <div class="panel">
          <div class="panel-head"><h3>Treino & preparação</h3><button class="btn btn-sm btn-ghost" data-nav="gym">Abrir academia ${icon('arrow', 13)}</button></div>
          <div class="panel-body">
            <div class="row between" style="margin-bottom:6px"><span class="tiny">Fadiga</span><span class="tiny">${c.training.fatigue}%</span></div>
            <div class="progress" style="margin-bottom:14px"><i style="width:${c.training.fatigue}%;background:linear-gradient(90deg,#34d399,#f2c14e,#e11d48)"></i></div>
            <div class="training-row"><div class="ico">${icon('gym', 17)}</div><div style="flex:1"><b>${c.training.sessionsLeft} sessões restantes</b><span>Total de ${c.training.totalSessions} sessões concluídas</span></div><span class="chip ${c.training.sessionsLeft > 0 ? 'green' : ''}">${c.training.sessionsLeft > 0 ? 'Pronto' : 'Descansar'}</span></div>
            <div class="training-row"><div class="ico">${icon('coach', 17)}</div><div style="flex:1"><b>${esc(c.gym.coach === 'Basico' ? 'Coach Básico' : c.gym.coach)}</b><span>${c.gym.equipment.length} equipamentos comprados</span></div><span class="chip">Nível ${c.gym.level}</span></div>
            <div class="training-row"><div class="ico">${icon('sponsor', 17)}</div><div style="flex:1"><b>${c.sponsor ? 'Patrocínio ativo' : 'Sem patrocínio'}</b><span>${c.sponsor ? 'Bônus por vitória garantido' : 'Visite a Loja TG para fechar um contrato'}</span></div><button class="btn btn-sm btn-ghost" data-nav="shop">Loja</button></div>
          </div>
        </div>

        <div class="panel">
          <div class="panel-head"><h3>Galeria de cinturões</h3><span class="tiny">${c.belts.length} títulos</span></div>
          <div class="panel-body">
            ${c.belts.length ? `<div class="belts-strip">${c.belts.map((b) => `<div class="belt-card">${beltIcon(b)}<div><b>${beltTierName(b.tier)}</b><span>${orgOf(b.org).short} · ${divisionName(b.division)}</span><div class="tiny">${b.defenses || 0} defesas · conquistado em ${fmtDate(b.wonAt)}</div></div></div>`).join('')}</div>` : `<div class="empty-state" style="padding:24px">${icon('belt', 32)}<b>Nenhum cinturão ainda</b><p>Vença lutas, suba no ranking e dispute um título mundial.</p></div>`}
          </div>
        </div>
      </div>

      <div class="stack">
        <div class="panel">
          <div class="panel-head"><h3>Campeões da divisão</h3><span class="tiny">${div.name}</span></div>
          <div class="panel-body" style="display:flex;flex-direction:column;gap:10px">
            ${champions.map(({ org, fighter, playerBelt }) => `
              <div class="champ-row">
                <span class="org-dot" style="background:${org.color}"></span>
                <div style="flex:1;min-width:0">
                  <div class="tiny" style="color:${org.color}">${org.short}</div>
                  <b>${playerBelt ? esc(p.name) : esc(fighter?.name || 'Vacante')}</b>
                </div>
                ${playerBelt ? '<span class="tag gold">VOCÊ</span>' : `<span class="tiny">${fighter ? recordText(fighter.record) : '—'}</span>`}
              </div>`).join('')}
          </div>
        </div>

        <div class="panel">
          <div class="panel-head"><h3>TG News</h3><button class="btn btn-sm btn-ghost" data-nav="news">Ver tudo ${icon('arrow', 13)}</button></div>
          <div class="panel-body news-mini">
            ${news.map((n) => `<div class="item" data-news="${esc(n.id)}"><span class="dot"></span><div style="flex:1"><div class="t">${esc(n.title)}</div><div class="d">${fmtDate(n.date)} · ${esc(n.tag || 'NOTÍCIA')}</div></div></div>`).join('') || `<p class="tiny">Nenhuma notícia ainda. Simule uma semana para movimentar o mundo.</p>`}
          </div>
        </div>

        <div class="panel">
          <div class="panel-head"><h3>Metas da temporada</h3><span class="tiny">${c.season.wins}/${c.season.fights} vitórias</span></div>
          <div class="panel-body">
            <div class="bars">
              <div class="bar-row"><span>Top 10</span><span class="bar-track"><i class="bar-fill" style="width:${Math.max(4, 100 - Math.min(100, rank))}%"></i></span><span class="attr-value">#${rank}</span></div>
              <div class="bar-row"><span>Reputação</span><span class="bar-track"><i class="bar-fill" style="width:${c.reputation}%"></i></span><span class="attr-value">${c.reputation}</span></div>
              <div class="bar-row"><span>Nocautes</span><span class="bar-track"><i class="bar-fill red" style="width:${Math.min(100, c.record.ko * 10)}%"></i></span><span class="attr-value">${c.record.ko}</span></div>
              <div class="bar-row"><span>Defesas</span><span class="bar-track"><i class="bar-fill green" style="width:${Math.min(100, c.season.defenses * 25)}%"></i></span><span class="attr-value">${c.season.defenses}</span></div>
            </div>
            <div class="divider" style="margin:14px 0"></div>
            <div class="row between"><span class="tiny">Bolsas acumuladas</span><b class="gold">${fmtMoney(c.totalPurse)}</b></div>
            <div class="row between" style="margin-top:6px"><span class="tiny">Melhor vitória</span><b style="font-size:12px">${esc(c.season.bestWin || '—')}</b></div>
          </div>
        </div>

        <div class="panel">
          <div class="panel-head"><h3>Próximos eventos</h3></div>
          <div class="panel-body" style="display:flex;flex-direction:column;gap:8px">
            ${(c.offers || []).slice(0, 3).map((o) => `<div class="quick-row" data-news-offer="${esc(o.id)}"><span class="dot" style="background:${DIVISION_BY_ID[o.opponent.division || p.division]?.color || '#f2c14e'}"></span><div><b>${esc(o.eventName)}</b><div class="tiny">${fmtDate(o.date)} · ${esc(o.arenaName)}</div></div><span class="tiny">${o.rounds}R</span></div>`).join('')}
          </div>
        </div>
      </div>
    </div>
  </div>`);

  // Offer actions
  el.querySelectorAll('[data-offer]').forEach((row) => {
    row.addEventListener('click', (e) => {
      if (e.target.closest('[data-offer-action]')) return;
      el.querySelectorAll('[data-offer]').forEach((r) => r.classList.toggle('selected', r === row));
      el.querySelectorAll('[data-offer-actions]').forEach((a) => { a.style.display = 'none'; });
      row.querySelector('[data-offer-actions]').style.display = 'flex';
    });
  });
  el.querySelectorAll('[data-offer-action]').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const offer = c.offers.find((o) => o.id === btn.dataset.offerId);
      if (!offer) return;
      const action = btn.dataset.offerAction;
      if (action === 'accept') {
        ui.confirm({
          title: 'Assinar contrato?',
          message: `Você enfrentará <b>${esc(offer.opponent.name)}</b> em ${fmtDate(offer.date)} na ${esc(offer.arenaName)}. Bolsa: <b>C$ ${fmtNum(offer.purse)}</b> + ${offer.coinReward} TG COIN.${offer.title ? '<br><br><b class="gold">Esta luta vale o ' + beltTierName(offer.title.tier) + '!</b>' : ''}`,
          confirmLabel: 'Assinar e preparar',
          onConfirm: () => {
            const res = acceptOffer(save, offer);
            if (!res.ok) { ui.toast(res.message, 'error', 'lock'); return; }
            persist(save, true);
            ui.toast('Contrato assinado! Prepare-se na academia.', 'success', 'check');
            ui.refresh({ scroll: 'keep' });
          },
        });
      } else if (action === 'negotiate') {
        const res = negotiateOffer(offer);
        ui.toast(res.message, res.ok ? 'success' : 'error', res.ok ? 'coin' : 'lock');
        if (res.ok) persist(save, true);
        ui.refresh({ scroll: 'keep' });
      } else if (action === 'decline') {
        ui.confirm({
          title: 'Recusar oferta?', message: `A oferta contra ${esc(offer.opponent.name)} será removida.`, danger: true,
          confirmLabel: 'Recusar', onConfirm: () => {
            declineOffer(save, ui.universe, offer.id);
            persist(save, true);
            ui.refresh({ scroll: 'keep' });
          },
        });
      }
    });
  });

  el.querySelector('[data-action="fight"]')?.addEventListener('click', () => {
    ui.navigate('fight', {
      mode: 'career', offer: c.activeOffer, arenaId: c.activeOffer.arenaId,
      rounds: c.activeOffer.rounds, division: p.division,
    });
  });
  el.querySelector('[data-action="cancel-contract"]')?.addEventListener('click', () => {
    ui.confirm({
      title: 'Cancelar contrato?', message: 'Cancelar pode reduzir sua reputação e gerar uma notícia negativa.', danger: true,
      confirmLabel: 'Cancelar luta', onConfirm: () => {
        cancelOffer(save);
        c.reputation = Math.max(0, c.reputation - 2);
        persist(save, true);
        ui.refresh({ scroll: 'keep' });
      },
    });
  });
  el.querySelector('[data-action="edit"]')?.addEventListener('click', () => ui.navigate('editor', { mode: 'edit' }));
  el.querySelector('[data-action="rest"]')?.addEventListener('click', () => {
    restDays(save, ui.universe, 7);
    persist(save, true);
    ui.toast('Uma semana se passou. Sessões restauradas e rankings movimentados.', 'success', 'clock');
    ui.refresh({ scroll: 'keep' });
  });
  el.querySelectorAll('[data-news]').forEach((item) => item.addEventListener('click', () => ui.navigate('news', { id: item.dataset.news })));
  el.querySelectorAll('[data-news-offer]').forEach((item) => item.addEventListener('click', () => {
    const row = el.querySelector(`[data-offer="${item.dataset.newsOffer}"]`);
    row?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    row?.click();
  }));

  return el;
}

function offerList(offers, division) {
  if (!offers?.length) return `<p class="tiny">Nenhuma oferta no momento. Descanse alguns dias para receber novas propostas.</p>`;
  return `<div class="offer-list">${offers.map((o) => `
    <div class="offer-card" data-offer="${esc(o.id)}">
      <div class="avatar-lg" style="width:46px;height:46px;font-size:16px">${initials(o.opponent.name)}</div>
      <div class="opp">
        <b>${esc(o.opponent.name)}</b>
        <span>${esc(o.opponent.nick || '')} ${o.opponent.nick ? '·' : ''} ${recordText(o.opponent.record)} · Overall ${o.opponent.overall} · ${esc(o.styleName || '')}</span>
        <div class="row" style="gap:5px;margin-top:5px">
          ${o.title ? `<span class="tag gold">${esc(beltTierName(o.title.tier))}</span>` : ''}
          <span class="tag ${o.hype > 70 ? 'red' : 'blue'}">HYPE ${o.hype}</span>
          <span class="tag">${o.rounds} ROUNDS</span>
          ${o.negotiated ? '<span class="tag green">NEGOCIADO</span>' : ''}
        </div>
      </div>
      <div class="purse"><b>${fmtNum(o.purse)}</b><span>C$ · ${o.coinReward} TG</span><span>${fmtDate(o.date)}</span></div>
      <div class="offer-actions" data-offer-actions style="display:none">
        <button class="btn btn-sm btn-primary" data-offer-action="accept" data-offer-id="${esc(o.id)}">Aceitar</button>
        <button class="btn btn-sm" data-offer-action="negotiate" data-offer-id="${esc(o.id)}" ${o.negotiated ? 'disabled' : ''}>Negociar</button>
        <button class="btn btn-sm btn-ghost" data-offer-action="decline" data-offer-id="${esc(o.id)}">Recusar</button>
      </div>
    </div>`).join('')}</div>`;
}

function activeContract(offer) {
  return `<div class="active-contract">
    <div class="row between" style="align-items:flex-start">
      <div>
        <div class="kicker">${esc(offer.eventName)}</div>
        <h2 style="font-family:var(--font-display);font-size:38px;margin:2px 0 0;line-height:0.9">${esc(offer.opponent.name)}</h2>
        <div class="tiny" style="margin-top:6px">${recordText(offer.opponent.record)} · Overall ${offer.opponent.overall} · ${esc(offer.styleName)} · ${offer.opponent.age} anos</div>
        <div class="row" style="gap:6px;margin-top:10px">
          <span class="chip gold">${icon('calendar', 11)} ${fmtDate(offer.date)}</span>
          <span class="chip">${icon('flag', 11)} ${esc(offer.arenaName)}</span>
          <span class="chip">${icon('coin', 11)} ${fmtNum(offer.purse)} C$ + ${offer.coinReward} TG</span>
          ${offer.title ? `<span class="chip red">${icon('belt', 11)} ${esc(beltTierName(offer.title.tier))}</span>` : ''}
        </div>
        <p class="tiny" style="margin-top:12px;max-width:520px">"${esc(offer.callout || STYLE_BY_ID[offer.opponent.style]?.desc || 'Vamos ver quem é o melhor.')}"</p>
      </div>
      <div style="text-align:center;flex:none">
        <div class="avatar-lg" style="width:76px;height:76px;font-size:26px">${initials(offer.opponent.name)}</div>
        <div class="tiny" style="margin-top:4px">${esc(offer.opponent.nationality || '')}</div>
      </div>
    </div>
    <div class="row" style="margin-top:16px;gap:8px">
      <button class="btn btn-primary" data-action="fight">${icon('play', 15)} Iniciar Luta</button>
      <button class="btn btn-ghost" data-action="cancel-contract">Cancelar contrato</button>
    </div>
  </div>`;
}

function beltIcon(belt) {
  const org = orgOf(belt.org);
  return `<div class="belt-art" style="background:radial-gradient(circle at 40% 35%, #fff3c4, ${org.color} 48%, #3a2405)">${org.short}</div>`;
}

// Rankings: 11 divisions, 3 organizations, TOP 100, champions and fighter dossiers.
import { icon } from './icons.js';
import {
  esc, h, fmtNum, recordText, initials, countryName, divisionName, statTile, screenHead, attrBars, overall, orgOf, beltTierName,
} from './helpers.js';
import { DIVISIONS, ORGS, STYLE_BY_ID, BELT_TIERS } from '../core/data.js';
import { rankingsFor, championOf, playerRank } from '../core/universe.js';
import { createPlayerFighter } from '../core/store.js';
import { playerRankNow } from '../core/career.js';

export function rankingsScreen(ui, data = {}) {
  const save = ui.save;
  let division = data.division || save?.profile?.division || 'middle';
  let org = data.org || null;
  if (!DIVISIONS.find((d) => d.id === division)) division = 'middle';

  const el = h(`<div class="screen">
    ${ui.topbar('rankings')}
    ${screenHead({
      kicker: 'Organizações & cinturões', title: 'Rankings mundiais',
      sub: '100 lutadores por divisão. Três organizações. Sete níveis de cinturão. O topo não é para todos.',
      actions: save ? `<span class="chip gold">${icon('crown', 13)} Você: #${playerRankNow(save, ui.universe)}</span>` : '',
    })}
    <div class="division-tabs" data-divisions>
      ${DIVISIONS.map((d) => `<button data-div="${d.id}" class="${d.id === division ? 'active' : ''}" style="--dc:${d.color}"><span style="color:${d.color}">●</span> ${d.name}</button>`).join('')}
    </div>
    <div class="row between" style="margin-bottom:14px">
      <div class="org-tabs" data-orgs>
        <button data-org="" class="${!org ? 'active' : ''}">GERAL</button>
        ${ORGS.map((o) => `<button data-org="${o.id}" class="${org === o.id ? 'active' : ''}">${o.short}</button>`).join('')}
      </div>
      <span class="tiny" data-count></span>
    </div>
    <div class="rank-layout">
      <div class="panel"><div class="rank-list" data-ranklist></div></div>
      <div class="stack" data-side></div>
    </div>
  </div>`);

  const listEl = el.querySelector('[data-ranklist]');
  const sideEl = el.querySelector('[data-side]');
  const countEl = el.querySelector('[data-count]');

  const render = () => {
    const player = save ? createPlayerFighter(save) : null;
    const list = rankingsFor(ui.universe, division, player, org);
    countEl.textContent = `${list.length} lutadores · ${divisionName(division)}${org ? ' · ' + orgOf(org).short : ''}`;
    listEl.innerHTML = list.map((f, i) => {
      const rank = i + 1;
      const isPlayer = f.isPlayer || f.id === 'player';
      const belts = f.belts || [];
      return `<div class="rank-row ${isPlayer ? 'me' : ''}" data-fighter="${esc(f.id)}" data-player="${isPlayer ? '1' : ''}">
        <div class="num ${rank <= 3 ? 'top' : ''}">${rank}</div>
        <div class="who">
          <b>${esc(f.name)} ${belts.length ? `<span class="gold">${icon('belt', 12)}</span>` : ''} ${isPlayer ? '<span class="tag gold">VOCÊ</span>' : ''}</b>
          <span>${esc(f.nick || 'Sem apelido')} · ${countryName(f.nationality)} · ${STYLE_BY_ID[f.style]?.name || 'Estilo'} · ${f.age || '—'} anos</span>
        </div>
        <div class="rec">${recordText(f.record)}<br><span class="tiny">${(f.belts || []).length ? (f.belts || []).map((b) => orgOf(b.org).short).join(' ') : '&nbsp;'}</span></div>
        <div class="pts">${fmtNum(f.points || 0)}<br><span class="tiny" style="font-family:var(--font-cond);font-size:8px;color:var(--muted2)">PTS</span></div>
      </div>`;
    }).join('') || `<div class="empty-state"><b>Ranking vazio</b><p>Simule o universo para gerar resultados.</p></div>`;

    // Champion / player side
    const playerRanking = player ? playerRank(ui.universe, division, player.points) : null;
    const playerBelt = save?.career?.belts?.find((b) => b.division === division && (!org || b.org === org));
    const champ = org ? championOf(ui.universe, division, org) : list[0];
    const champBelts = champ?.belts || [];
    const top = list.slice(0, 3);
    const playerInDiv = save?.profile?.division === division;
    sideEl.innerHTML = `
      <div class="champ-card">
        <div class="belt-ico">${icon('belt', 36)}</div>
        <div class="nick">${org ? 'CAMPEÃO ' + orgOf(org).short : 'LÍDER DA DIVISÃO'}</div>
        <div class="name">${playerBelt && save ? esc(save.profile.name) : esc(champ?.name || 'Vacante')}</div>
        <div class="nick">${playerBelt && save ? 'SEU CINTURÃO' : esc(champ?.nick || 'Aguardando novo campeão')}</div>
        <div class="row" style="margin-top:10px;gap:6px">
          <span class="chip gold">${recordText(playerBelt && save ? save.career.record : champ?.record)}</span>
          <span class="chip">${champBelts.length} cinturões</span>
          <span class="chip">${divisionName(division)}</span>
        </div>
        ${champ ? `<button class="btn btn-sm btn-block" style="margin-top:12px" data-fighter="${esc(playerBelt && save ? 'player' : champ.id)}">${icon('eye', 14)} Ver dossiê</button>` : ''}
      </div>
      <div class="panel">
        <div class="panel-head"><h3>Top 3 da divisão</h3></div>
        <div class="panel-body" style="display:flex;flex-direction:column;gap:9px">
          ${top.map((f, i) => `<div class="top3-row"><span class="num">${i + 1}</span><div style="flex:1;min-width:0"><b>${esc(f.name)}</b><div class="tiny">${recordText(f.record)} · ${countryName(f.nationality)}</div></div><span class="gold tiny">${fmtNum(f.points)} pts</span></div>`).join('')}
        </div>
      </div>
      ${save ? `<div class="panel">
        <div class="panel-head"><h3>Sua posição</h3></div>
        <div class="panel-body">
          <div class="row between"><div><div class="tiny">Ranking ${divisionName(division)}</div><div class="rank-big">#${playerInDiv ? playerRanking : '—'}</div></div><div style="text-align:right"><div class="tiny">Pontos</div><div class="rank-big">${fmtNum(save.career.points)}</div></div></div>
          <div class="divider" style="margin:14px 0"></div>
          <div class="row between"><span class="tiny">Cinturões na divisão</span><b>${save.career.belts.filter((b) => b.division === division).length}</b></div>
          <div class="row between" style="margin-top:7px"><span class="tiny">Recorde</span><b>${recordText(save.career.record)}</b></div>
          <div class="row between" style="margin-top:7px"><span class="tiny">Reputação</span><b>${save.career.reputation}</b></div>
          ${playerInDiv && playerRanking <= 2 && !playerBelt ? `<div class="notice" style="margin-top:12px">${icon('crown', 13)} Você está no TOP 2. Uma vitória pode valer uma disputa mundial.</div>` : ''}
        </div>
      </div>` : ''}
      <div class="panel">
        <div class="panel-head"><h3>Cinturões em jogo</h3><span class="tiny">${org ? orgOf(org).short : 'TODAS'}</span></div>
        <div class="panel-body" style="display:flex;flex-direction:column;gap:8px">
          ${BELT_TIERS.map((t) => `<div class="row between"><span class="tiny">${t.name}</span><span class="tag ${t.prestige >= 5 ? 'gold' : ''}">${t.short}</span></div>`).join('')}
        </div>
      </div>
    `;
    bindFighterButtons();
  };

  const bindFighterButtons = () => {
    el.querySelectorAll('[data-fighter]').forEach((row) => {
      row.addEventListener('click', () => openFighter(row.dataset.fighter));
    });
  };

  const openFighter = (id) => {
    let fighter = ui.universe?.fighters.find((f) => f.id === id);
    let isPlayer = id === 'player';
    if (isPlayer && save) {
      fighter = createPlayerFighter(save);
      fighter.belts = save.career.belts;
      fighter.points = save.career.points;
      fighter.isPlayer = true;
    }
    if (!fighter) return;
    const belts = fighter.belts || [];
    const attr = fighter.attributes || {};
    ui.modal({
      wide: true,
      title: esc(fighter.name),
      body: `<div class="dossier">
        <div class="dossier-head">
          <div class="avatar-lg">${initials(fighter.name)}</div>
          <div style="flex:1">
            <div class="kicker">${esc(fighter.nick || 'Sem apelido')}</div>
            <div class="row" style="gap:6px;margin-top:6px;flex-wrap:wrap">
              <span class="chip">${countryName(fighter.nationality)}</span>
              <span class="chip">${STYLE_BY_ID[fighter.style]?.name || 'Estilo'}</span>
              <span class="chip gold">${recordText(fighter.record)}</span>
              <span class="chip">${fighter.age || '—'} anos</span>
              <span class="chip">Overall ${fighter.overall || overall(attr)}</span>
            </div>
          </div>
        </div>
        <div class="dossier-body">
          <div>${attrBars(attr)}</div>
          <div>
            <div class="tiny" style="margin-bottom:6px">CINTURÕES</div>
            ${belts.length ? belts.map((b) => `<div class="mini-belt"><span>${icon('belt', 16)}</span><div><b>${beltTierName(b.tier)}</b><div class="tiny">${orgOf(b.org).short} · ${divisionName(b.division || division)} · ${b.defenses || 0} defesas</div></div></div>`).join('') : '<p class="tiny">Nenhum cinturão conquistado.</p>'}
            <div class="divider" style="margin:12px 0"></div>
            <div class="row between"><span class="tiny">Pontos de ranking</span><b class="gold">${fmtNum(fighter.points || 0)}</b></div>
            <div class="row between" style="margin-top:6px"><span class="tiny">Nacionalidade</span><b>${countryName(fighter.nationality)}</b></div>
            <div class="row between" style="margin-top:6px"><span class="tiny">Divisão</span><b>${divisionName(fighter.division || division)}</b></div>
          </div>
        </div>
      </div>`,
      actions: [
        { label: 'Fechar', cls: 'btn-ghost' },
        {
          label: isPlayer ? 'Ir para carreira' : 'Ver ranking', cls: 'btn-primary',
          onClick: () => { if (isPlayer) ui.navigate('career'); },
        },
      ],
    });
  };

  el.querySelectorAll('[data-div]').forEach((btn) => {
    btn.addEventListener('click', () => {
      division = btn.dataset.div;
      el.querySelectorAll('[data-div]').forEach((b) => b.classList.toggle('active', b === btn));
      render();
    });
  });
  el.querySelectorAll('[data-org]').forEach((btn) => {
    btn.addEventListener('click', () => {
      org = btn.dataset.org || null;
      el.querySelectorAll('[data-org]').forEach((b) => b.classList.toggle('active', b === btn));
      render();
    });
  });

  render();
  return el;
}

// TG News: dynamic articles generated from the living universe and career events.
import { icon } from './icons.js';
import { esc, h, fmtDate, divisionName, screenHead, orgOf, initials } from './helpers.js';
import { NEWS_CATS, DIVISION_BY_ID, ORGS, DIVISIONS } from '../core/data.js';
import { seedNews, simulateBackground, championOf, makeRumorArticle } from '../core/universe.js';
import { addNews, persist } from '../core/store.js';

export function newsScreen(ui, data = {}) {
  const save = ui.save;
  if (save && (!save.career.news || save.career.news.length === 0)) {
    seedNews(save, ui.universe, 14);
    persist(save, true);
  }
  let cat = data.cat || 'latest';
  let selectedId = data.id || null;

  const el = h(`<div class="screen">
    ${ui.topbar('news')}
    ${screenHead({
      kicker: 'TG News · cobertura mundial', title: 'Notícias do ringue',
      sub: 'Resultados, contratos, rivalidades e campeões gerados a partir dos dados reais da sua carreira e do universo.',
      actions: `<button class="btn btn-sm" data-action="simulate">${icon('swap', 14)} Atualizar mundo</button>`,
    })}
    <div class="news-filter" data-filters>
      ${NEWS_CATS.map((c) => `<button data-cat="${c.id}" class="${c.id === cat ? 'active' : ''}">${c.name}</button>`).join('')}
    </div>
    <div data-news-layout></div>
  </div>`);

  const layout = el.querySelector('[data-news-layout]');

  const universeArticles = () => {
    if (save) return save.career.news;
    const out = [];
    let seed = 0;
    for (const div of DIVISIONS.slice(0, 6)) {
      for (const org of ORGS) {
        const champ = championOf(ui.universe, div.id, org.id);
        if (!champ) continue;
        out.push({
          id: 'u' + (seed++), date: new Date().toISOString(), cat: 'title', tag: 'CAMPEÃO',
          title: `${champ.name} segue no topo dos ${div.name.toLowerCase()}s pelo ${org.short}`,
          subtitle: `${champ.record.w}-${champ.record.l}-${champ.record.d} · ${champ.record.ko} nocautes · ${champ.belts?.[0]?.defenses || 0} defesas.`,
          body: `${champ.name}, ${champ.age} anos, é o atual campeão ${org.short} dos ${div.name.toLowerCase()}s. Com cartel de ${champ.record.w}-${champ.record.l}-${champ.record.d} e ${champ.record.ko} nocautes, ele é considerado um dos lutadores mais perigosos do circuito.\n\nCrie uma carreira para acompanhar as notícias da sua própria história, contratos e disputas de cinturão.`,
          division: div.id, hero: { name: champ.name, nick: champ.nick, color: div.color }, featured: seed === 1,
        });
      }
    }
    return out;
  };

  const render = () => {
    const all = universeArticles().slice().sort((a, b) => new Date(b.date) - new Date(a.date));
    const filtered = cat === 'latest' ? all : all.filter((a) => a.cat === cat);
    const feature = filtered.find((a) => a.id === selectedId) || filtered.find((a) => a.featured) || filtered[0];
    const rest = filtered.filter((a) => a !== feature);
    if (feature) selectedId = feature.id;
    const divColor = DIVISION_BY_ID[feature?.division]?.color || '#f2c14e';
    layout.innerHTML = feature ? `
      <div class="news-layout">
        <div>
          <div class="news-feature" data-article="${esc(feature.id)}">
            <div class="news-art" style="background:
              radial-gradient(circle at 72% 18%, ${divColor}55, transparent 42%),
              radial-gradient(circle at 22% 70%, rgba(225,29,72,.28), transparent 55%),
              linear-gradient(135deg, #17111a, #0a0a0e 70%)"></div>
            <div class="content">
              <div class="row" style="gap:6px"><span class="tag gold">${esc(feature.tag || 'NOTÍCIA')}</span><span class="tiny">${fmtDate(feature.date)}</span></div>
              <h2>${esc(feature.title)}</h2>
              <p>${esc(feature.subtitle || '')}</p>
              <div class="row" style="margin-top:14px;gap:8px">
                <span class="chip">${icon('globe', 12)} ${divisionName(feature.division)}</span>
                <span class="chip">${icon('news', 12)} Ler matéria completa</span>
              </div>
            </div>
          </div>
          <div class="panel" style="margin-top:16px">
            <div class="panel-head"><h3>Mais notícias</h3><span class="tiny">${filtered.length} matérias</span></div>
            <div class="panel-body" style="padding-top:6px">
              ${rest.length ? rest.map((a) => `<div class="news-item-card" data-article="${esc(a.id)}">
                <div class="thumb" style="background:radial-gradient(circle at 60% 30%, ${(DIVISION_BY_ID[a.division]?.color || '#f2c14e')}66, #13131a 62%)"><span>${initials(a.hero?.name || a.title)}</span></div>
                <div style="flex:1;min-width:0"><div class="t">${esc(a.title)}</div><div class="meta">${fmtDate(a.date)} · ${esc(a.tag || 'NOTÍCIA')} · ${divisionName(a.division)}</div></div>
                ${icon('arrow', 15)}
              </div>`).join('') : `<div class="empty-state" style="padding:30px"><b>Nada nesta categoria</b><p>Tente outra editoria ou atualize o mundo.</p></div>`}
            </div>
          </div>
        </div>
        <div class="stack">
          <div class="panel">
            <div class="panel-head"><h3>Editorias</h3></div>
            <div class="panel-body" style="display:flex;flex-direction:column;gap:2px">
              ${NEWS_CATS.map((c) => `<button class="news-cat-row ${cat === c.id ? 'active' : ''}" data-cat="${c.id}"><span>${c.name}</span><b>${c.id === 'latest' ? all.length : all.filter((a) => a.cat === c.id).length}</b></button>`).join('')}
            </div>
          </div>
          <div class="panel">
            <div class="panel-head"><h3>Radar de campeões</h3></div>
            <div class="panel-body" style="display:flex;flex-direction:column;gap:10px">
              ${ORGS.map((org) => {
                const champ = championOf(ui.universe, save?.profile?.division || 'middle', org.id);
                return `<div class="champ-row"><span class="org-dot" style="background:${org.color}"></span><div style="flex:1"><div class="tiny" style="color:${org.color}">${org.short}</div><b>${esc(champ?.name || 'Vacante')}</b></div><span class="tiny">${champ ? `${champ.record.w}-${champ.record.l}` : '—'}</span></div>`;
              }).join('')}
            </div>
          </div>
          <div class="notice">${icon('news', 13)} As manchetes são geradas a partir de resultados simulados, rankings, contratos e títulos do seu save. Nada é estático.</div>
        </div>
      </div>
    ` : `<div class="empty-state">${icon('news', 40)}<b>Sem notícias nesta editoria</b><p>Atualize o mundo para gerar novos resultados.</p><button class="btn btn-primary" data-action="simulate">Atualizar mundo</button></div>`;

    layout.querySelectorAll('[data-article]').forEach((item) => {
      item.addEventListener('click', () => openArticle(item.dataset.article));
    });
    layout.querySelectorAll('[data-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        cat = btn.dataset.cat;
        selectedId = null;
        el.querySelectorAll('[data-cat]').forEach((b) => b.classList.toggle('active', b.dataset.cat === cat));
        render();
      });
    });
  };

  const openArticle = (id) => {
    const article = universeArticles().find((a) => a.id === id);
    if (!article) return;
    const color = DIVISION_BY_ID[article.division]?.color || '#f2c14e';
    ui.modal({
      wide: true,
      title: esc(article.title),
      body: `<div class="article-meta"><span class="tag gold">${esc(article.tag || 'NOTÍCIA')}</span><span class="tiny">${fmtDate(article.date)} · ${divisionName(article.division)}</span></div>
        <div class="article-hero" style="background:radial-gradient(circle at 70% 20%, ${color}66, transparent 50%), linear-gradient(135deg, #18111c, #0a0a0e)"><span>${initials(article.hero?.name || 'TG')}</span></div>
        <p class="article-body">${esc(article.subtitle || '')}

${esc(article.body || '')}</p>`,
      actions: [{ label: 'Fechar', cls: 'btn-ghost' }, { label: 'Voltar às notícias', cls: 'btn-primary' }],
    });
  };

  el.querySelector('[data-action="simulate"]').addEventListener('click', () => {
    if (!save) {
      ui.toast('Crie uma carreira para simular e salvar notícias.', 'error', 'lock');
      return;
    }
    simulateBackground(ui.universe, save, 3);
    if (Math.random() < 0.7) {
      const art = makeRumorArticle(ui.universe, save, save.profile.division);
      if (art) addNews(save, art);
    }
    persist(save, true);
    ui.toast('O universo se movimentou. Novas notícias publicadas.', 'success', 'news');
    render();
  });

  render();
  return el;
}

// TG Shop: gym gear, staff, sponsors, fictitious training boosters and cosmetics.
import { icon } from './icons.js';
import { esc, h, fmtNum, screenHead } from './helpers.js';
import { SHOP_ITEMS, MEDAL_NAMES } from '../core/data.js';
import { addCoins, addMoney, persist } from '../core/store.js';

const CATS = [
  { id: 'all', name: 'Todos' },
  { id: 'gym', name: 'Academia' },
  { id: 'training', name: 'Treino' },
  { id: 'staff', name: 'Treinadores' },
  { id: 'sponsor', name: 'Patrocínio' },
  { id: 'cosmetic', name: 'Cosméticos' },
];

export function shopScreen(ui) {
  const save = ui.save;
  if (!save) {
    return h(`<div class="screen plain">${ui.topbar('shop')}${screenHead({ kicker: 'Economia', title: 'Loja TG', sub: 'Crie uma carreira para comprar equipamentos.' })}<div class="empty-state">${icon('shop', 40)}<b>Loja bloqueada</b><p>Você precisa de uma carreira ativa para gastar TG COIN.</p><button class="btn btn-primary" data-nav="create">Criar carreira</button></div></div>`);
  }
  const c = save.career;
  let cat = 'all';
  const el = h(`<div class="screen">
    ${ui.topbar('shop')}
    ${screenHead({
      kicker: 'Economia virtual', title: 'Loja TG',
      sub: 'Equipamentos reais da academia, treinadores, patrocínios e itens cosméticos. TG COIN é uma moeda 100% virtual, sem valor em dinheiro real.',
      actions: `<span class="chip gold">${icon('coin', 13)} ${fmtNum(c.coins)} TG</span>
        <span class="chip">${icon('coin', 13)} C$ ${fmtNum(c.money)}</span>
        <button class="btn btn-sm btn-gold-outline" data-action="daily">${icon('calendar', 14)} Bônus diário</button>`,
    })}
    <div class="row between" style="margin-bottom:14px">
      <div class="tabs" style="margin:0;border:none">${CATS.map((x) => `<button data-cat="${x.id}" class="${x.id === cat ? 'active' : ''}">${x.name}</button>`).join('')}</div>
      <span class="tiny" data-count></span>
    </div>
    <div class="grid grid-auto" data-grid></div>
    <div class="divider"></div>
    <div class="grid grid-2">
      <div class="notice">${icon('shield', 14)} <b>Proteção de economia:</b> compras são validadas no seu save local, TG COIN não pode ser convertido em dinheiro real e não há compra de moeda com dinheiro real. Itens de treino são fictícios e não representam substâncias reais.</div>
      <div class="notice green">${icon('coin', 14)} <b>Ganhe TG:</b> vitórias, títulos, contratos, conquistas, patrocínios e o bônus diário. Cada luta rende TG COIN de acordo com a bolsa e o hype.</div>
    </div>
  </div>`);

  const grid = el.querySelector('[data-grid]');
  const count = el.querySelector('[data-count]');

  const owned = (item) => (c.gym.equipment || []).includes(item.id) || (item.type === 'sponsor' && c.sponsor === item.id);

  const render = () => {
    const items = SHOP_ITEMS.filter((i) => cat === 'all' || i.type === cat);
    count.textContent = `${items.length} itens`;
    grid.innerHTML = items.map((item) => {
      const has = owned(item);
      const boosterCount = item.type === 'training' ? (c.boosters?.[item.id] || 0) : 0;
      return `<div class="shop-card ${has ? 'owned' : ''}">
        <div class="ico-big">${icon(item.icon, 34)}</div>
        <div class="row between"><span class="tag ${item.type === 'cosmetic' ? 'blue' : item.type === 'sponsor' ? 'green' : 'gold'}">${labelFor(item.type)}</span>${has ? `<span class="tag green">${icon('check', 10)} COMPRADO</span>` : ''}</div>
        <h4>${esc(item.name)}</h4>
        <p>${esc(item.desc)}</p>
        ${item.type === 'training' ? `<span class="tiny">Estoque: ${boosterCount} · uso único por sessão</span>` : ''}
        <div class="price-row">
          <div class="price">${fmtNum(item.price)} <small>C$</small>${item.coins ? `<span class="tiny gold"> + ${item.coins} TG</span>` : ''}</div>
          <button class="btn btn-sm ${has && item.type !== 'training' ? '' : 'btn-primary'}" data-buy="${item.id}" ${has && item.type !== 'training' ? 'disabled' : ''}>
            ${item.type === 'training' ? (boosterCount ? 'Comprar outro' : 'Comprar') : has ? 'Adquirido' : 'Comprar'}
          </button>
        </div>
      </div>`;
    }).join('');
    grid.querySelectorAll('[data-buy]').forEach((btn) => btn.addEventListener('click', () => buy(btn.dataset.buy)));
  };

  const buy = (id) => {
    const item = SHOP_ITEMS.find((i) => i.id === id);
    if (!item) return;
    if (owned(item) && item.type !== 'training') { ui.toast('Você já possui este item.', 'error', 'check'); return; }
    if (c.money < item.price) { ui.toast('Carteira insuficiente. Vença lutas para ganhar C$.', 'error', 'coin'); return; }
    if (item.coins && c.coins < item.coins) { ui.toast(`TG COIN insuficiente. Faltam ${item.coins - c.coins} TG.`, 'error', 'coin'); return; }
    if (item.type === 'sponsor' && c.sponsor && c.sponsor !== item.id) {
      const current = SHOP_ITEMS.find((i) => i.id === c.sponsor);
      ui.confirm({
        title: 'Trocar patrocínio?', message: `Seu patrocínio atual é <b>${esc(current?.name || 'outro')}</b>. Deseja substituí-lo por <b>${esc(item.name)}</b>?`,
        confirmLabel: 'Trocar', onConfirm: () => executePurchase(item),
      });
      return;
    }
    executePurchase(item);
  };

  const executePurchase = (item) => {
    addMoney(save, -item.price);
    if (item.coins) addCoins(save, -item.coins, 'Compra na loja');
    if (item.type === 'training') {
      c.boosters[item.id] = (c.boosters[item.id] || 0) + 1;
    } else {
      if (!c.gym.equipment.includes(item.id)) c.gym.equipment.push(item.id);
      if (item.type === 'staff') c.gym.coach = item.name;
      if (item.type === 'sponsor') c.sponsor = item.id;
      if (item.id === 'cosmetic_gold') save.profile.appearance.glove = 'glove96';
      if (item.id === 'cosmetic_medal') save.profile.appearance.medal = MEDAL_NAMES[1];
      if (item.id === 'robe_champ') save.profile.appearance.robe = 'robe95';
      const gymItems = c.gym.equipment.filter((x) => SHOP_ITEMS.find((s) => s.id === x)?.type === 'gym').length;
      c.gym.level = Math.min(10, 1 + Math.floor(gymItems * 0.75));
    }
    persist(save, true);
    ui.app.audio.coin();
    ui.toast(`${item.name} adquirido!`, 'success', item.icon);
    render();
    el.querySelector('.userbar')?.remove();
    ui.refresh({ scroll: 'keep' });
  };

  el.querySelectorAll('[data-cat]').forEach((btn) => {
    btn.addEventListener('click', () => {
      cat = btn.dataset.cat;
      el.querySelectorAll('[data-cat]').forEach((b) => b.classList.toggle('active', b === btn));
      render();
    });
  });

  el.querySelector('[data-action="daily"]').addEventListener('click', () => {
    const today = new Date().toISOString().slice(0, 10);
    if (c.lastDaily === today) { ui.toast('Bônus diário já resgatado hoje. Volte amanhã!', 'error', 'calendar'); return; }
    c.lastDaily = today;
    addCoins(save, 75, 'Bônus diário');
    persist(save, true);
    ui.app.audio.coin();
    ui.toast('+75 TG COIN de bônus diário!', 'success', 'coin');
    ui.refresh({ scroll: 'keep' });
  });

  render();
  return el;
}

function labelFor(type) {
  return { gym: 'ACADEMIA', training: 'TREINO FICTÍCIO', staff: 'EQUIPE', sponsor: 'PATROCÍNIO', cosmetic: 'COSMÉTICO' }[type] || 'ITEM';
}

