128:       if (this.slowmoTimer <= 0) this.timeScale = 1;
129:     }
130: 
131:     if (this.phase === 'fight') {
132:       this.updateFight(scaled, inputs);
133:     } else if (this.phase === 'knockdown') {
134:       this.updateKnockdown(scaled, inputs);
135:     } else if (this.phase === 'roundEnd') {
136:       if (this.phaseTime > 3.0) this.nextRound();
137:     } else if (this.phase === 'ko') {
138:       if (this.phaseTime > 4.2) this.finishKo();
139:     }
140:   }
141: 
142:   updateFight(dt, inputs) {
143:     this.clock -= dt;
144:     const p1In = this.normalizeInput(inputs.p1, 'p1');
145:     const p2In = this.normalizeInput(inputs.p2, 'p2');
146:     // AI overrides its slot.
147:     const a0 = this.ai.p1 ? this.ai.p1.think(dt) : null;
148:     const a1 = this.ai.p2 ? this.ai.p2.think(dt) : null;
149:     const in0 = a0 || p1In;
150:     const in1 = a1 || p2In;
151:     this.punchRequests.p1 = in0?.punch || null;
152:     this.punchRequests.p2 = in1?.punch || null;
153:     this.stepFighter(this.fighters[0], in0, this.fighters[1], dt);
154:     this.stepFighter(this.fighters[1], in1, this.fighters[0], dt);
155:     this.separate();
156:     this.updateHeat(dt);
157: 
158:     if (this.clock <= 0) {
159:       this.clock = 0;
160:       this.endRound();
161:     }
162:   }
163: 
164:   normalizeInput(input, slot) {
165:     const base = { moveX: 0, moveZ: 0, block: false, dodge: false, punch: null };
166:     if (!input) return base;
167:     return {
168:       moveX: clamp(input.moveX || 0, -1, 1),
169:       moveZ: clamp(input.moveZ || 0, -1, 1),
170:       block: !!input.block,
171:       dodge: !!input.dodge,
172:       punch: input.punch || null,
173:     };
174:   }
175: 
176:   setRemoteInput(input) {
177:     this.remoteInput = input;
178:     this.remoteInputTime = performance.now();
179:   }
180: 
181:   stepFighter(f, input, opp, dt) {
182:     if (!f || !opp) return;
183:     f.moveX = input.moveX;
184:     f.moveZ = input.moveZ;
185:     f.blocking = input.block && !f.action && !f.dodge.active && f.stun <= 0;
186:     f.expression = f.stun > 0 ? 'hurt' : f.stamina < 25 ? 'tired' : f.action ? 'focused' : 'neutral';
187: 
188:     if (f.stun > 0) {
189:       f.blocking = false;
190:       this.applyMovement(f, opp, 0, 0, dt, true);
191:       return;
192:     }
193: 
194:     // Dodge
195:     if (input.dodge && !f.dodge.active && f.dodge.cooldown <= 0 && f.stamina > 8 && !f.action) {
196:       f.dodge.active = true;
197:       f.dodge.time = 0.36;
198:       f.dodge.dir = Math.abs(input.moveX) > 0.1 ? Math.sign(input.moveX) : (Math.random() < 0.5 ? -1 : 1);
199:       f.dodge.cooldown = 0.9;
200:       f.stamina = Math.max(0, f.stamina - 9);
201:       this.emit('dodge', { id: f.id, dir: f.dodge.dir });
202:     }
203: 
204:     if (f.dodge.active) {
205:       f.blocking = false;
206:       this.applyMovement(f, opp, f.dodge.dir * 1.8, 0, dt, true);
207:       // Grant counter timing in the back half of the dodge.
208:       if (f.dodge.time > 0.05 && f.dodge.time < 0.3) f.counterWindow = Math.max(f.counterWindow, 0.22);
209:       return;
210:     }
211: 
212:     // Start punch
213:     const req = this.punchRequests[f.id];
214:     if (req && PUNCHES[req] && !f.action && f.cooldown <= 0 && !f.blocking) {
215:       this.startPunch(f, opp, req);
216:     }
217: 
218:     // Advance punch
219:     if (f.action) {
220:       const act = f.action;
221:       act.time += dt;
222:       if (!act.resolved && act.time >= act.def.impactAt * act.def.dur) {
223:         act.resolved = true;
224:         this.resolvePunch(f, opp, act);
225:       }
226:       if (act.time >= act.def.dur) {
227:         f.action = null;
228:         f.cooldown = 0.08;
229:       }
230:       this.applyMovement(f, opp, input.moveX * 0.22, input.moveZ * 0.22, dt, false);
231:       return;
232:     }
233: 
234:     // Movement and stamina
235:     if (!f.blocking) {
236:       this.applyMovement(f, opp, input.moveX, input.moveZ, dt, false);
237:     } else {
238:       this.applyMovement(f, opp, input.moveX * 0.3, input.moveZ * 0.3, dt, false);
239:       f.blockingTime += dt;
240:       f.guard = Math.max(0, f.guard - dt * 1.4);
241:       if (f.guard <= 0) {
242:         f.stun = Math.max(f.stun, 1.1);
243:         f.guard = 12;
244:         f.blocking = false;
245:         this.emit('guardBreak', { id: f.id });
246:       }
247:     }
248: 
249:     // Stamina economy
250:     const moving = Math.abs(input.moveX) + Math.abs(input.moveZ) > 0.15;
251:     const cond = attr(f.attributes, 'conditioning', 55);
252:     const regen = (f.blocking ? 2.2 : moving ? 3.6 : 5.4) * (0.7 + cond / 160);
253:     if (!f.action) f.stamina = Math.min(f.maxStamina, f.stamina + regen * dt);
254:     if (!f.blocking) f.guard = Math.min(100, f.guard + dt * 7);
255:     if (f.stamina <= 0.5) f.expression = 'tired';
256: 
257:     // Reset combo
258:     if (this.timeSinceHit(f, opp) > 1.6 && f.combo > 0) f.combo = 0;
259:   }
260: 
261:   applyMovement(f, opp, x, z, dt, locked) {
262:     const dx = opp.pos.x - f.pos.x;
263:     const dz = opp.pos.z - f.pos.z;
264:     const dist = Math.max(0.001, Math.hypot(dx, dz));
265:     const dirx = dx / dist, dirz = dz / dist;
266:     const px = -dirz, pz = dirx;
267:     const mobility = attr(f.attributes, 'mobility', 55);
268:     const style = STYLE_BY_ID[f.style]?.modifiers || {};
269:     const fatigue = f.stamina < 25 ? 0.72 : 1;
270:     let speed = (1.45 + mobility / 100 * 1.0) * (style.speed || 1) * fatigue;
271:     if (locked) speed *= 1.3;
272:     if (f.blocking) speed *= 0.4;
273:     if (f.stun > 0) speed *= 0.2;
274:     f.vx = (dirx * z + px * x) * speed;
275:     f.vz = (dirz * z + pz * x) * speed;
276:     f.pos.x = clamp(f.pos.x + f.vx * dt, -RING_LIMIT, RING_LIMIT);
277:     f.pos.z = clamp(f.pos.z + f.vz * dt, -RING_LIMIT, RING_LIMIT);
278:     f.stats.distance += Math.hypot(f.vx * dt, f.vz * dt);
279:     const ndx = opp.pos.x - f.pos.x;
280:     const ndz = opp.pos.z - f.pos.z;
281:     f.facing = Math.atan2(ndx, ndz);
282:     f.distance = Math.hypot(ndx, ndz);
283:   }
284: 
285:   separate() {
286:     const [a, b] = this.fighters;
287:     const dx = b.pos.x - a.pos.x;
288:     const dz = b.pos.z - a.pos.z;
289:     const dist = Math.max(0.0001, Math.hypot(dx, dz));
290:     const min = 0.78;
291:     if (dist < min) {
292:       const push = (min - dist) / 2;
293:       const nx = dx / dist, nz = dz / dist;
294:       a.pos.x = clamp(a.pos.x - nx * push, -RING_LIMIT, RING_LIMIT);
295:       a.pos.z = clamp(a.pos.z - nz * push, -RING_LIMIT, RING_LIMIT);
296:       b.pos.x = clamp(b.pos.x + nx * push, -RING_LIMIT, RING_LIMIT);
297:       b.pos.z = clamp(b.pos.z + nz * push, -RING_LIMIT, RING_LIMIT);
298:     }
299:     a.facing = Math.atan2(b.pos.x - a.pos.x, b.pos.z - a.pos.z);
300:     b.facing = Math.atan2(a.pos.x - b.pos.x, a.pos.z - b.pos.z);
301:   }
302: 
303:   startPunch(f, opp, type) {
304:     const def = PUNCHES[type];
305:     if (!def || f.stamina < def.stamina * 0.6) return false;
306:     f.action = { type, def, time: 0, resolved: false, counter: f.counterWindow > 0 };
307:     f.stamina = Math.max(0, f.stamina - def.stamina);
308:     f.stats.thrown++;
309:     if (def.hand === 'L') f.stats.jabs++;
310:     else f.stats.power++;
311:     f.counterWindow = 0;
312:     this.emit('punch', { id: f.id, type, counter: f.action.counter });
313:     return true;
314:   }
315: 
316:   resolvePunch(attacker, defender, act) {
317:     const def = act.def;
318:     const dist = attacker.distance || Math.hypot(defender.pos.x - attacker.pos.x, defender.pos.z - attacker.pos.z);
319:     const reachBonus = (attr(attacker.attributes, 'mobility', 50) - 50) * 0.001;
320:     const maxRange = 1.48 + def.range + reachBonus + (attacker.attributes && attacker.attributes.reach ? 0 : 0);
321:     const stats = attacker.stats;
322:     const style = STYLE_BY_ID[attacker.style]?.modifiers || {};
323:     if (dist > maxRange) {
324:       this.emit('whiff', { id: attacker.id, type: act.type });
325:       return;
326:     }
327:     // Defensive states
328:     if (defender.dodge.active) {
329:       defender.stats.dodges++;
330:       defender.counterWindow = Math.max(defender.counterWindow, 0.65);
331:       attacker.stun = Math.max(attacker.stun, 0.22);
332:       attacker.combo = 0;
333:       this.emit('dodgeSuccess', { id: defender.id, attacker: attacker.id, type: act.type });
334:       return;
335:     }
336:     const precision = attr(attacker.attributes, 'precision', 55);
337:     const reflexes = attr(defender.attributes, 'reflexes', 55);
338:     const staminaPenalty = attacker.stamina < 20 ? 0.18 : 0;
339:     let hitChance = 0.70 + def.accuracy + (precision - reflexes) / 240 - staminaPenalty + (act.counter ? 0.16 : 0) + (defender.stun > 0 ? 0.2 : 0);
340:     if (defender.blocking) hitChance += 0.16;
341:     if (Math.random() > clamp(hitChance, 0.28, 0.97)) {
342:       attacker.combo = 0;
343:       this.emit('whiff', { id: attacker.id, type: act.type });
344:       return;
345:     }
346:     const strength = attr(attacker.attributes, 'strength', 55);
347:     const staminaFactor = clamp(0.55 + attacker.stamina / 110, 0.55, 1.15);
348:     let damage = def.damage * (0.72 + strength / 100 * 0.65) * staminaFactor * (0.9 + Math.random() * 0.2);
349:     damage *= style.power || 1;
350:     if (act.counter) damage *= 1.28;
351:     if (attacker.combo > 0) damage *= 1 + Math.min(0.24, attacker.combo * 0.035);
352:     if (defender.stun > 0) damage *= 1.2;
353:     const defense = attr(defender.attributes, 'defense', 55);
354:     damage *= 1 - clamp(defense / 100 * 0.34, 0, 0.38);
355: 
356:     const crit = Math.random() < 0.055 + precision / 1400;
357:     if (crit) damage *= 1.35;
358: 
359:     const target = Math.random() < 0.68 ? 'head' : 'body';
360:     defender.hurtFlash = 0.25;
361:     defender.combo = 0;
362:     attacker.lastHitAt = this.phaseTime;
363: 
364:     if (defender.blocking) {
365:       defender.stats.blocks++;
366:       const guardDmg = def.guardBreak * (0.72 + strength / 160);
367:       defender.guard = Math.max(0, defender.guard - guardDmg);
368:       const chip = damage * 0.17;
369:       defender.hp = Math.max(0, defender.hp - chip);
370:       defender.hurtFlash = 0.12;
371:       this.emit('block', { attacker: attacker.id, defender: defender.id, type: act.type, guard: defender.guard, damage: chip });
372:       if (defender.guard <= 0) {
373:         defender.stun = Math.max(defender.stun, 1.2);
374:         defender.blocking = false;
375:         defender.guard = 15;
376:         this.emit('guardBreak', { id: defender.id });
377:       }
378:       return;
379:     }
380: 
381:     damage = Math.max(1, Math.round(damage * 10) / 10);
382:     defender.hp = Math.max(0, defender.hp - damage);
383:     defender.stun = Math.max(defender.stun, def.stun * (0.8 + strength / 220));
384:     defender.stats.damage += damage;
385:     attacker.stats.landed++;
386:     attacker.stats.damage += damage;
387:     attacker.combo++;
388:     attacker.stats.maxCombo = Math.max(attacker.stats.maxCombo, attacker.combo);
389:     this.roundDamage[attacker.id === 'p1' ? 0 : 1] += damage;
390:     defender.roundDamage += damage;
391:     if (act.counter) attacker.stats.counters++;
392:     this.heat = Math.min(1, this.heat + 0.08 + damage / 80);
393:     this.emit(crit ? 'critical' : 'hit', {
394:       attacker: attacker.id, defender: defender.id, type: act.type, damage, crit,
395:       hp: defender.hp, stamina: defender.stamina, target,
396:     });
397:     if (defender.hp <= 0) {
398:       this.knockdown(defender, attacker);
399:     }
400:   }
401: 
402:   timeSinceHit(a, b) {
403:     return this.phaseTime - (a.lastHitAt || 0);
404:   }
405: 
406:   knockdown(fighter, opponent) {
407:     if (this.phase !== 'fight') return;
408:     fighter.knockdowns++;
409:     fighter.action = null;
410:     fighter.blocking = false;
411:     fighter.dodge.active = false;
412:     fighter.combo = 0;
413:     this.phase = 'knockdown';
414:     this.phaseTime = 0;
415:     this.down = {
416:       fighter, opponent, time: 0, count: 0, resolved: false, recovered: false,
417:       fallProgress: 0, taps: 0, playerCanTap: fighter.isPlayer || this.config.mode === 'multiplayer' && fighter.id === 'p2',
418:       maxKnockdowns: fighter.knockdowns >= 3,
419:     };
420:     opponent.stats.knockdowns = (opponent.stats.knockdowns || 0) + 1;
421:     this.emit('knockdown', { id: fighter.id, opponent: opponent.id, knockdowns: fighter.knockdowns, tko: this.down.maxKnockdowns });
422:     this.timeScale = this.down.maxKnockdowns ? 0.5 : 0.62;
423:     this.slowmoTimer = 1.4;
424:   }
425: 
426:   updateKnockdown(dt, inputs) {
427:     const d = this.down;
428:     if (!d) return;
429:     d.time += dt;
430:     d.fallProgress = Math.min(1, d.time / 0.9);
431:     if (d.playerCanTap && inputs) {
432:       const inBox = d.fighter.id === 'p1' ? inputs.p1 : inputs.p2;
433:       if (inBox?.getUp) d.taps++;
434:       if (this.remoteInput?.getUp && d.fighter.id === 'p2') d.taps++;
435:     }
436:     const count = Math.min(10, Math.floor(d.time / 0.55) + 1);
437:     if (count !== d.count) {
438:       d.count = count;
439:       this.emit('count', { count, id: d.fighter.id });
440:       if (count === 8 && !d.resolved) {
441:         d.resolved = true;
442:         const recovery = attr(d.fighter.attributes, 'recovery', 55);
443:         let chance = 0.36 + recovery / 240 - d.fighter.knockdowns * 0.11;
444:         chance += Math.min(0.28, d.taps * 0.06);
445:         if (d.maxKnockdowns) chance = 0;
446:         d.recovered = Math.random() < clamp(chance, 0, 0.78);
447:         if (d.recovered) {
448:           d.fighter.hp = Math.round(d.fighter.maxHp * 0.30);
449:           d.fighter.stamina = Math.max(30, d.fighter.stamina);
450:           d.fighter.stun = 0.8;
451:           d.fighter.guard = 45;
452:           d.opponent.stamina = Math.max(0, d.opponent.stamina - 6);
453:           this.emit('getUp', { id: d.fighter.id, taps: d.taps });
454:         }
455:       }
456:     }
457:     if ((d.resolved && !d.recovered && count >= 9) || count >= 10) {
458:       const isTko = d.fighter.knockdowns >= 3 || d.opponent.stats.landed - d.opponent.stats.blocks > 0 && d.maxKnockdowns;
459:       this.endFight({
460:         winnerId: d.opponent.id,
461:         loserId: d.fighter.id,
462:         method: isTko ? 'TKO' : 'KO',
463:         round: this.round,
464:         time: Math.max(0, this.clock),
465:       });
466:       this.phase = 'ko';
467:       this.phaseTime = 0;
468:       this.timeScale = 0.5;
469:       this.emit('ko', { winner: d.opponent.id, loser: d.fighter.id, method: isTko ? 'TKO' : 'KO' });
470:       return;
471:     }
472:     if (d.recovered && d.time > 6.0) {
473:       this.phase = 'fight';
474:       this.phaseTime = 0;
475:       this.clock = Math.max(6, this.clock);
476:       this.timeScale = 1;
477:       this.down = null;
478:       this.emit('bell');
479:       this.emit('resume', {});
480:     }
481:   }
482: 
483:   endRound() {
484:     if (this.phase !== 'fight') return;
485:     this.phase = 'roundEnd';
486:     this.phaseTime = 0;
487:     this.emit('bell');
488:     // Judges score the round
489:     const [a, b] = this.fighters;
490:     const dmgA = this.roundDamage[0] + a.knockdowns * 8;
491:     const dmgB = this.roundDamage[1] + b.knockdowns * 8;
492:     for (const j of this.judges) {
493:       let winner = dmgA === dmgB ? 0 : dmgA > dmgB ? 1 : -1;
494:       if (winner !== 0 && Math.random() < Math.abs(j.bias)) winner *= -1;
495:       let scoreA = 10, scoreB = 10;
496:       if (winner === 1) scoreB = 9;
497:       if (winner === -1) scoreA = 9;
498:       if (winner !== 0 && Math.random() < 0.04) { scoreA = 10; scoreB = 10; winner = 0; }
499:       const knocked = winner === 1 ? (b.knockdowns > 0) : (a.knockdowns > 0);
500:       if (knocked && winner !== 0) scoreB = winner === 1 ? 8 : scoreB;
501:       if (knocked && winner === -1) scoreA = 8;
502:       j.scores[0] += scoreA;
503:       j.scores[1] += scoreB;
504:       j.rounds.push({ round: this.round, a: scoreA, b: scoreB, winner });
505:     }
506:     a.scorecards.push({ round: this.round, dmg: dmgA });
507:     b.scorecards.push({ round: this.round, dmg: dmgB });
508:     this.emit('roundEnd', { round: this.round, damage: [...this.roundDamage], scores: this.judges.map((j) => [...j.scores]) });
509:     // Recovery between rounds
510:     for (const f of this.fighters) {
511:       const rec = attr(f.attributes, 'recovery', 55);
512:       f.hp = Math.min(f.maxHp, f.hp + 5 + rec * 0.075);
513:       f.stamina = Math.min(f.maxStamina, f.stamina + 18 + rec * 0.24);
514:       f.guard = Math.min(100, f.guard + 35);
515:       f.stun = 0;
516:       f.combo = 0;
517:       f.knockdowns = Math.max(0, f.knockdowns);
518:     }
519:     this.roundDamage = [0, 0];
520:   }
521: 
522:   nextRound() {
523:     if (this.round >= this.config.rounds) {
524:       this.decision();
525:       return;
526:     }
527:     this.round++;
528:     this.phase = 'fight';
529:     this.phaseTime = 0;
530:     this.clock = this.config.roundTime;
531:     this.timeScale = 1;
532:     this.emit('roundStart', { round: this.round });
533:     this.emit('bell');
534:   }
535: 
536:   decision() {
537:     const [a, b] = this.fighters;
538:     const totals = this.judges.map((j) => ({ a: j.scores[0], b: j.scores[1] }));
539:     let aWins = 0, bWins = 0, draws = 0;
540:     for (const t of totals) {
541:       if (t.a > t.b) aWins++;
542:       else if (t.b > t.a) bWins++;
543:       else draws++;
544:     }
545:     let winnerId = null;
546:     let method = 'DEC';
547:     if (aWins > bWins) winnerId = 'p1';
548:     else if (bWins > aWins) winnerId = 'p2';
549:     else {
550:       // Tiebreak by damage + knockdowns
551:       const scoreA = a.stats.damage + a.knockdowns * 12 + a.stats.landed * 0.5;
552:       const scoreB = b.stats.damage + b.knockdowns * 12 + b.stats.landed * 0.5;
553:       if (Math.abs(scoreA - scoreB) < 2) method = 'DRAW';
554:       else winnerId = scoreA > scoreB ? 'p1' : 'p2';
555:     }
556:     const unanimous = method === 'DEC' && (aWins === 3 || bWins === 3);
557:     this.endFight({
558:       winnerId,
559:       loserId: winnerId ? (winnerId === 'p1' ? 'p2' : 'p1') : null,
560:       method: method === 'DRAW' ? 'DRAW' : 'DEC',
561:       decisionType: unanimous ? 'UNÂNIME' : 'DIVISÃO',
562:       round: this.config.rounds,
563:       time: 0,
564:       scorecards: totals,
565:     });
566:     this.emit('decision', { result: this.result });
567:   }
568: 
569:   finishKo() {
570:     if (this.result) {
571:       this.phase = 'end';
572:       this.timeScale = 1;
573:       this.finished = true;
574:       this.emit('end', this.result);
575:     }
576:   }
577: 
578:   endFight(result) {
579:     if (this.result) return;
580:     const winner = this.fighters.find((f) => f.id === result.winnerId);
581:     const loser = this.fighters.find((f) => f.id === result.loserId);
582:     const totalA = this.judges.reduce((s, j) => s + j.scores[0], 0);
583:     const totalB = this.judges.reduce((s, j) => s + j.scores[1], 0);
584:     this.result = {
585:       ...result,
586:       rounds: this.config.rounds,
587:       stats: {
588:         p1: { ...this.fighters[0].stats, hp: this.fighters[0].hp, maxHp: this.fighters[0].maxHp },
589:         p2: { ...this.fighters[1].stats, hp: this.fighters[1].hp, maxHp: this.fighters[1].maxHp },
590:       },
591:       totals: { p1: totalA, p2: totalB },
