735:   think(dt) {
736:     const me = this.me();
737:     const opp = this.opp();
738:     const input = this.input;
739:     input.punch = null;
740:     input.dodge = false;
741:     input.getUp = false;
742:     if (this.engine.phase === 'knockdown' && this.engine.down?.fighter === me) {
743:       input.getUp = Math.random() < this.skill * 0.7;
744:       return null;
745:     }
746:     if (this.engine.phase !== 'fight') return null;
747:     this.timer -= dt;
748:     this.blockTimer = Math.max(0, this.blockTimer - dt);
749:     this.dodgeTimer = Math.max(0, this.dodgeTimer - dt);
750:     const dist = me.distance || Math.hypot(opp.pos.x - me.pos.x, opp.pos.z - me.pos.z);
751:     const oppAttacking = !!opp.action;
752:     const myStamina = me.stamina;
753:     const oppHp = opp.hp / opp.maxHp;
754:     const myHp = me.hp / me.maxHp;
755: 
756:     // Reactive defence (reaction speed increases with difficulty/reflexes).
757:     const reaction = this.skill * (0.5 + (me.attributes.reflexes || 50) / 180);
758:     if (oppAttacking && Math.random() < reaction * 0.5 * dt * 18 && this.dodgeTimer <= 0) {
759:       const styleDodge = this.style === 'counter' || this.style === 'defensive' || this.style === 'speed';
760:       if (Math.random() < (styleDodge ? 0.55 : 0.3) && me.dodge.cooldown <= 0 && myStamina > 18) {
761:         input.dodge = true;
762:         this.dodgeTimer = 0.5;
763:         input.moveX = Math.random() < 0.5 ? -1 : 1;
764:         return null;
765:       }
766:       if (Math.random() < (styleDodge ? 0.5 : 0.66) && myStamina > 10) {
767:         this.blockTimer = 0.22 + Math.random() * 0.3;
768:       }
769:     }
770:     input.block = this.blockTimer > 0 && myStamina > 4;
771:     input.moveX = 0;
772:     input.moveZ = 0;
773: 
774:     if (myStamina < 16 && !input.block) {
775:       // Rest: circle away and guard.
776:       input.moveZ = -0.55;
777:       input.moveX = Math.sin(this.engine.phaseTime * 0.7) * 0.7;
778:       if (dist < 1.6) input.block = Math.random() < 0.5;
779:       if (dist > 2.3) input.moveZ = 0;
780:       return input;
781:     }
782: 
783:     // Range management based on style.
784:     const preferred = this.style === 'technical' ? 1.75 : this.style === 'counter' ? 1.8 : this.style === 'speed' ? 1.5 : this.style === 'defensive' ? 1.95 : 1.45;
785:     if (dist > preferred + 0.15) {
786:       input.moveZ = 0.55 + this.aggression * 0.45;
787:       input.moveX = Math.sin(this.engine.phaseTime * 0.9 + this.personality) * 0.3;
788:     } else if (dist < preferred - 0.22) {
789:       input.moveZ = -0.35 - (this.style === 'aggressive' ? -0.1 : 0.2);
790:       input.moveX = Math.sin(this.engine.phaseTime * 1.1) * 0.4;
791:     } else {
792:       input.moveX = Math.sin(this.engine.phaseTime * 0.55 + this.personality * 6) * 0.45;
793:     }
794: 
795:     // Combo plan
796:     if (this.punchPlan.length && this.timer <= 0) {
797:       input.punch = this.punchPlan.shift();
798:       this.timer = 0.16 + Math.random() * 0.2 + (1 - this.skill) * 0.2;
799:       return input;
800:     }
801: 
802:     if (this.timer <= 0) {
803:       const hurtOpp = oppHp < 0.35;
804:       const aggression = this.aggression * (0.8 + this.skill * 0.35) * (hurtOpp ? 1.3 : 1) * (myHp < 0.3 ? 0.8 : 1);
805:       this.timer = 0.3 + Math.random() * (0.6 - aggression * 0.3);
806:       if (dist < 2.1 && myStamina > 18 && Math.random() < aggression) {
807:         const roll = Math.random();
808:         let punch;
809:         if (dist > 1.85) punch = roll < 0.7 ? 'jab' : 'cross';
810:         else if (dist > 1.5) punch = roll < 0.4 ? 'jab' : roll < 0.7 ? 'cross' : 'hook';
811:         else punch = roll < 0.25 ? 'jab' : roll < 0.5 ? 'hook' : roll < 0.8 ? 'uppercut' : 'body';
812:         if (opp.blocking && Math.random() < 0.45) punch = 'body';
813:         if (opp.stun > 0) punch = 'uppercut';
814:         input.punch = punch;
815:         // Follow-up plan
816:         const chance = this.skill * (this.style === 'aggressive' || this.style === 'pressure' ? 0.7 : 0.45);
817:         if (Math.random() < chance) {
818:           this.punchPlan = [Math.random() < 0.5 ? 'cross' : 'hook'];
819:           if (this.style === 'pressure' && Math.random() < 0.4) this.punchPlan.push('body');
820:         }
821:         this.timer = 0.18 + Math.random() * 0.3;
822:       } else if (dist < 1.6 && myStamina > 25 && Math.random() < 0.3) {
823:         input.punch = 'uppercut';
824:         this.timer = 0.4;
825:       } else if (Math.random() < 0.25) {
826:         // reset / feint
827:         input.dodge = Math.random() < 0.2 && myStamina > 20;
828:       }
829:     }
830:     // Cornered escape
831:     if (Math.abs(me.pos.x) > 2.15 || Math.abs(me.pos.z) > 2.15) {
832:       input.moveX = -Math.sign(me.pos.x || 1) * 0.9;
833:       input.moveZ = -Math.sign(me.pos.z || 1) * 0.5;
834:     }
835:     return input;
836:   }
