152:     spark.max = 0.28;
153:     spark.size = clamp(0.35 + damage / 26, 0.35, 1.25) * (crit ? 1.4 : 1);
154:     spark.sprite.position.copy(pos);
155:     spark.sprite.material.color.set(color || (crit ? '#ffe9a3' : '#ffc27a'));
156:     spark.sprite.material.opacity = 1;
157:     spark.sprite.scale.setScalar(spark.size * 0.6);
158:     spark.crit = crit;
159:     this.impactRing.position.copy(pos);
160:     this.impactRing.position.z += 0.01;
161:     this.impactRing.material.color.set(color || '#fff0b0');
162:     this.impactRing.material.opacity = 0.9;
163:     this.impactRingLife = 0.2;
164:     this.impactRing.scale.setScalar(1);
165:     // opponent flinch offset
