174:       this.sweat.cursor = (this.sweat.cursor + 1) % this.sweatCount;
175:       this.sweat.pos[idx * 3] = origin.x + (Math.random() - 0.5) * 0.2;
176:       this.sweat.pos[idx * 3 + 1] = origin.y + (Math.random() - 0.5) * 0.2;
177:       this.sweat.pos[idx * 3 + 2] = origin.z + (Math.random() - 0.5) * 0.2;
178:       this.sweat.vel[idx * 3] = (Math.random() - 0.5) * 1.8 + dir * 0.4;
179:       this.sweat.vel[idx * 3 + 1] = 0.8 + Math.random() * 1.8;
180:       this.sweat.vel[idx * 3 + 2] = (Math.random() - 0.5) * 1.8;
