189:     this.boxers[0].root.position.copy(this.entrancePos[0]);
190:     this.boxers[1].root.position.copy(this.entrancePos[1]);
191:     this.boxers[0].root.rotation.y = Math.PI * 0.8;
192:     this.boxers[1].root.rotation.y = -Math.PI * 0.2;
193:     this.boxers[0].update(0.016, { entrance: true, robe: true });
