203:   update(dt, { paused = false } = {}) {
204:     if (this.hitstop > 0) {
205:       this.hitstop = Math.max(0, this.hitstop - dt);
206:       dt *= 0.15;
207:     }
208:     this.time += dt;
209:     this.heat = damp(this.heat, this.engine.heat || 0.25, 1.2, dt);
210:     this.shake = Math.max(0, this.shake - dt * 2.4);
211:     this.flash = Math.max(0, this.flash - dt * 3.2);
212: 
213:     if (this.replay) {
214:       this.updateReplay(dt);
215:       this.updateParticles(dt);
216:       this.updateConfetti(dt);
217:       this.arena.update(dt, this.heat);
218:       return;
219:     }
220: 
221:     if (this.entrance) {
222:       this.entrance.t += dt;
223:       const p = clamp(this.entrance.t / this.entrance.dur, 0, 1);
224:       const ease = p * p * (3 - 2 * p);
225:       const start0 = new THREE.Vector3(-0.06 * VISUAL_SCALE, 0, (1.62 / 2) * VISUAL_SCALE);
226:       const start1 = new THREE.Vector3(0.06 * VISUAL_SCALE, 0, -(1.62 / 2) * VISUAL_SCALE);
227:       this.boxers[0].root.position.lerpVectors(this.entrancePos[0], start0, ease);
228:       this.boxers[1].root.position.lerpVectors(this.entrancePos[1], start1, ease);
229:       this.boxers[0].root.rotation.y = lerp(Math.PI * 0.8, Math.PI, ease);
230:       this.boxers[1].root.rotation.y = lerp(-Math.PI * 0.2, 0, ease);
231:       for (const [i, b] of this.boxers.entries()) {
232:         b.update(dt, { entrance: p < 0.9, robe: true, moveZ: 1, moveX: 0, stamina: 100 });
233:       }
234:       this.updateStaff(dt);
235:       this.updateCamera(dt, false, true);
236:       this.arena.update(dt, 0.6);
237:       this.updateParticles(dt);
238:       if (p >= 1 && !this._entranceDone) {
239:         this._entranceDone = true;
240:         this.onEntranceDone?.();
241:       }
242:       return;
243:     }
244: 
245:     this.syncFighters(dt);
246:     this.updateStaff(dt);
247:     this.updateCamera(dt);
248:     this.arena.update(dt, Math.min(1, this.heat + (this.engine.phase === 'knockdown' ? 0.35 : 0)));
249:     this.updateParticles(dt);
250:     this.updateConfetti(dt);
251:     this.recordFrame(dt);
252:     if (this.engine.result && this.engine.phase === 'end' && !this.resultAt) this.resultAt = this.time;
253:     if (this.engine.result && !this.beltGroup) this.maybeCelebrate();
254:   }
