256:   syncFighters(dt) {
257:     const [f1, f2] = this.engine.fighters;
258:     const fighting = this.engine.phase !== 'intro';
259:     for (const [i, f] of [f1, f2].entries()) {
260:       const b = this.boxers[i];
261:       if (!f || !b) continue;
262:       const x = f.pos.x * VISUAL_SCALE;
263:       const z = f.pos.z * VISUAL_SCALE;
264:       b.root.position.x = damp(b.root.position.x, x, 20, dt);
265:       b.root.position.z = damp(b.root.position.z, z, 20, dt);
266:       b.root.position.y = 0.012;
267:       b.root.rotation.y = f.facing;
268:       const down = this.engine.phase === 'knockdown' && this.engine.down?.fighter?.id === f.id;
269:       const downKo = (this.engine.phase === 'ko' || this.engine.phase === 'end') && this.engine.result?.loserId === f.id && ['KO', 'TKO'].includes(this.engine.result.method);
270:       const state = {
271:         moveX: f.moveX || 0,
272:         moveZ: f.moveZ || 0,
273:         blocking: f.blocking,
274:         dodging: f.dodge.active,
275:         dodgeDir: f.dodge.dir,
276:         action: f.action?.type || null,
277:         actionTime: f.action?.time || 0,
278:         actionDur: f.action?.def?.dur || 0,
279:         stun: f.stun,
280:         stamina: f.stamina,
281:         hp: f.hp,
282:         knockedDown: down || downKo,
283:         fallProgress: down ? this.engine.down?.fallProgress || 1 : downKo ? 1 : 0,
284:         victory: !!(this.engine.result && this.engine.result.winnerId === f.id && this.engine.phase === 'end'),
285:         defeated: downKo || !!(this.engine.result && this.engine.result.loserId === f.id && this.engine.phase === 'end' && !['KO', 'TKO'].includes(this.engine.result.method)),
286:         robe: false,
287:       };
288:       const wasBlocking = b._blocking;
289:       b.update(dt, state);
290:       b._blocking = f.blocking;
291:       if (b.shadow) {
292:         b.shadow.material.opacity = down || downKo ? 0.2 : 0.32;
293:       }
294:       if (this.engine.result && this.engine.phase === 'end' && this.engine.result.winnerId === f.id) {
295:         b.setExpression('happy');
296:       } else if (f.stun > 0.1) b.setExpression('hurt');
297:       else if (f.stamina < 24) b.setExpression('tired');
298:       else if (f.action) b.setExpression('focused');
299:       else b.setExpression('neutral');
300:     }
301:   }
