303:   updateStaff(dt) {
304:     const ref = this.arena.referee;
305:     if (!ref) return;
306:     const e = this.engine;
307:     let targetX = 0.0, targetZ = -2.3;
308:     let rotation = 0;
309:     if (e.phase === 'knockdown' && e.down) {
310:       const f = e.fighters.find((x) => x.id === e.down.fighter.id);
311:       if (f) {
312:         targetX = f.pos.x * VISUAL_SCALE + 0.65;
313:         targetZ = f.pos.z * VISUAL_SCALE + 0.55;
314:         rotation = Math.atan2(-(f.pos.x * VISUAL_SCALE - targetX), -(f.pos.z * VISUAL_SCALE - targetZ));
315:         // wave down
316:         ref.setExpression('focused');
317:       }
318:     } else if (e.phase === 'end' && e.result?.winnerId) {
319:       const w = e.fighters.find((f) => f.id === e.result.winnerId);
320:       if (w) {
321:         targetX = w.pos.x * VISUAL_SCALE + 0.65;
322:         targetZ = w.pos.z * VISUAL_SCALE + 0.35;
323:         rotation = Math.atan2(-(w.pos.x * VISUAL_SCALE - targetX), -(w.pos.z * VISUAL_SCALE - targetZ));
324:         ref.setExpression('happy');
325:       }
326:     } else {
327:       targetX = Math.sin(this.time * 0.2) * 0.6;
328:       targetZ = -2.35;
329:       rotation = 0;
330:     }
331:     ref.root.position.x = damp(ref.root.position.x, targetX, 2.2, dt);
332:     ref.root.position.z = damp(ref.root.position.z, targetZ, 2.2, dt);
333:     ref.root.rotation.y = damp(ref.root.rotation.y, rotation, 3, dt);
334:     const knee = e.phase === 'knockdown' ? 0.9 : 0.15;
335:     ref.update(dt, { stamina: 90, stance: knee, blocking: false });
336:     for (const s of this.arena.staff) {
337:       if (s === ref) continue;
338:       s.update(dt, { stamina: 95, idle: true });
339:     }
340:   }
