342:   updateCamera(dt, forced = false, entrance = false) {
343:     const e = this.engine;
344:     const aspect = this.camera.aspect;
345:     const mobileFactor = aspect < 1 ? 1.26 : 1;
346:     const [f1, f2] = e.fighters;
347:     const mid = new THREE.Vector3(
348:       ((f1.pos.x + f2.pos.x) / 2) * VISUAL_SCALE,
349:       1.08,
350:       ((f1.pos.z + f2.pos.z) / 2) * VISUAL_SCALE,
351:     );
352:     let desiredPos;
353:     let desiredLook;
354:     if (entrance) {
355:       const p = clamp((this.entrance?.t || 0) / (this.entrance?.dur || 3), 0, 1);
356:       const ease = p * p * (3 - 2 * p);
357:       desiredPos = new THREE.Vector3(lerp(-3.6, 3.1, ease), lerp(0.65, 2.0, ease), lerp(6.0, 5.0, ease));
358:       desiredLook = new THREE.Vector3(lerp(1.6, 0, ease), lerp(0.75, 1.1, ease), 0.2);
359:     } else if (e.phase === 'knockdown' && e.down) {
360:       const f = e.fighters.find((x) => x.id === e.down.fighter.id) || f1;
361:       const x = f.pos.x * VISUAL_SCALE;
362:       const z = f.pos.z * VISUAL_SCALE;
363:       desiredPos = new THREE.Vector3(x + 1.55 * mobileFactor, 0.82, z + 1.85 * mobileFactor);
364:       desiredLook = new THREE.Vector3(x, 0.5, z);
365:     } else if (e.phase === 'ko' && e.result) {
366:       const loser = e.fighters.find((f) => f.id === e.result.loserId) || f2;
367:       const winner = e.fighters.find((f) => f.id === e.result.winnerId) || f1;
368:       const x = loser.pos.x * VISUAL_SCALE;
369:       const z = loser.pos.z * VISUAL_SCALE;
370:       const t = clamp((e.phaseTime || 0) / 4, 0, 1);
371:       desiredPos = new THREE.Vector3(x + 2.0 * mobileFactor, 0.8 + t * 0.4, z + 1.9 * mobileFactor);
372:       desiredLook = new THREE.Vector3(x, 0.42, z);
373:       desiredPos.y += Math.sin(this.time * 0.8) * 0.03;
374:     } else if (e.phase === 'end' && e.result?.winnerId) {
375:       const w = e.fighters.find((f) => f.id === e.result.winnerId) || f1;
376:       const x = w.pos.x * VISUAL_SCALE;
377:       const z = w.pos.z * VISUAL_SCALE;
378:       desiredPos = new THREE.Vector3(x + 1.55 * mobileFactor, 1.5, z + 2.15 * mobileFactor);
379:       desiredLook = new THREE.Vector3(x, 1.15, z);
380:       if (this.beltGroup) {
381:         desiredLook.set(0, 1.2, 0);
382:         desiredPos.set(1.1, 1.8, 3.4);
383:       }
384:     } else {
385:       const dist = Math.abs(f1.pos.z - f2.pos.z) + Math.abs(f1.pos.x - f2.pos.x);
386:       const zoom = clamp(dist * 0.16, 0, 0.45);
387:       desiredPos = new THREE.Vector3(
388:         mid.x + (2.85 + zoom) * mobileFactor,
389:         1.95 + (mobileFactor - 1) * 0.8,
390:         mid.z + (4.6 + zoom * 2.2) * mobileFactor,
391:       );
392:       desiredLook = new THREE.Vector3(mid.x, 1.05, mid.z);
393:       // subtle orbit with the action
394:       desiredPos.x += Math.sin(this.time * 0.22) * 0.12;
395:       desiredPos.y += Math.sin(this.time * 0.35) * 0.04;
396:     }
397:     const lambda = entrance ? 2.4 : forced ? 100 : (e.phase === 'knockdown' || e.phase === 'ko' ? 2.0 : 3.4);
398:     this.camera.position.x = damp(this.camera.position.x, desiredPos.x, lambda, dt);
399:     this.camera.position.y = damp(this.camera.position.y, desiredPos.y, lambda, dt);
400:     this.camera.position.z = damp(this.camera.position.z, desiredPos.z, lambda, dt);
401:     this.cameraTarget.x = damp(this.cameraTarget.x, desiredLook.x, lambda, dt);
402:     this.cameraTarget.y = damp(this.cameraTarget.y, desiredLook.y, lambda, dt);
403:     this.cameraTarget.z = damp(this.cameraTarget.z, desiredLook.z, lambda, dt);
404:     if (this.shake > 0.01) {
405:       const s = this.shake * 0.12;
406:       this.camera.position.x += (Math.random() - 0.5) * s;
407:       this.camera.position.y += (Math.random() - 0.5) * s;
408:       this.camera.position.z += (Math.random() - 0.5) * s * 0.5;
409:     }
410:     this.camera.lookAt(this.cameraTarget);
411:   }
412: 
413:   renderCamera(dt) {
414:     if (this.replay) {
415:       // camera handled by replay frames
416:       return;
417:     }
418:     if (this.shake > 0.01) { /* handled in updateCamera */ }
419:     this.camera.lookAt(this.cameraTarget);
420:   }
