422:   updateParticles(dt) {
423:     for (const spark of this.sparks) {
424:       if (spark.life <= 0) { spark.sprite.material.opacity = 0; continue; }
425:       spark.life -= dt;
426:       const p = 1 - spark.life / spark.max;
427:       spark.sprite.material.opacity = Math.max(0, 1 - p) * 0.95;
428:       const s = spark.size * (0.55 + p * 1.3);
429:       spark.sprite.scale.setScalar(s);
430:     }
431:     if (this.impactRingLife > 0) {
432:       this.impactRingLife -= dt;
433:       const p = 1 - this.impactRingLife / 0.2;
434:       this.impactRing.material.opacity = Math.max(0, 1 - p);
435:       this.impactRing.scale.setScalar(1 + p * 3.5);
436:     } else {
437:       this.impactRing.material.opacity = 0;
438:     }
439:     // Sweat
440:     const { pos, vel, life } = this.sweat;
441:     for (let i = 0; i < this.sweatCount; i++) {
442:       if (life[i] <= 0) {
443:         if (pos[i * 3 + 1] > -5) pos[i * 3 + 1] = -10;
444:         continue;
445:       }
446:       life[i] -= dt;
447:       vel[i * 3 + 1] -= 5.5 * dt;
448:       pos[i * 3] += vel[i * 3] * dt;
449:       pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
450:       pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
451:       if (pos[i * 3 + 1] < 0.03) { pos[i * 3 + 1] = 0.03; vel[i * 3 + 1] *= -0.2; vel[i * 3] *= 0.5; }
452:     }
453:     this.sweat.geo.attributes.position.needsUpdate = true;
454:     this.flashSprite.material.opacity = this.flash * 0.65;
455:     this.flashSprite.scale.setScalar(2 + this.flash * 2);
456:     this.flashSprite.material.color.set(this.flash > 0.5 ? '#ffd27a' : '#ff7a4a');
457:     if (this.flinchTimer > 0) this.flinchTimer -= dt;
458:   }
459: 
460:   recordFrame(dt) {
461:     if (this.engine.phase === 'intro' || this.engine.phase === 'roundEnd') return;
462:     this.recordTimer += dt;
463:     if (this.recordTimer < 0.045) return;
464:     this.recordTimer = 0;
465:     const frame = {
466:       t: this.time,
467:       cam: { pos: this.camera.position.toArray(), look: this.cameraTarget.toArray() },
468:       boxers: this.boxers.map((b) => ({
469:         pos: b.root.position.toArray(),
470:         ry: b.root.rotation.y,
471:         state: b.getRenderState(),
472:       })),
473:       heat: this.heat,
474:       phase: this.engine.phase,
475:     };
476:     this.frames.push(frame);
477:     if (this.frames.length > 170) this.frames.shift();
478:   }
479: 
480:   startReplay(seconds = 4, speed = 0.42, onDone = null) {
481:     if (this.frames.length < 4) { onDone?.(); return false; }
482:     const cutoff = this.time - seconds;
483:     const frames = this.frames.filter((f) => f.t >= cutoff);
484:     if (frames.length < 4) { onDone?.(); return false; }
485:     this.replay = { frames, index: 0, elapsed: 0, speed, onDone, duration: seconds };
486:     this._entranceDone = false;
487:     return true;
488:   }
489: 
490:   updateReplay(dt) {
491:     const r = this.replay;
492:     if (!r) return;
493:     r.elapsed += dt;
494:     const frames = r.frames;
495:     const tStart = frames[0].t;
496:     const targetT = tStart + r.elapsed * r.speed;
497:     let i = r.index;
498:     while (i < frames.length - 1 && frames[i + 1].t <= targetT) i++;
499:     r.index = i;
500:     const f = frames[i];
501:     const next = frames[Math.min(frames.length - 1, i + 1)];
502:     const p = next.t > f.t ? clamp((targetT - f.t) / (next.t - f.t), 0, 1) : 0;
503:     for (const [bi, b] of this.boxers.entries()) {
504:       const a = f.boxers[bi], c = next.boxers[bi];
505:       if (!a) continue;
506:       b.root.position.set(lerp(a.pos[0], c.pos[0], p), lerp(a.pos[1], c.pos[1], p), lerp(a.pos[2], c.pos[2], p));
507:       b.root.rotation.y = lerp(a.ry, c.ry, p);
508:       const pose = {};
509:       for (const k of Object.keys(a.state.pose)) pose[k] = lerp(a.state.pose[k], c.state?.pose?.[k] ?? a.state.pose[k], p);
510:       b.applyRenderState({ ...a.state, pose });
511:     }
512:     this.camera.position.set(
513:       lerp(f.cam.pos[0], next.cam.pos[0], p),
514:       lerp(f.cam.pos[1], next.cam.pos[1], p),
515:       lerp(f.cam.pos[2], next.cam.pos[2], p),
516:     );
517:     const look = new THREE.Vector3(
518:       lerp(f.cam.look[0], next.cam.look[0], p),
519:       lerp(f.cam.look[1], next.cam.look[1], p),
520:       lerp(f.cam.look[2], next.cam.look[2], p),
521:     );
522:     this.camera.lookAt(look);
523:     this.cameraTarget.copy(look);
524:     this.heat = f.heat;
525:     if (r.elapsed * r.speed >= (frames[frames.length - 1].t - tStart) || r.elapsed > 18) {
526:       const cb = r.onDone;
527:       this.replay = null;
528:       this.syncFighters(1);
529:       cb?.();
530:     }
531:   }
