231:     <polyline points="${pts}" fill="none" stroke="#f2c14e" stroke-width="2" stroke-linejoin="round"/>
232:     <polygon points="0,${h} ${pts} ${w},${h}" fill="url(#spark)"/>
233:   </svg>`;
234: }

