178:   }
179:   const repDelta = won ? 6 : draw ? 1 : -4;
180:   c.reputation = clamp(c.reputation + repDelta, 0, 100);
181:   const basePoints = won ? (ko ? 190 : 145) : draw ? 35 : -25;
182:   const hypeBonus = Math.round((offer?.hype || 40) * 0.55);
183:   const titleBonus = offer?.title ? 80 : 0;
184:   const oldPoints = c.points;
185:   c.points = Math.max(0, c.points + basePoints + (won ? hypeBonus + titleBonus : 0));
186: 
187:   // Purse and TG COIN
