269:   };
270:   c.history.unshift(historyEntry);
271:   if (c.history.length > 100) c.history.length = 100;
272:   if (!c.foughtArenas.includes(arenaId || offer?.arenaId)) c.foughtArenas.push(arenaId || offer?.arenaId);
273:   if (won) c.season.bestWin = op.name || c.season.bestWin;
