295:       title: `${save.profile.name} perde o ${BELT_TIERS.find((t) => t.id === titleLost.tier)?.name || 'cinturão'} para ${op.name || 'o desafiante'}`,
296:       subtitle: 'Uma noite amarga para o até então campeão.',
297:       body: `O reinado de ${save.profile.name} chegou ao fim. ${op.name || 'O desafiante'} venceu por ${method} e levou o cinturão dos ${divInfo.name.toLowerCase()}s. A revanche já é especulada nos bastidores.`,
298:       division: div, hero: { name: save.profile.name, nick: save.profile.nickname }, imageSeed: 3, featured: true,
299:     });
300:   }
301: 
302:   // Calendar and world
303:   const offerDate = offer?.date ? new Date(offer.date).getTime() : Date.now();
