221: function sparkline(values) {
222:   if (!values.length) values = [100];
223:   const w = 300, h = 90;
224:   const pts = values.map((v, i) => {
225:     const x = values.length === 1 ? w / 2 : (i / (values.length - 1)) * w;
226:     const y = ((v - 1) / 99) * (h - 10) + 5;
227:     return `${x.toFixed(1)},${y.toFixed(1)}`;
228:   }).join(' ');
229:   return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="100" preserveAspectRatio="none" aria-hidden="true">
230:     <defs><linearGradient id="spark" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f2c14e" stop-opacity=".35"/><stop offset="1" stop-color="#f2c14e" stop-opacity="0"/></linearGradient></defs>
231:     <polyline points="${pts}" fill="none" stroke="#f2c14e" stroke-width="2" stroke-linejoin="round"/>
232:     <polygon points="0,${h} ${pts} ${w},${h}" fill="url(#spark)"/>
233:   </svg>`;
234: }

