  if (this.conn && this.conn !== conn) {
    // Guest reconnecting: replace stale channel.
    if (this.role === 'host') {
      try { conn.close(); } catch {}
      this.emit('notice', { message: 'Uma segunda conexão tentou entrar. Sala já ocupada.' });
      return;
    }
  }
  this.conn = conn;
  conn.on('open', () => {
    this.connected = true;
    this.lastMessageAt = Date.now();
    this.reconnectAttempts = 0;
    this._startHeartbeat();
    this.emit('connected', { role: this.role });
    if (this.role === 'guest' && this.localInfo) {
      this.send({ t: 'hello', ...this.localInfo, resume: this.reconnectAttempts > 0 });
    }
  });
  conn.on('data', (data) => this._onData(data));
  conn.on('close', () => {
    this.connected = false;
    this._stopHeartbeat();
    this.emit('disconnected', { role: this.role });
    if (this.role === 'guest' && !this.destroyed) this._scheduleReconnect();
  });
