    this.connected = false;
    this._stopHeartbeat();
    this.emit('disconnected', { role: this.role });
    if (this.role === 'guest' && !this.destroyed) this._scheduleReconnect();
  });
  conn.on('error', () => {
    this.emit('status', { state: 'error', label: 'Erro na conexão P2P.' });
  });
}

