657:         guard: f.guard, blocking: f.blocking, action: f.action ? { type: f.action.type, time: f.action.time, dur: f.action.def.dur } : null,
658:         stun: f.stun, dodge: { ...f.dodge }, knockdowns: f.knockdowns, combo: f.combo, expression: f.expression,
