681:         f.defeated = !!s.fighters[i]?.defeated;
682:       });
683:       this.emit('result', this.result);
684:     }
685:     if (this.fighters && s.fighters) {
686:       s.fighters.forEach((sf, i) => {
687:         const f = this.fighters[i];
688:         if (!f) return;
689:         Object.assign(f, {
690:           hp: sf.hp, maxHp: sf.maxHp, stamina: sf.stamina, guard: sf.guard, blocking: sf.blocking,
691:           stun: sf.stun, knockdowns: sf.knockdowns, combo: sf.combo, expression: sf.expression,
692:           victory: sf.victory, defeated: sf.defeated, hurtFlash: sf.hurtFlash, facing: sf.facing,
693:         });
694:         f.pos = { ...sf.pos };
695:         f.dodge = { ...sf.dodge };
696:         f.action = sf.action ? { type: sf.action.type, time: sf.action.time, def: PUNCHES[sf.action.type], resolved: true } : null;
697:         f.down = sf.down;
698:         f.netPos = { ...sf.pos };
699:       });
700:     }
701:     if (s.down) {
702:       const fighter = this.fighters.find((f) => f.id === s.down.id);
703:       this.down = { fighter, time: s.down.time, count: s.down.count, fallProgress: s.down.fallProgress, resolved: true, recovered: false };
704:     } else {
705:       this.down = null;
706:     }
707:     if (s.judges) s.judges.forEach((j, i) => { if (this.judges[i]) this.judges[i].scores = [...j.scores]; });
708:     if (s.stats) s.stats.forEach((st, i) => { if (this.fighters[i]) this.fighters[i].stats = { ...st }; });
709:     if (s.phase === 'end') this.finished = true;
710:   }
711: }
