148:   const createSession = (role) => {
149:     const mp = {
150:       role,
151:       localInfo: state.localInfo,
152:       remoteInfo: null,
153:       code: state.code,
154:       public: false,
155:       hostReady: false,
156:       guestReady: false,
157:       hostWager: 0,
158:       guestWager: 0,
159:       wager: 0,
160:       rounds: state.rounds,
161:       arenaId: state.arenaId,
162:       messages: [],
163:       listeners: new Set(),
164:       match: null,
165:     };
166:     mp.session = new NetSession({
167:       onEvent: (type, payload) => {
168:         if (type === 'message') return;
169:         for (const fn of mp.listeners) {
170:           try { fn(type, payload || {}); } catch (err) { console.warn('mp listener', type, err); }
171:         }
172:       },
173:     });
174:     ui.mp = mp;
175:     detach = attachMp(ui, onNetEvent);
176:     return mp;
177:   };
