198:   const onNetEvent = (type, d = {}) => {
199:     switch (type) {
200:       case 'ready': {
201:         if (d.code) state.code = d.code;
202:         if (d.public != null) state.public = !!d.public;
203:         if (state.phase !== 'lobby') state.phase = 'lobby';
204:         saveStateToMp();
205:         paint();
206:         break;
207:       }
208:       case 'connected': {
209:         setStatus('online', 'Conectado · P2P');
210:         if (ui.mp) ui.mp.connected = true;
211:         paint();
212:         break;
213:       }
214:       case 'status': {
215:         setStatus(d.state || 'info', d.label || '');
216:         paint();
217:         break;
218:       }
219:       case 'error': {
220:         state.error = d.message || 'Falha na conexão.';
221:         state.joining = false;
222:         state.busy = false;
223:         setStatus('offline', state.error);
224:         ui.toast(state.error, 'error', 'wifiOff');
225:         if (state.phase === 'menu' || !ui.mp?.connected) {
226:           resetToMenu(state.error);
227:         } else {
228:           paint();
229:         }
230:         break;
231:       }
232:       case 'notice': {
233:         if (d.message) ui.toast(d.message, 'info', 'wifi');
234:         break;
235:       }
236:       case 'disconnected': {
237:         setStatus('offline', 'Conexão perdida. Tentando reconectar...');
238:         saveStateToMp();
239:         paint();
240:         break;
241:       }
242:       case 'reconnected': {
243:         setStatus('online', 'Reconectado');
244:         ui.toast('Reconectado ao adversário.', 'success', 'wifi');
245:         paint();
246:         break;
247:       }
248:       case 'hello': {
249:         if (state.role !== 'host') break;
250:         state.remoteInfo = sanitizeFighterInfo(d);
251:         if (ui.mp) ui.mp.remoteInfo = state.remoteInfo;
252:         if (typeof d.ready === 'boolean') state.guestReady = d.ready;
253:         if (Number.isFinite(Number(d.wager))) state.guestWager = Number(d.wager);
254:         sendMp(ui, {
255:           t: 'welcome',
256:           host: state.localInfo,
257:           code: state.code,
258:           ready: state.hostReady,
259:           wager: state.hostWager,
260:           rounds: state.rounds,
261:           arenaId: state.arenaId,
262:           match: ui.mp?.match || null,
263:         });
264:         setStatus('online', d.resume ? 'Adversário reconectado' : 'Adversário conectado');
265:         saveStateToMp();
266:         if (d.resume) ui.toast('Adversário reconectado.', 'success', 'wifi');
267:         paint();
268:         break;
269:       }
270:       case 'welcome': {
271:         if (state.role !== 'guest') break;
272:         state.remoteInfo = sanitizeFighterInfo(d.host || d);
273:         if (ui.mp) ui.mp.remoteInfo = state.remoteInfo;
274:         if (typeof d.ready === 'boolean') state.hostReady = d.ready;
275:         if (Number.isFinite(Number(d.wager))) state.hostWager = Number(d.wager);
276:         if (Number.isFinite(Number(d.rounds))) state.rounds = Number(d.rounds);
277:         if (ARENA_BY_ID[d.arenaId]) state.arenaId = d.arenaId;
278:         if (d.match) ui.mp.match = d.match;
279:         setStatus('online', 'Conectado ao anfitrião');
280:         saveStateToMp();
281:         paint();
282:         break;
283:       }
284:       case 'settings': {
285:         if (state.role !== 'guest') break;
286:         if (ROUND_OPTIONS.includes(Number(d.rounds))) state.rounds = Number(d.rounds);
287:         if (ARENA_BY_ID[d.arenaId]) state.arenaId = d.arenaId;
288:         paint();
289:         break;
290:       }
291:       case 'ready': {
292:         if (state.role === 'host') {
293:           state.guestReady = !!d.ready;
294:           if (Number.isFinite(Number(d.wager))) state.guestWager = Number(d.wager);
295:           if (d.info) state.remoteInfo = sanitizeFighterInfo(d.info);
296:         } else {
297:           state.hostReady = !!d.ready;
298:           if (Number.isFinite(Number(d.wager))) state.hostWager = Number(d.wager);
299:           if (d.info) state.remoteInfo = sanitizeFighterInfo(d.info);
300:         }
301:         saveStateToMp();
302:         paint();
303:         break;
304:       }
305:       case 'chat': {
306:         const text = String(d.text || '').slice(0, 180).trim();
307:         if (!text) break;
308:         state.messages.push({ from: state.remoteInfo?.name || 'Adversário', text, mine: false });
309:         if (state.messages.length > 40) state.messages.shift();
310:         saveStateToMp();
311:         paint({ keepChat: true });
312:         break;
313:       }
314:       case 'match': {
315:         if (!d.match || state.role !== 'guest') break;
316:         if (ui.mp) ui.mp.match = d.match;
317:         state.starting = true;
318:         saveStateToMp();
319:         launchFight();
320:         break;
321:       }
322:       case 'closed': {
323:         if (state.phase === 'lobby') {
324:           setStatus('offline', 'Sala encerrada pelo anfitrião.');
325:           ui.toast('A sala foi encerrada.', 'error', 'wifiOff');
326:           resetToMenu('Sala encerrada.');
327:         }
328:         break;
329:       }
330:       default:
331:         break;
332:     }
333:   };
