387:     this.lastMessageAt = Date.now();
388:     if (data.t === 'hello' && this.role === 'host') {
389:       this.remoteInfo = data;
390:       this.emit('hello', data);
391:       return;
392:     }
393:     if (data.t === 'welcome' && this.role === 'guest') {
394:       this.remoteInfo = data.host || data;
395:       this.emit('welcome', data);
396:       return;
397:     }
398:     this.emit('message', data);
399:     if (data.t) this.emit(data.t, data);
400:   }
401: 
402:   send(message) {
403:     if (!this.conn?.open) return false;
404:     try {
405:       this.conn.send(message);
406:       return true;
407:     } catch (err) {
408:       console.warn('send failed', err);
409:       return false;
410:     }
411:   }
412: 
413:   _startHeartbeat() {
414:     this._stopHeartbeat();
415:     this.heartbeat = setInterval(() => {
416:       if (!this.connected) return;
417:       if (this.role === 'guest') {
418:         this.send({ t: 'ping', ts: Date.now() });
419:         if (Date.now() - this.lastMessageAt > 12000) {
420:           this.emit('status', { state: 'reconnecting', label: 'Conexão instável...' });
421:         }
422:       } else {
423:         this.send({ t: 'ping', ts: Date.now(), host: true });
424:       }
425:     }, 2500);
426:   }
