433:   _handlePeerError(err) {
434:     const type = err?.type || '';
435:     let message = err?.message || 'Erro de conexão.';
436:     if (type === 'unavailable-id') message = 'Este código de sala já está em uso. Gere outro.';
437:     else if (type === 'peer-unavailable') message = 'Sala não encontrada. Confira o código ou o link.';
438:     else if (type === 'network') message = 'Falha de rede no servidor de salas. Verifique sua internet.';
439:     else if (type === 'server-error') message = 'Servidor de sinalização indisponível. Tente novamente.';
440:     else if (type === 'browser-incompatible') message = 'Seu navegador não suporta WebRTC.';
441:     this.emit('error', { type, message });
442:   }
443: 
444:   destroy() {
445:     this.destroyed = true;
