86: export function trainDrill(save, universe, drillId, timing = 0.72) {
87:   const drill = DRILLS.find((d) => d.id === drillId);
88:   if (!drill) return { ok: false, message: 'Treino inválido.' };
89:   if (save.career.training.sessionsLeft <= 0) return { ok: false, message: 'Sem sessões hoje. Descanse para recuperar a energia.' };
90:   const fatigue = save.career.training.fatigue || 0;
91:   const readiness = clamp(1 - fatigue / 180, 0.55, 1.05);
92:   const quality = clamp(0.72 + timing * 0.72, 0.72, 1.42);
93:   const gains = {};
94:   const boosterEntry = Object.entries(save.career.boosters || {}).find(([, count]) => count > 0);
95:   const boosterActive = !!boosterEntry;
96:   for (const attr of drill.attrs) {
97:     const gear = gearBoost(save, attr);
98:     const booster = boosterActive ? 1.08 : 1;
99:     const raw = (1.15 + Math.random() * 1.55) * readiness * quality * (1 + gear) * booster;
100:     const gain = Math.max(1, Math.round(raw));
101:     const old = save.profile.attributes[attr] || 42;
102:     save.profile.attributes[attr] = Math.min(99, old + gain);
103:     gains[attr] = save.profile.attributes[attr] - old;
104:   }
105:   if (boosterEntry) {
106:     save.career.boosters[boosterEntry[0]] = Math.max(0, boosterEntry[1] - 1);
107:   }
108:   save.career.training.sessionsLeft--;
109:   save.career.training.totalSessions++;
110:   save.career.training.fatigue = clamp(fatigue + 13, 0, 100);
111:   save.career.training.lastDrill = drillId;
112:   save.career.points += 1;
113:   advanceDate(save, 1);
114:   if (Math.random() < 0.3) simulateBackground(universe, save, 1);
115:   return { ok: true, gains, drill, fatigue: save.career.training.fatigue };
116: }
