170:   c.streak = won ? Math.max(1, c.streak + 1) : draw ? 0 : Math.min(-1, c.streak - 1);
171:   c.bestStreak = Math.max(c.bestStreak, c.streak);
172:   c.totalPurse += offer?.purse || 0;
