181:   const basePoints = won ? (ko ? 190 : 145) : draw ? 35 : -25;
182:   const hypeBonus = Math.round((offer?.hype || 40) * 0.55);
183:   const titleBonus = offer?.title ? 80 : 0;
184:   const oldPoints = c.points;
185:   c.points = Math.max(0, c.points + basePoints + (won ? hypeBonus + titleBonus : 0));
186: 
187:   // Purse and TG COIN
188:   const purseRate = won ? 1 : draw ? 0.72 : 0.58;
189:   const purse = Math.round((offer?.purse || 2000) * purseRate);
190:   const sponsor = c.sponsor ? SHOP_ITEMS.find((i) => i.id === c.sponsor) : null;
191:   const sponsorMoney = won && sponsor ? (c.sponsor === 'sponsor_global' ? 900 : 200) : 0;
192:   const sponsorCoins = won && sponsor ? (c.sponsor === 'sponsor_global' ? 20 : 0) : 0;
193:   const coinRate = won ? 1 : draw ? 0.4 : 0.22;
194:   const coins = Math.round((offer?.coinReward || 50) * coinRate) + sponsorCoins;
195:   addMoney(save, purse + sponsorMoney);
196:   addCoins(save, coins, 'Bolsa de luta');
197: 
198:   // Titles
199:   let titleWon = null;
200:   let titleLost = null;
201:   if (offer?.title && won) {
202:     const existing = c.belts.find((b) => b.org === offer.title.org && b.division === div);
203:     if (existing) {
204:       existing.defenses = (existing.defenses || 0) + 1;
205:       existing.lastDefendedAt = new Date().toISOString();
206:       if (beltPrestige(offer.title.tier) >= beltPrestige(existing.tier)) existing.tier = offer.title.tier;
207:       existing.level = offer.title.tier;
208:       c.season.defenses++;
209:       titleWon = { ...existing, defense: true };
210:     } else {
211:       const belt = {
