232:   if (npc) {
233:     if (won) {
234:       npc.record.l++;
235:       npc.points = Math.max(10, npc.points - 48);
236:       npc.streak = Math.min(-1, npc.streak - 1);
237:       npc.form = ['D', ...(npc.form || [])].slice(0, 5);
