          title: { org: challengeOrg.id, tier, name: tier === 'supreme' ? 'Campeão dos Campeões' : 'Cinturão Absoluto' },
          purse: 95000 + heldOrgs.size * 40000, coins: 1800, rounds: 6, arenaId: 'champions', hype: 100,
