  background:
    radial-gradient(120% 80% at 85% 0%, rgba(225, 29, 72, 0.09), transparent 55%),
    linear-gradient(180deg, rgba(6, 6, 8, 0.62) 0%, rgba(6, 6, 8, 0.28) 32%, rgba(6, 6, 8, 0.82) 100%);
  animation: screenIn 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
