@keyframes screenIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
.screen-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin-bottom: 26px; flex-wrap: wrap; }
.screen-title { font-family: var(--font-display); font-size: clamp(34px, 5vw, 62px); line-height: 0.9; margin: 6px 0 0; letter-spacing: 0.015em; }
