484:.combo-meter { position: absolute; left: clamp(14px, 3vw, 38px); top: 130px; font-family: var(--font-display); font-size: 32px; color: var(--gold); opacity: 0; transform: translateX(-10px); transition: 0.2s; text-shadow: 0 4px 18px rgba(0, 0, 0, 0.8); }
