499:.joystick::before { content: ''; position: absolute; inset: 25%; border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 50%; }
500:.joystick-knob { position: absolute; width: 54px; height: 54px; border-radius: 50%; left: 50%; top: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.32), rgba(242, 193, 78, 0.25)); border: 1px solid rgba(242, 193, 78, 0.5); box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4); }
