502:.action-pad { position: absolute; right: 18px; bottom: 24px; width: 190px; height: 190px; pointer-events: none; }
503:.act-btn { position: absolute; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.2); background: rgba(8, 8, 12, 0.62); color: var(--text); display: grid; place-items: center; font-family: var(--font-display); font-size: 15px; pointer-events: auto; touch-action: none; backdrop-filter: blur(4px); transition: transform 0.08s, background 0.08s; user-select: none; }
