515:.key { display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px; border: 1px solid rgba(255, 255, 255, 0.22); border-radius: 4px; font-size: 9px; color: var(--text); background: rgba(255, 255, 255, 0.06); }
