532:.intro-details .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; margin-top: 4px; }
533:.intro-details .title-line { font-family: var(--font-cond); color: var(--gold); font-size: 12px; letter-spacing: 0.18em; margin-top: 8px; display: flex; gap: 8px; justify-content: center; align-items: center; }
534:.intro-buttons { display: flex; gap: 10px; justify-content: center; margin-top: 24px; flex-wrap: wrap; }
535:.result-card { width: min(900px, 94vw); }
536:.result-head { text-align: center; margin-bottom: 20px; }
537:.result-head .method { font-family: var(--font-display); font-size: clamp(56px, 10vw, 110px); line-height: 0.8; color: var(--gold); }
538:.result-head .winner { font-family: var(--font-display); font-size: clamp(26px, 4vw, 46px); margin-top: 6px; }
539:.result-head .winner span { color: var(--gold); }

.result-head .winner span { color: var(--gold); }
.result-head .meta { font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.15em; color: var(--muted); margin-top: 3px; }
.result-stats { display: grid; grid-template-columns: 1fr auto 1fr; gap: 20px; align-items: center; }
.result-side { display: flex; flex-direction: column; gap: 6px; }
