.result-news span { color: var(--gold); font-size: 9px; letter-spacing: 0.18em; display: block; margin-bottom: 3px; }
.replay-overlay { position: absolute; top: 26px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.25em; color: var(--gold); text-transform: uppercase; background: rgba(6, 6, 8, 0.6); border: 1px solid rgba(242, 193, 78, 0.25); padding: 7px 13px; border-radius: 4px; pointer-events: none; animation: blink 1.2s infinite; }
@keyframes blink { 50% { opacity: 0.55; } }
.pause-menu { width: min(440px, 92vw); }
.pause-menu .panel-body { display: flex; flex-direction: column; gap: 8px; }
.pause-menu h2 { font-family: var(--font-display); font-size: 44px; margin: 0 0 4px; text-align: center; }

/* -------------------------------- Multiplayer -------------------------------- */
.mp-layout { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.75fr); gap: 18px; align-items: start; }
.lobby-card { padding: 26px; }
.room-code { font-family: var(--font-display); font-size: clamp(42px, 7vw, 72px); letter-spacing: 0.16em; color: var(--gold); text-align: center; line-height: 1; padding: 16px 0 8px; }
.invite-box { display: flex; gap: 8px; margin-top: 12px; }
.invite-box input { flex: 1; background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); color: var(--muted); border-radius: 7px; padding: 9px 11px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.03em; min-width: 0; }
.player-slots { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px; margin: 20px 0; }
.player-slot { border: 1px solid var(--line); border-radius: 12px; padding: 16px; text-align: center; background: rgba(255, 255, 255, 0.025); min-height: 150px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; }
.player-slot.ready { border-color: rgba(52, 211, 153, 0.45); box-shadow: inset 0 0 30px rgba(52, 211, 153, 0.06); }
.player-slot .avatar { width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 40% 30%, #5c1d28, #111118); border: 1px solid rgba(242, 193, 78, 0.3); display: grid; place-items: center; font-family: var(--font-display); font-size: 24px; color: var(--gold); }
.player-slot b { font-family: var(--font-cond); font-size: 15px; }
.player-slot span { font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.vs-small { font-family: var(--font-display); font-size: 26px; color: var(--muted2); }
.connection-pill { display: inline-flex; align-items: center; gap: 7px; font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.08em; padding: 6px 10px; border-radius: 999px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); }
.connection-pill .dot { width: 7px; height: 7px; border-radius: 50%; background: #eab308; }
.connection-pill.online .dot { background: var(--green); box-shadow: 0 0 8px rgba(52, 211, 153, 0.8); }
.connection-pill.offline .dot { background: var(--red); }
.mp-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.quick-list { display: flex; flex-direction: column; gap: 8px; }
.quick-row { display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; cursor: pointer; }
.quick-row:hover { border-color: rgba(242, 193, 78, 0.3); background: rgba(242, 193, 78, 0.04); }
.quick-row .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); }
.quick-row b { font-family: var(--font-cond); font-size: 13px; }
.quick-row span { margin-left: auto; font-family: var(--font-cond); font-size: 10px; color: var(--muted); }
.wager-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.wager-row button { border: 1px solid var(--line); background: rgba(255, 255, 255, 0.03); border-radius: 6px; color: var(--muted); padding: 7px 11px; font-family: var(--font-cond); font-size: 11px; cursor: pointer; }
.wager-row button.active { border-color: var(--gold); color: var(--gold); background: rgba(242, 193, 78, 0.08); }
.chat-feed { max-height: 150px; overflow-y: auto; display: flex; flex-direction: column; gap: 5px; font-family: var(--font-cond); font-size: 12px; }
.chat-feed .msg { color: var(--muted); }
.chat-feed .msg b { color: var(--text); }
.match-history { display: flex; flex-direction: column; }
.match-history .row-item { display: flex; gap: 10px; align-items: center; padding: 9px 0; border-bottom: 1px solid var(--line); font-family: var(--font-cond); font-size: 12px; }
.match-history .win { color: var(--green); }
.match-history .loss { color: #ff7c91; }
.mp-status { text-align: center; padding: 22px; }
.mp-status .big { font-family: var(--font-display); font-size: 32px; }
.spinner { width: 34px; height: 34px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.12); border-top-color: var(--gold); animation: spin 1s linear infinite; margin: 0 auto 12px; }

/* -------------------------------- Modal / toast -------------------------------- */
.modal-backdrop { position: fixed; inset: 0; z-index: 80; background: rgba(3, 3, 5, 0.78); backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; padding: 20px; animation: fadeIn 0.2s; }
.modal { width: min(560px, 94vw); max-height: 88vh; overflow-y: auto; background: #111117; border: 1px solid var(--line2); border-radius: 16px; box-shadow: var(--shadow); padding: 26px; }
.modal.wide { width: min(850px, 95vw); }
.modal h2 { font-family: var(--font-display); font-size: 34px; margin: 0 0 6px; }
.modal p { color: var(--muted); font-size: 13px; line-height: 1.6; }
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 22px; flex-wrap: wrap; }
@keyframes fadeIn { from { opacity: 0; } }
.toast-stack { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); z-index: 120; display: flex; flex-direction: column; gap: 8px; pointer-events: none; width: min(420px, 92vw); }
.toast { background: rgba(16, 16, 22, 0.96); border: 1px solid var(--line2); border-left: 2px solid var(--gold); border-radius: 8px; padding: 11px 14px; font-family: var(--font-cond); font-size: 13px; display: flex; align-items: center; gap: 9px; box-shadow: var(--shadow); animation: toastIn 0.28s cubic-bezier(0.22, 1, 0.36, 1); pointer-events: auto; }
.toast.error { border-left-color: var(--red); }
.toast.success { border-left-color: var(--green); }
.toast.achievement { border-left-color: var(--gold); background: linear-gradient(90deg, rgba(242, 193, 78, 0.15), #111117); }
.toast .ic { color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px); } }
.toast.out { animation: toastOut 0.3s forwards; }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

/* -------------------------------- Misc -------------------------------- */
.empty-state { text-align: center; padding: 50px 20px; color: var(--muted); }
.empty-state .ic { color: var(--muted2); margin-bottom: 10px; }
.empty-state b { display: block; font-family: var(--font-display); font-size: 26px; color: var(--text); margin-bottom: 4px; }
.loading-block { display: grid; place-items: center; padding: 60px; }
.kbd-hint { font-family: var(--font-cond); font-size: 10px; color: var(--muted2); letter-spacing: 0.1em; }
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin-bottom: 18px; overflow-x: auto; }
.tabs button { background: none; border: none; border-bottom: 2px solid transparent; color: var(--muted); padding: 10px 14px; font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; cursor: pointer; white-space: nowrap; }
.tabs button:hover { color: var(--text); }
.tabs button.active { color: var(--gold); border-bottom-color: var(--gold); }
.division-badge { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.division-badge i { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); }
.list-plain { margin: 0; padding: 0; list-style: none; }
.notice { border-left: 2px solid var(--gold); background: rgba(242, 193, 78, 0.06); padding: 11px 14px; font-family: var(--font-cond); font-size: 12px; line-height: 1.5; color: #cfc9b8; }
.notice.red { border-color: var(--red); background: rgba(225, 29, 72, 0.07); }
.notice.green { border-color: var(--green); background: rgba(52, 211, 153, 0.06); }

/* -------------------------------- Responsive -------------------------------- */
@media (max-width: 1100px) {
  .editor { grid-template-columns: 180px minmax(200px, 1fr) 320px; }
  .career-top { grid-template-columns: 1fr; }
  .career-side { grid-template-columns: 1fr 1fr 1fr; }
  .next-fight-card { grid-column: auto; }
  .dashboard-grid { grid-template-columns: 1fr; }
  .rank-layout { grid-template-columns: 1fr; }
  .news-layout { grid-template-columns: 1fr; }
  .mp-layout { grid-template-columns: 1fr; }
  .gym-layout { grid-template-columns: 1fr; }
  .settings-layout { grid-template-columns: 1fr; }
  .settings-nav { flex-direction: row; overflow-x: auto; }
  .records-grid { grid-template-columns: 1fr; }
  .menu-left { width: min(380px, 92vw); }
  .main-logo { font-size: clamp(60px, 10vw, 96px); }
}
@media (max-width: 820px) {
  body { overflow: hidden; }
  .screen { padding: 16px 14px 80px; }
  .topbar { flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
  .topnav { order: 3; width: 100%; overflow-x: auto; flex-wrap: nowrap; padding-bottom: 4px; }
  .topnav button { white-space: nowrap; font-size: 11px; }
  .userbar { margin-left: auto; }
  .profile-pill small { display: none; }
  .menu-left { width: 100%; margin-top: 4vh; }
  .main-menu { justify-content: flex-start; padding-top: 8vh; padding-bottom: 100px; overflow-y: auto; display: block; }
  .main-logo { font-size: clamp(66px, 19vw, 100px); }
  .menu-btn { padding: 10px 13px; }
  .menu-btn b { font-size: 19px; }
  .menu-btn small { display: none; }
  .menu-ticker { padding: 9px 14px; }
  .hero-badge { display: none; }
  .career-side { grid-template-columns: 1fr 1fr; }
  .next-fight-card { grid-column: 1 / -1; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: 1fr; }
  .editor { grid-template-columns: 1fr; grid-template-rows: minmax(280px, 45vh) 1fr; }
  .editor-left { position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; flex-direction: row; overflow-x: auto; padding: 8px; gap: 4px; justify-content: flex-start; background: linear-gradient(0deg, rgba(6, 6, 8, 0.95), transparent); }
  .editor-left .cat-btn { flex-direction: column; gap: 3px; font-size: 9px; padding: 8px 10px; white-space: nowrap; border-left: none; border-bottom: 2px solid transparent; }
  .editor-left .cat-btn.active { border-bottom-color: var(--gold); }
  .editor-left .done { margin-top: 0; margin-left: auto; }
  .editor-center { grid-row: 1; justify-content: center; padding-bottom: 70px; }
  .editor-right { grid-row: 2; border-left: none; border-top: 1px solid var(--line); max-height: none; height: auto; }
  .editor-scroll { max-height: 44vh; }
  .editor-head { padding: 12px 14px; }
  .editor-head h2 { font-size: 23px; }
  .editor-footer { position: sticky; bottom: 0; background: #0c0c11; }
  .hud-top { padding: 10px 12px; gap: 8px; }
  .hud-avatar { width: 36px; height: 36px; font-size: 14px; border-width: 1px; }
  .hud-name { font-size: 11px; }
  .hud-record { font-size: 8px; margin-bottom: 3px; }
  .round-timer { font-size: 34px; }
  .round-center { min-width: 74px; }
  .hud-info { max-width: 42vw; }
  .hud-bottom { bottom: 8px; }
  .hud-stats { display: none; }
  .desktop-hint { display: none; }
  .combo-meter { top: 100px; font-size: 24px; }
  .vs-card { grid-template-columns: 1fr; gap: 12px; }
  .vs-mid { order: -1; display: flex; align-items: center; justify-content: center; gap: 12px; }
  .vs-mid .vs { font-size: 46px; }
  .vs-mid .at { margin: 0; }
  .vs-fighter .portrait { width: 92px; height: 92px; font-size: 34px; margin-bottom: 8px; }
  .vs-fighter h2 { font-size: 34px; }
  .result-stats { grid-template-columns: 1fr 1fr; }
  .result-stats .vs-small { display: none; }
  .scorecards { grid-template-columns: 1fr; }
  .fight-overlay { padding: 14px; align-items: flex-start; padding-top: 30px; }
  .modal { padding: 20px; }
  .division-tabs button { font-size: 10px; padding: 6px 9px; }
