.touch-controls[data-side="right"] .joystick { right:22px; left:auto; } but default .joystick left 22. Better explicit:
.touch-controls[data-side="right"] .joystick { left:auto; right:22px; }
.touch-controls[data-side="right"] .action-pad { right:18px; }
.touch-controls[data-side="left"] .action-pad { left:18px; right:auto; }
