.form-grid.two { grid-template-columns: 1fr 1fr; }
.style-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.style-pill { text-align: left; border: 1px solid var(--line); border-left: 3px solid var(--sc, var(--gold)); background: rgba(255, 255, 255, 0.025); border-radius: 8px; padding: 10px 12px; cursor: pointer; color: var(--text); transition: 0.16s; }
.style-pill:hover { background: rgba(255, 255, 255, 0.06); border-color: var(--line2); }
.style-pill b { display: block; font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.06em; text-transform: uppercase; }
.style-pill span { display: block; margin-top: 2px; font-family: var(--font-cond); font-size: 10px; color: var(--muted); line-height: 1.35; }
.style-pill.active { border-color: var(--gold); background: rgba(242, 193, 78, 0.08); box-shadow: inset 0 0 24px rgba(242, 193, 78, 0.06); }
.alloc-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; }
.alloc-pill { display: flex; align-items: center; gap: 7px; padding: 7px 9px; border: 1px solid var(--line); border-radius: 7px; background: rgba(255, 255, 255, 0.025); font-family: var(--font-cond); font-size: 11px; color: var(--muted); }
.alloc-pill .lbl { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.alloc-pill b { color: var(--text); font-size: 14px; min-width: 18px; text-align: right; }
.alloc-btns { display: flex; gap: 3px; }
.alloc-btns button { width: 22px; height: 22px; border-radius: 4px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.05); color: var(--text); cursor: pointer; display: grid; place-items: center; font-size: 14px; line-height: 1; transition: 0.14s; }
.alloc-btns button:hover:not(:disabled) { border-color: var(--gold); color: var(--gold); }
.alloc-btns button:disabled { opacity: 0.3; cursor: not-allowed; }

/* --- Editor extras --- */
.ed-search-row { display: flex; align-items: center; gap: 7px; margin-bottom: 10px; }
.ed-search-row .input { flex: 1; min-width: 0; }

/* --- Career extras --- */
.offer-actions { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; max-width: 250px; }
.active-contract { padding: 4px; }
.active-contract h2 { letter-spacing: 0.02em; }
.belts-strip { display: flex; flex-direction: column; gap: 10px; }
.champ-row { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.champ-row:last-child { border-bottom: none; }
.champ-row b { font-family: var(--font-cond); font-size: 14px; display: block; }
.org-dot { width: 9px; height: 9px; border-radius: 50%; flex: none; box-shadow: 0 0 10px currentColor; }
.rank-big { font-family: var(--font-display); font-size: 34px; line-height: 1; color: var(--text); }
.top3-row { display: flex; align-items: center; gap: 9px; padding: 7px 0; border-bottom: 1px solid var(--line); }
.top3-row:last-child { border-bottom: none; }
.top3-row .num { font-family: var(--font-display); font-size: 18px; color: var(--gold); width: 18px; }
.top3-row b { font-family: var(--font-cond); font-size: 13px; }

/* --- Fighter dossier --- */
.dossier-head { display: flex; align-items: center; gap: 16px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.dossier-body { display: grid; grid-template-columns: 1.05fr 0.95fr; gap: 24px; margin-top: 16px; }
.mini-belt { display: flex; gap: 9px; align-items: flex-start; padding: 6px 0; }
.mini-belt > span { color: var(--gold); flex: none; margin-top: 1px; }
.mini-belt b { font-family: var(--font-cond); font-size: 13px; display: block; }

/* --- News article --- */
.article-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; flex-wrap: wrap; }
.article-hero { height: 190px; border-radius: 12px; display: grid; place-items: center; margin-bottom: 16px; border: 1px solid var(--line); overflow: hidden; }
.article-hero span { font-family: var(--font-display); font-size: 78px; color: rgba(255, 255, 255, 0.14); letter-spacing: 0.04em; }
.news-cat-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; background: none; border: none; border-bottom: 1px solid var(--line); padding: 9px 5px; color: var(--muted); font-family: var(--font-cond); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; cursor: pointer; transition: 0.15s; }
.news-cat-row:last-child { border-bottom: none; }
.news-cat-row:hover { color: var(--text); background: rgba(255, 255, 255, 0.035); }
.news-cat-row b { color: var(--gold); font-size: 15px; }
.news-cat-row.active { color: var(--gold); background: linear-gradient(90deg, rgba(242, 193, 78, 0.09), transparent); }

/* --- Gym --- */
.drill-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.drill-grid .drill-card { margin-bottom: 0; }
.timing-panel { margin-top: 16px; padding: 14px; border: 1px solid var(--line); border-radius: 10px; background: rgba(0, 0, 0, 0.22); }
.timing-panel > .row { gap: 10px; }
.timing-result { min-height: 34px; margin-top: 10px; font-family: var(--font-cond); }
.training-gain { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 8px 11px; border-left: 2px solid var(--green); background: rgba(52, 211, 153, 0.06); font-family: var(--font-cond); font-size: 13px; animation: fadeIn 0.25s; }

/* --- Stats --- */
.history-row { display: flex; align-items: center; gap: 12px; padding: 10px 4px; border-bottom: 1px solid var(--line); cursor: pointer; transition: 0.15s; }
.history-row:last-child { border-bottom: none; }
.history-row:hover { background: rgba(255, 255, 255, 0.035); }
.history-row b { font-family: var(--font-cond); font-size: 13px; }
.result-badge { width: 28px; height: 28px; flex: none; display: grid; place-items: center; border-radius: 6px; font-family: var(--font-display); font-size: 15px; line-height: 1; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.05); color: var(--muted); }
.result-badge.win { background: rgba(52, 211, 153, 0.14); color: #6ee7b7; border-color: rgba(52, 211, 153, 0.35); }
.result-badge.loss { background: rgba(225, 29, 72, 0.13); color: #ff8197; border-color: rgba(225, 29, 72, 0.35); }
.result-badge.draw { background: rgba(56, 189, 248, 0.1); color: #7dd3fc; border-color: rgba(56, 189, 248, 0.3); }
.rank-spark { color: var(--gold); opacity: 0.95; }
.rank-spark svg { display: block; }
.timeline { position: relative; display: flex; flex-direction: column; gap: 2px; padding-left: 16px; }
.timeline::before { content: ''; position: absolute; left: 4px; top: 6px; bottom: 6px; width: 1px; background: var(--line2); }
.timeline-item { position: relative; display: flex; gap: 10px; padding: 6px 0; }
.timeline-item .dot { position: absolute; left: -16px; top: 11px; width: 9px; height: 9px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 0 3px rgba(242, 193, 78, 0.12); }
.timeline-item .dot.red { background: var(--red); box-shadow: 0 0 0 3px rgba(225, 29, 72, 0.12); }
.timeline-item b { font-family: var(--font-cond); font-size: 13px; }
.achievement-card { display: flex; gap: 12px; align-items: flex-start; padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: rgba(255, 255, 255, 0.02); opacity: 0.62; transition: 0.18s; }
.achievement-card .ic { color: var(--muted2); }
.achievement-card b { font-family: var(--font-cond); font-size: 14px; letter-spacing: 0.03em; }
.achievement-card p { margin: 3px 0 8px; }
.achievement-card.unlocked { opacity: 1; border-color: rgba(242, 193, 78, 0.35); background: linear-gradient(135deg, rgba(242, 193, 78, 0.09), rgba(255, 255, 255, 0.015)); }
.achievement-card.unlocked .ic { color: var(--gold); }
.award-card.mine { border-color: rgba(242, 193, 78, 0.5); background: linear-gradient(180deg, rgba(242, 193, 78, 0.14), rgba(255, 255, 255, 0.02)); box-shadow: 0 10px 30px rgba(242, 193, 78, 0.08); }

/* --- Multiplayer --- */
.mp-identity { display: flex; align-items: center; gap: 14px; }
.mp-name { display: block; font-family: var(--font-display); font-size: 25px; line-height: 1; letter-spacing: 0.02em; }
.join-row { display: flex; gap: 8px; }
.join-row .input { flex: 1; min-width: 0; }
.join-row .btn { flex: none; }
.wager-box { border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; margin-bottom: 14px; background: rgba(255, 255, 255, 0.025); }
.chat-panel { margin-top: 14px; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: rgba(0, 0, 0, 0.18); }
.chat-panel .panel-head { padding: 10px 12px; }
.chat-feed { padding: 10px 12px; max-height: 160px; }
.chat-feed .msg.mine b { color: var(--gold); }
.chat-input-row { display: flex; gap: 8px; padding: 10px 12px; border-top: 1px solid var(--line); }
.chat-input-row .input { flex: 1; min-width: 0; }
.chat-status { font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.16em; color: var(--muted2); }
.chat-status.ok { color: var(--green); }
.lobby-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.leave-btn { flex: none; }
.host-settings { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px; }
.mp-rules { display: flex; flex-direction: column; gap: 8px; font-family: var(--font-cond); font-size: 12px; line-height: 1.45; color: var(--muted); }
.mp-rules b { color: var(--gold); }
.mp-footnote { display: flex; align-items: flex-start; gap: 7px; margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line); font-family: var(--font-cond); font-size: 10px; line-height: 1.5; color: var(--muted2); }
.mp-disclaimer { font-family: var(--font-cond); font-size: 10px; line-height: 1.5; color: var(--muted2); }

/* --- Fight screen --- */
.fight-screen { padding: 0; overflow: hidden; background: transparent; animation: none; }
.fight-screen .fight-ui { z-index: 20; }
.fight-screen .hud-top,
.fight-screen .hud-bottom,
.fight-screen .combo-meter,
.fight-screen .announcer,
.fight-screen .count-overlay { pointer-events: none; }
.fight-screen .hud-actions,
.fight-screen .hud-btn,
.fight-screen .getup-btn,
.fight-screen .touch-controls button { pointer-events: auto; }
.fight-intro-wrap { width: min(1080px, 96vw); text-align: center; }
.intro-kicker { display: inline-flex; align-items: center; gap: 8px; margin-bottom: 18px; padding: 6px 14px; border: 1px solid rgba(242, 193, 78, 0.26); border-radius: 999px; background: rgba(242, 193, 78, 0.06); color: var(--gold); font-family: var(--font-cond); font-size: 11px; letter-spacing: 0.24em; text-transform: uppercase; }
.vs-tags { display: flex; justify-content: center; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.intro-quote { max-width: 640px; margin: 14px auto 0; color: #c4c0b6; font-family: var(--font-cond); font-size: 14px; line-height: 1.5; font-style: italic; }
.intro-hint { display: flex; align-items: center; justify-content: center; gap: 6px; flex-wrap: wrap; margin-top: 18px; color: rgba(255, 255, 255, 0.4); font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; }
.network-chip { display: inline-flex; align-items: center; gap: 5px; margin-top: 5px; color: var(--green); font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.12em; }
.network-chip i { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px rgba(52, 211, 153, 0.8); }
.getup-btn { position: absolute; left: 50%; bottom: 128px; transform: translateX(-50%); z-index: 26; display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 13px 30px; border: 2px solid #ffe3a1; border-radius: 12px; background: linear-gradient(135deg, #f7d072, #dca52f); color: #1a1305; font-family: var(--font-display); font-size: 26px; letter-spacing: 0.05em; cursor: pointer; box-shadow: 0 12px 44px rgba(242, 193, 78, 0.4); animation: getupPulse 0.8s infinite; }
.getup-btn span { font-family: var(--font-cond); font-size: 10px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; }
.getup-btn.urgent { background: linear-gradient(135deg, #fb7185, #c4103a); border-color: #ffc2cd; color: #fff; box-shadow: 0 12px 44px rgba(225, 29, 72, 0.45); animation-duration: 0.45s; }
@keyframes getupPulse { 50% { transform: translateX(-50%) scale(1.05); } }
.reconnect-banner { position: absolute; left: 50%; top: 82px; transform: translateX(-50%); z-index: 40; display: flex; align-items: center; gap: 12px; width: min(600px, 93vw); padding: 12px 16px; border: 1px solid rgba(242, 193, 78, 0.4); border-radius: 10px; background: rgba(8, 8, 12, 0.94); box-shadow: var(--shadow); backdrop-filter: blur(10px); pointer-events: auto; }
.reconnect-banner .spinner { width: 24px; height: 24px; margin: 0; flex: none; }
.reconnect-banner b { display: block; font-family: var(--font-cond); font-size: 13px; letter-spacing: 0.05em; }
.reconnect-banner span { display: block; color: var(--muted); font-family: var(--font-cond); font-size: 10px; }
.result-tags { display: flex; justify-content: center; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.result-fighters { display: flex; align-items: center; justify-content: center; gap: 18px; margin: 18px 0; padding: 13px 10px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); text-align: center; }
.result-fighters > div { flex: 1; min-width: 0; }
.result-fighters b { display: block; font-family: var(--font-display); font-size: 25px; line-height: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.result-fighters span { display: block; margin-top: 3px; color: var(--muted); font-family: var(--font-cond); font-size: 10px; letter-spacing: 0.06em; }
.result-rewards { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 16px; }
.reward { padding: 10px 8px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255, 255, 255, 0.025); text-align: center; }
.reward span { display: block; color: var(--muted); font-family: var(--font-cond); font-size: 9px; letter-spacing: 0.11em; text-transform: uppercase; }
.reward b { display: block; margin-top: 3px; color: var(--gold); font-family: var(--font-display); font-size: 22px; line-height: 1.05; }
.reward b.mono { color: var(--muted); }
.touch-controls { opacity: var(--ctrl-opacity, 0.8); transition: opacity 0.2s; }
.touch-controls[data-side="right"] .joystick { left: auto; right: 22px; }
.touch-controls[data-side="right"] .action-pad { right: 18px; left: auto; }
.touch-controls[data-side="left"] .joystick { right: auto; left: 22px; }
.touch-controls[data-side="left"] .action-pad { left: 18px; right: auto; }
.action-pad { transform: scale(var(--btn-scale, 1)); transform-origin: bottom right; }
.touch-controls[data-side="left"] .action-pad { transform-origin: bottom left; }
.act-btn.body { right: 6px; top: 130px; }
.fight-screen.replaying .hud-top,
.fight-screen.replaying .hud-bottom,
.fight-screen.replaying .combo-meter,
.fight-screen.replaying .touch-controls { opacity: 0; pointer-events: none; transition: opacity 0.3s; }
.fight-screen.replaying .fight-ui { pointer-events: none; }

/* --- System flags --- */
body.reduce-motion *, body.reduce-motion *::before, body.reduce-motion *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
body.high-contrast { --line: rgba(255, 255, 255, 0.26); --line2: rgba(255, 255, 255, 0.42); --muted: #c6c4d0; --muted2: #a9a7b5; }
body.high-contrast .screen { background: #050507; }
body.high-contrast .panel, body.high-contrast .stat-tile, body.high-contrast .shop-card { background: #111117; }

@media (max-width: 820px) {
  .form-grid.two { grid-template-columns: 1fr; }
  .alloc-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dossier-body { grid-template-columns: 1fr; gap: 16px; }
  .result-rewards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .host-settings { grid-template-columns: 1fr; }
  .lobby-head { flex-direction: column; }
  .fight-intro-wrap { padding-top: 6px; }
  .getup-btn { bottom: 108px; font-size: 22px; padding: 11px 24px; }
  .reconnect-banner { top: 64px; flex-wrap: wrap; }
}
@media (max-width: 620px) {
  .style-grid, .drill-grid { grid-template-columns: 1fr; }
  .create-shell { padding-bottom: 40px; }
  .offer-card { flex-wrap: wrap; }
  .offer-actions { max-width: none; width: 100%; justify-content: flex-start; }
  .result-fighters b { font-size: 20px; }
  .action-pad { transform: scale(calc(var(--btn-scale, 1) * 0.88)); }
  .touch-controls[data-side="right"] .joystick { right: 12px; bottom: 16px; }
  .touch-controls[data-side="left"] .joystick { left: 12px; bottom: 16px; }
  .touch-controls[data-side="right"] .action-pad { right: 8px; bottom: 12px; }
  .touch-controls[data-side="left"] .action-pad { left: 8px; bottom: 12px; }
}
@media (max-width: 420px) {
  .alloc-grid { grid-template-columns: 1fr; }
  .result-rewards { grid-template-columns: 1fr 1fr; }
}
CSS
