import { chromium } from '/home/runner/work/PlayGround/PlayGround/node_modules/playwright-core/index.mjs';
import fs from 'node:fs';

const out = '/tmp/opencode/shots';
fs.mkdirSync(out, { recursive: true });
const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  args: ['--no-sandbox', '--enable-webgl', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'],
});
const context = await browser.newContext({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const page = await context.newPage();
const logs = [];
page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) logs.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}\n${e.stack || ''}`));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForFunction(() => window.TG_BOXING?.booted, null, { timeout: 30000 });
await page.waitForTimeout(1600);
await page.screenshot({ path: `${out}/01-menu.jpg`, type: 'jpeg', quality: 55 });
console.log('booted', await page.title());
console.log('errors:', JSON.stringify(logs, null, 2));

// Navigate through screens
const screens = ['create', 'rankings', 'news', 'shop', 'gym', 'stats', 'settings', 'multiplayer'];
for (const s of screens) {
  await page.evaluate((name) => window.TG_BOXING.navigate(name), s);
  await page.waitForTimeout(600);
  const info = await page.evaluate(() => ({
    title: document.querySelector('.screen-title')?.textContent?.trim(),
    unknown: document.querySelector('.empty-state b')?.textContent?.trim(),
    height: document.querySelector('.screen')?.scrollHeight,
  }));
  console.log(s, info);
  await page.screenshot({ path: `${out}/02-${s}.jpg`, type: 'jpeg', quality: 55 });
}
console.log('errors after:', JSON.stringify(logs, null, 2));
await browser.close();

